INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西不让别人过去或看不到。", "primary_collocate": null, "pronunciation": "dǎng zhù", "ipa": "tɑŋ˨˩˦ ʈ͡ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "前面的大树挡住了我的视线。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在门口，挡住了我的路。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你让一下，你挡住我了。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一块大木板放在路中间，挡住了行人。", "target_word": "挡住", "complexity_tier": "T3", "furigana": "tā bǎ yí kuài dà mù bǎn fàng zài lù zhōng jiān, dǎng zhù le xíng rén.", "sentence_source": "generated"}, {"text": "他用手挡住了她的眼睛，不让她看见。", "target_word": "挡住", "complexity_tier": "T3", "furigana": "tā yòng shǒu dǎng zhù le tā de yǎn jing, bú ràng tā kàn jiàn.", "sentence_source": "generated"}, {"text": "她用手挡住脸，不让我拍照。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面的人太高，挡住了我看电影。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把门挡住，不让孩子出去。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块大石头挡住了山路。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停在路中间，挡住了其他的车。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挡住了", "label": "体标（了）"}, {"form": "挡不住", "label": "可能补语（否定）"}, {"form": "挡得住", "label": "可能补语（肯定）"}], "register": "中性", "sense_fingerprint": "用东西遮挡或拦住，使人过不去或看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：“挡住”指拦住视线，大树遮住了我的视线，符合句意。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：大树不能拍摄，视线也不能被拍摄。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”要带人作宾语，不能带“视线”作宾语。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”多用于眼睛、镜子，“视线”不能被擦亮。"}], "explanations": {"挡住": "正确：“挡住”指拦住视线，大树遮住了我的视线，符合句意。", "拍摄": "语义：大树不能拍摄，视线也不能被拍摄。", "欢迎": "配价：“欢迎”要带人作宾语，不能带“视线”作宾语。", "擦亮": "搭配：“擦亮”多用于眼睛、镜子，“视线”不能被擦亮。"}, "sentence_index": 0, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挡住了怒气，没有发作。", "explanation": "这里应该用〈压制〉。挡住指用实物或身体拦住人或物，怒气要说“压制”。"}, {"text": "她挡住了朋友的道歉，没有说话。", "explanation": "这里应该用〈接受〉。挡住是拦住，朋友的道歉要说“接受”。"}, {"text": "我挡住了那段最艰难的日子，终于走了过来。", "explanation": "这里应该用〈熬过〉。挡住不能用于一段时间，经历困难时期要说“熬过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：“挡住了我看电影”指前面的人遮住了视线，符合句意。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”要带祝福的对象，不能带“看电影”作宾语。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：前面的人不能叫醒我，句中说的是视线受阻。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”不与“看电影”搭配，句中也没有需要打扮的对象。"}], "explanations": {"挡住": "正确：“挡住了我看电影”指前面的人遮住了视线，符合句意。", "祝贺": "配价：“祝贺”要带祝福的对象，不能带“看电影”作宾语。", "叫醒": "语义：前面的人不能叫醒我，句中说的是视线受阻。", "打扮": "搭配：“打扮”不与“看电影”搭配，句中也没有需要打扮的对象。"}, "sentence_index": 6, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挡住了那个任务，没有完成。", "explanation": "这里应该用〈完成〉。挡住是拦住具体的人或物，任务要说“完成”，不能说挡住。"}, {"text": "他挡住了自己的经历，没有讲给大家。", "explanation": "这里应该用〈讲述〉。挡住针对能被拦住的人或物，经历要说“讲述”。"}, {"text": "他挡住了学校的规定，结果被处罚了。", "explanation": "这里应该用〈遵守〉。挡住是拦住具体的人或物，规定要说“遵守”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这扇门挡不住了风。", "corrected_sentence": "这扇门挡不住风。", "error_description": "错误：“挡不住了风”，可能补语“挡不住”后面不能再加“了”。正确：“挡不住风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在门口挡住着我的路。", "corrected_sentence": "他站在门口挡着我的路。", "error_description": "错误：“挡住着”，结果补语“住”与表示持续的“着”不能同时用在一个动词上。正确：“挡着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们头上高高的大片蓝色，有时有云和星星。", "primary_collocate": null, "pronunciation": "tiān kōng", "ipa": "tʰi̯ɛn˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "今天天空很蓝，我们去公园玩。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空上有几朵白云。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他躺在草地上看天空。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑了，天空出现了星星。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在天空飞得很高。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夕阳把天空染成了红色。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空灰灰的，好像要下雨。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢看天空里的云。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟花照亮了夜晚的天空。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在天空自由地飞。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "头上高高的大片蓝色，有云和星星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”指头上高高的大片蓝色，是本词的正确答案。"}, {"text": "天宫", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头上的蓝色天空。"}, {"text": "天坑", "is_correct": false, "explanation": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。"}, {"text": "挑空", "is_correct": false, "explanation": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}], "explanations": {"天空": "“天空”指头上高高的大片蓝色，是本词的正确答案。", "天宫": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头上的蓝色天空。", "天坑": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。", "挑空": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}, "sentence_index": null, "correct_answer": "天空"}, "level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”指头上高高的大片蓝色，正是“很蓝”所描述的对象。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是绿色的草木环境，不用“很蓝”来形容。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地是绿色的，不会说“今天草地很蓝”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“很蓝”形容颜色，不用来描写作业。"}], "explanations": {"天空": "“天空”指头上高高的大片蓝色，正是“很蓝”所描述的对象。", "花园": "语义：花园是绿色的草木环境，不用“很蓝”来形容。", "草地": "语义：草地是绿色的，不会说“今天草地很蓝”。", "作业": "搭配：“很蓝”形容颜色，不用来描写作业。"}, "sentence_index": 0, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本天空，很好看。", "explanation": "量词错误：天空的量词是“片”，“本”用于书，应说“一片天空”。"}, {"text": "最近天空很好，适合去郊游。", "explanation": "这里应该用〈天气〉。天气指冷暖晴雨等，天空是头顶的空间，不说天空很好。"}, {"text": "山上的天空很新鲜，我们深深呼吸吧。", "explanation": "这里应该用〈空气〉。新鲜形容空气，天空是头顶的空间，不说天空新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”是灰色的，句中说它好像要下雨，指的正是天色。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌的颜色不会用“好像要下雨”来描述，句中说的是天色。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包的颜色与下雨无关，与句中“要下雨”的意思不符。"}, {"text": "作业本", "is_correct": false, "explanation": "搭配：“灰灰的”形容天色时，不用来描写作业本，且与“要下雨”无关。"}], "explanations": {"天空": "“天空”是灰色的，句中说它好像要下雨，指的正是天色。", "课桌": "语义：课桌的颜色不会用“好像要下雨”来描述，句中说的是天色。", "面包": "语义：面包的颜色与下雨无关，与句中“要下雨”的意思不符。", "作业本": "搭配：“灰灰的”形容天色时，不用来描写作业本，且与“要下雨”无关。"}, "sentence_index": 6, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座天空很大，鸟儿在里面飞。", "explanation": "量词错误：“座”用于山、楼等大型物体，天空要用“片”，不说“这座天空”。"}, {"text": "这颗天空很亮，孩子们都在看。", "explanation": "量词错误：“颗”用于星星、珠子等小圆的东西，天空要用“片”，不说“这颗天空”。"}, {"text": "这几天天空特别冷，大家都多穿了衣服。", "explanation": "这里应该用〈天气〉。天气指冷暖晴雨等，天空是头顶的空间，不说天空特别冷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看见一朵天空很蓝。", "corrected_sentence": "我看见一片天空很蓝。", "error_description": "量词错误：天空应用量词“片”，“朵”用于花、云等，应说“一片天空”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢看蓝色地天空。", "corrected_sentence": "我喜欢看蓝色的天空。", "error_description": "“地”放错了：修饰名词要用“的”，应说“蓝色的天空”，不说“蓝色地天空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
