INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理学是研究东西为什么动、为什么掉下来、为什么有颜色的学问。", "primary_collocate": null, "pronunciation": "wù lǐ xué", "ipa": "u⁵¹ li²¹⁴ ɕɥe³⁵", "syllable_count": 3, "sentences": [{"text": "为什么苹果会掉下来？物理学能告诉我们。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问天为什么是蓝的，爸爸说这是物理学。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学告诉我们，东西为什么会掉下来。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹为什么有颜色？物理学可以回答。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明喜欢物理学，因为它能解释很多事。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车为什么会动？物理学里有答案。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学物理学，弄清球为什么会滚。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学课上，我们玩了小球和斜坡。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用物理学解释了影子是怎么来的。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了物理学，我知道风筝为什么能飞。", "target_word": "物理学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理学家", "label": "复合"}, {"form": "物理學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "解释日常现象（动、落下、颜色）的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理学", "is_correct": true, "explanation": "正确：物理学研究物体为什么运动、下落，能解释苹果掉下来的原因。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是知识来源，不能告诉我们道理。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“告诉我们”要求能传递知识的主语，“厨房”不能作这类主语。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能解释苹果为什么掉下来。"}], "explanations": {"物理学": "正确：物理学研究物体为什么运动、下落，能解释苹果掉下来的原因。", "蛋糕": "语义：蛋糕不是知识来源，不能告诉我们道理。", "厨房": "搭配：“告诉我们”要求能传递知识的主语，“厨房”不能作这类主语。", "汽车": "语义：汽车是交通工具，不能解释苹果为什么掉下来。"}, "sentence_index": 0, "correct_answer": "物理学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我舅舅是物理学，每天在实验室工作。", "explanation": "这里应该用〈物理学家〉。物理学指学科，指称人要说“物理学家”。"}, {"text": "老师讲了一只物理学。", "explanation": "这里应该用〈门〉。学科用“门”计量，“只”不用于学科。"}, {"text": "爸爸把物理学放进了冰箱。", "explanation": "语义：物理学是学科，不是物体，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理学", "is_correct": true, "explanation": "正确：物理学解释物体为什么运动，正好对应“弄清球为什么会滚”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史不研究物体运动，与“弄清球为什么会滚”的目的不符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭的技艺，与“弄清球为什么会滚”的目的不符。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“学”后接音乐指学乐器或乐理，但与“弄清球为什么会滚”的解释目的不搭配。"}], "explanations": {"物理学": "正确：物理学解释物体为什么运动，正好对应“弄清球为什么会滚”。", "历史": "语义：历史不研究物体运动，与“弄清球为什么会滚”的目的不符。", "烹饪": "语义：烹饪是做饭的技艺，与“弄清球为什么会滚”的目的不符。", "音乐": "搭配：“学”后接音乐指学乐器或乐理，但与“弄清球为什么会滚”的解释目的不搭配。"}, "sentence_index": 6, "correct_answer": "物理学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水变成冰是物理学变化，不是化学变化。", "explanation": "这里应该用〈物理〉。“物理学”是学科名称，不能修饰“变化”；指物理变化要说“物理”。"}, {"text": "妈妈正在编织物理学，准备送给我。", "explanation": "这里应该用〈研究〉或〈学习〉。“编织”用于毛衣等织物，学问不能编织。"}, {"text": "这块木头的物理学很重。", "explanation": "这里应该用〈性质〉。“物理学”是学科名称，不指木头的重量等物理性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥为了弄清苹果为什么掉下来，选了一张物理学。", "corrected_sentence": "我哥哥为了弄清苹果为什么掉下来，选了一门物理学。", "error_description": "量词错误：学科名词“物理学”应用量词“门”，写成“一张”是错误形式，应改为“一门物理学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想学了物理学，弄清雨为什么会下。", "corrected_sentence": "我想学物理学，弄清雨为什么会下。", "error_description": "错误：“想”表示打算，与表示完成的“了”不能同用，应去掉“了”，说“想学物理学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
