INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面就是脚踩的地方。", "primary_collocate": null, "pronunciation": "dì miàn", "ipa": "ti˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "地面很湿，别滑倒了。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子坐在地面上玩儿。", "target_word": "地面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地面太脏了，我来打扫。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机慢慢落到了地面。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，地面变得很滑。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把书掉在了地面上。", "target_word": "地面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，地面上有一层雪。", "target_word": "地面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间的地面是木头做的。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要把水洒在地面上。", "target_word": "地面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，摸了摸地面。", "target_word": "地面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "地面站", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：人脚踩的地方，地的表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24026, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地面", "is_correct": true, "explanation": "正确。“地面”指人脚踩的地方，即地的表面。"}, {"text": "底面", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是物体的底部表面。"}, {"text": "立面", "is_correct": false, "explanation": "lì 与 dì 声母不同（l 与 d），意思是建筑物的立面，即外形的正面或侧面。"}, {"text": "字面", "is_correct": false, "explanation": "zì 与 dì 声母不同（z 与 d），意思是文字的字面意思。"}], "explanations": {"地面": "正确。“地面”指人脚踩的地方，即地的表面。", "底面": "dǐ（第三声）与 dì（第四声）声调不同，意思是物体的底部表面。", "立面": "lì 与 dì 声母不同（l 与 d），意思是建筑物的立面，即外形的正面或侧面。", "字面": "zì 与 dì 声母不同（z 与 d），意思是文字的字面意思。"}, "sentence_index": null, "correct_answer": "地面"}, "level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "正确。“地面很湿”指脚踩的地方湿了，所以人会滑倒。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不会湿，也不会让人滑倒，句子不通。"}, {"text": "墙面", "is_correct": false, "explanation": "搭配：“墙面”是竖立的面，人不会在墙上滑倒，“滑倒”不搭配“墙面”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被弄湿到让人滑倒，句子不通。"}], "explanations": {"地面": "正确。“地面很湿”指脚踩的地方湿了，所以人会滑倒。", "天空": "语义：天空不会湿，也不会让人滑倒，句子不通。", "墙面": "搭配：“墙面”是竖立的面，人不会在墙上滑倒，“滑倒”不搭配“墙面”。", "空气": "语义：空气不能被弄湿到让人滑倒，句子不通。"}, "sentence_index": 0, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把画挂在了地面上。", "explanation": "这里应该用〈墙面〉。画要挂在墙面上，地面不能挂画。"}, {"text": "小船在地面上漂。", "explanation": "这里应该用〈海面〉。小船漂在海面上，陆地的表面才叫“地面”。"}, {"text": "鱼跳出了地面。", "explanation": "这里应该用〈水面〉。鱼跳出的是水面，地面不是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24026, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地面", "is_correct": true, "explanation": "正确。“地面”指人脚踩的地方，即地的表面。"}, {"text": "四面", "is_correct": false, "explanation": "sì 与 dì 声母不同（s 与 d），意思是四个方向的各个面。"}, {"text": "细面", "is_correct": false, "explanation": "xì 与 dì 声母不同（x 与 d），意思是细的面条或面粉。"}, {"text": "地线", "is_correct": false, "explanation": "dì 相同，xiàn 与 miàn 声母不同（x 与 m），意思是接地用的导线。"}], "explanations": {"地面": "正确。“地面”指人脚踩的地方，即地的表面。", "四面": "sì 与 dì 声母不同（s 与 d），意思是四个方向的各个面。", "细面": "xì 与 dì 声母不同（x 与 d），意思是细的面条或面粉。", "地线": "dì 相同，xiàn 与 miàn 声母不同（x 与 m），意思是接地用的导线。"}, "sentence_index": null, "correct_answer": "地面"}, "level_3": {"options": [{"text": "地面", "is_correct": true, "explanation": "正确。“地面上有一层雪”指脚踩的地方覆盖了雪。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是时间，不能被雪覆盖，句子不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是物体，不能盖上一层雪，句子不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象的概念，不能有一层雪，句子不通。"}], "explanations": {"地面": "正确。“地面上有一层雪”指脚踩的地方覆盖了雪。", "夜晚": "语义：夜晚是时间，不能被雪覆盖，句子不通。", "声音": "语义：声音不是物体，不能盖上一层雪，句子不通。", "时间": "语义：时间是抽象的概念，不能有一层雪，句子不通。"}, "sentence_index": 6, "correct_answer": "地面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "星星挂在地面上，很亮。", "explanation": "这里应该用〈夜空〉。星星挂在天上的夜空，不挂在地面上。"}, {"text": "雨滴从地面滴下来。", "explanation": "这里应该用〈屋檐〉。雨水从屋檐往下滴，不会从地面往下滴。"}, {"text": "这张桌子的地面很光滑。", "explanation": "这里应该用〈桌面〉。地面是脚踩的地方，桌子的表面要说“桌面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里有一只平整的地面。", "corrected_sentence": "院子里有一块平整的地面。", "error_description": "量词错误：地面这样的面用“块”，不用“只”。正确的说法是“一块平整的地面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水流到地面的上了。", "corrected_sentence": "雨水流到地面上了。", "error_description": "错误形式：“地面的上”；正确形式：“地面上”。“上”是方位词，接在“地面”后面时中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
