INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工程师是设计东西或者修机器的人。", "primary_collocate": null, "pronunciation": "gōng chéng shī", "ipa": "kʊŋ˥ ʈʂʰɤŋ˧˥ ʂɨ˥", "syllable_count": 3, "sentences": [{"text": "我哥哥是一名工程师，他在公司设计桥。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在修这台旧机器。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师设计了一座很高的桥。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长大后当工程师，设计新汽车。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后在公司当工程师，每天设计新的机器。", "target_word": "工程师", "complexity_tier": "T3", "furigana": "gōng chéng shī", "sentence_source": "generated"}, {"text": "工程师们在工地上检查新楼。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，公司请来了一位工程师。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸是工程师，常常在工地上忙。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位工程师把图纸给了工人。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了四年，终于成为工程师。", "target_word": "工程师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位工程师", "label": "量词"}, {"form": "一名工程师", "label": "量词"}, {"form": "工程师们", "label": "复数"}, {"form": "软件工程师", "label": "复合词"}], "register": "中性", "sense_fingerprint": "从事设计、建造或修理机器和工程的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医生", "is_correct": false, "explanation": "语义：医生不设计桥，“哥哥是一名医生，在公司设计桥”与职业不符。"}, {"text": "工程师", "is_correct": true, "explanation": "正确：“工程师”指设计或修理机器、工程的专业人员，与“设计桥”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责设计桥梁，与“在公司设计桥”的语境矛盾。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“设计桥”一般由专业技术人员完成，“司机设计桥”搭配不当。"}], "explanations": {"医生": "语义：医生不设计桥，“哥哥是一名医生，在公司设计桥”与职业不符。", "工程师": "正确：“工程师”指设计或修理机器、工程的专业人员，与“设计桥”相符。", "厨师": "语义：厨师不负责设计桥梁，与“在公司设计桥”的语境矛盾。", "司机": "搭配：“设计桥”一般由专业技术人员完成，“司机设计桥”搭配不当。"}, "sentence_index": 0, "correct_answer": "工程师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师每天给病人治病。", "explanation": "这里应该用〈医生〉。工程师负责设计和修理机器，给病人治病要用“医生”。"}, {"text": "工程师在法庭上为客户辩护。", "explanation": "这里应该用〈律师〉。工程师不做法律工作，在法庭上为客户辩护要用“律师”。"}, {"text": "工程师每天给病人打针。", "explanation": "这里应该用〈护士〉。工程师不负责护理病人，给病人打针要用“护士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌手", "is_correct": false, "explanation": "语义：歌手不会修机器，“机器坏了，请来一位歌手”与语境矛盾。"}, {"text": "工程师", "is_correct": true, "explanation": "正确：“工程师”能修理机器，与“机器坏了，公司请来”相符。"}, {"text": "画家", "is_correct": false, "explanation": "语义：画家不负责修理机器，与“机器坏了”的语境不符。"}, {"text": "演员", "is_correct": false, "explanation": "搭配：“机器坏了”要请修理人员，“演员”与修机器搭配不当。"}], "explanations": {"歌手": "语义：歌手不会修机器，“机器坏了，请来一位歌手”与语境矛盾。", "工程师": "正确：“工程师”能修理机器，与“机器坏了，公司请来”相符。", "画家": "语义：画家不负责修理机器，与“机器坏了”的语境不符。", "演员": "搭配：“机器坏了”要请修理人员，“演员”与修机器搭配不当。"}, "sentence_index": 6, "correct_answer": "工程师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我认识一台工程师。", "explanation": "这里应该用〈位〉或〈名〉。“台”用于机器，“工程师”指人，不能用“台”来数。"}, {"text": "公司里有一座工程师。", "explanation": "这里应该用〈位〉或〈名〉。“座”用于山、楼、桥等大型物体，不用于指人。"}, {"text": "我的邻居是一只工程师。", "explanation": "这里应该用〈位〉或〈名〉。“只”用于动物，不用于指人的职业名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐是一名工程师们，她在公司上班。", "corrected_sentence": "我姐姐是一名工程师，她在公司上班。", "error_description": "错误：“一名工程师们”。正确：“一名工程师”。“们”表示复数，不能与数量词“一名”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位工程师们很有名。", "corrected_sentence": "那位工程师很有名。", "error_description": "错误：“那位”是单数指示，不能与表示复数的“们”同用。正确：“那位工程师很有名。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
