INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "引擎是让机器动起来的东西，就像汽车和飞机的心脏。", "primary_collocate": null, "pronunciation": "yǐn qíng", "ipa": "in˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "引擎是汽车的心脏。", "target_word": "引擎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有引擎，汽车就不能走。", "target_word": "引擎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里的机器都有自己的引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，好引擎能让车跑得更远。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆卡车的引擎很有力。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船装上引擎以后，走得快多了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧引擎换成了新的。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引擎一停，飞机就掉下去了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的割草机引擎很吵。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅听了听引擎的声音。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "引擎盖", "label": "复合"}], "register": "中性", "sense_fingerprint": "让机器动起来的核心部件，像汽车、飞机的心脏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是汽车的动力核心，与“心脏”的比喻相符。"}, {"text": "方向盘", "is_correct": false, "explanation": "语义：方向盘负责转向，不是汽车的动力核心，不能比作心脏。"}, {"text": "油箱", "is_correct": false, "explanation": "语义：油箱只储存燃料，不具备动力功能，不能比作心脏。"}, {"text": "座椅", "is_correct": false, "explanation": "搭配：“是……的心脏”一般用于动力或核心部件，座椅不能这样比喻。"}], "explanations": {"引擎": "引擎是汽车的动力核心，与“心脏”的比喻相符。", "方向盘": "语义：方向盘负责转向，不是汽车的动力核心，不能比作心脏。", "油箱": "语义：油箱只储存燃料，不具备动力功能，不能比作心脏。", "座椅": "搭配：“是……的心脏”一般用于动力或核心部件，座椅不能这样比喻。"}, "sentence_index": 0, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一辆引擎。", "explanation": "这里应该用〈台〉。引擎的量词是“台”，“辆”用于车辆。"}, {"text": "这台冰箱的引擎很安静。", "explanation": "这里应该用〈压缩机〉。冰箱的制冷部件叫压缩机，“引擎”一般指汽车、飞机、船等大型动力装置。"}, {"text": "这台缝纫机的引擎转得很快。", "explanation": "这里应该用〈马达〉。缝纫机等小型机器的动力部件通常叫马达，“引擎”一般指汽车、飞机、船等大型动力装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是可以更换的动力部件，与“换成了新的”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以更换的物件，“把旧天空换成新的”句意不成立。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“换”不能用于童年，二者不搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以拆换的物件，句意不成立。"}], "explanations": {"引擎": "引擎是可以更换的动力部件，与“换成了新的”相符。", "天空": "语义：天空不是可以更换的物件，“把旧天空换成新的”句意不成立。", "童年": "搭配：“换”不能用于童年，二者不搭配。", "月亮": "语义：月亮不是可以拆换的物件，句意不成立。"}, "sentence_index": 6, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一颗引擎。", "explanation": "这里应该用〈台〉。“颗”用于粒状或圆形的小东西，引擎的量词是“台”。"}, {"text": "这台电磨的引擎声音很刺耳。", "explanation": "这里应该用〈电机〉。电磨等小型电器的动力部件叫电机，“引擎”一般指大型动力装置。"}, {"text": "这把电钻的引擎转得很快。", "explanation": "这里应该用〈马达〉。电钻等小型电动工具的动力部件通常叫马达，“引擎”一般指大型动力装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆引擎很有力。", "corrected_sentence": "这台引擎很有力。", "error_description": "量词错误：引擎的量词是“台”，“辆”用于车辆。正确说法是“这台引擎很有力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于引擎换新了。", "corrected_sentence": "他终于把引擎换新了。", "error_description": "“把”字句漏用“把”：“换新”的宾语“引擎”前要加“把”，应说“把引擎换新了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
