INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "推东西时用的力。", "primary_collocate": null, "pronunciation": "tuī lì", "ipa": "tʰu̯eɪ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个箱子很重，我的推力不够。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "推车时，推力要向前。", "target_word": "推力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩的推力太小，推不开门。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "推力越大，箱子滑得越远。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "推秋千时，推力不用太大。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人的推力比孩子大得多。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这扇门很重，需要很大的推力。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人一起推，推力就更大了。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车陷在泥里，我加大推力，车还是纹丝不动。", "target_word": "推力", "complexity_tier": "T3", "furigana": "chē xiàn zài ní lǐ, wǒ jiā dà tuīlì, chē hái shì wén sī bú dòng", "sentence_source": "generated"}, {"text": "要想推动大石头，推力必须很大。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "反推力", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手推东西时用的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffb67340-e1c4-4776-99da-c6f147023945') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24040, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指用手推东西时用的力。"}, {"text": "推离", "is_correct": false, "explanation": "推离（tuī lí）与推力的第二音节声调不同（第二声与第四声），意思是推开使其离开。"}, {"text": "对立", "is_correct": false, "explanation": "对立（duì lì）与推力的声母不同（d 与 t），声调也不同（第四声），意思是互相抵触。"}, {"text": "脱力", "is_correct": false, "explanation": "脱力（tuō lì）与推力的韵母不同（ō 与 uī），声调也不同（第二声），意思是失去力气。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指用手推东西时用的力。", "推离": "推离（tuī lí）与推力的第二音节声调不同（第二声与第四声），意思是推开使其离开。", "对立": "对立（duì lì）与推力的声母不同（d 与 t），声调也不同（第四声），意思是互相抵触。", "脱力": "脱力（tuō lì）与推力的韵母不同（ō 与 uī），声调也不同（第二声），意思是失去力气。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：句子说的是我施加在箱子上的力不够，与“推力”相符。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是地球对物体的吸引力，不是人施加的力，“我的重力不够”说不通。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力是阻碍物体运动的力，“我的阻力不够”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人体的温度，“我的体温不够”与推动箱子无关，说不通。"}], "explanations": {"推力": "正确：句子说的是我施加在箱子上的力不够，与“推力”相符。", "重力": "语义：重力是地球对物体的吸引力，不是人施加的力，“我的重力不够”说不通。", "阻力": "语义：阻力是阻碍物体运动的力，“我的阻力不够”说不通。", "体温": "语义：体温指人体的温度，“我的体温不够”与推动箱子无关，说不通。"}, "sentence_index": 0, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的推力很强，能解决很难的数学题。", "explanation": "这里应该用〈能力〉。推力只指推动物体的力，不能用来说人解决问题的本领。"}, {"text": "这根绳子的推力很大，能把箱子拉过来。", "explanation": "这里应该用〈拉力〉。推力指推东西时用的力，把箱子拉过来用的是拉力，不能说推力。"}, {"text": "空气的推力很大，车跑不快。", "explanation": "这里应该用〈阻力〉。推力指推东西时用的力，阻碍车前进的是阻力，不能说推力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24040, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指用手推东西时用的力。"}, {"text": "推理", "is_correct": false, "explanation": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。"}, {"text": "体力", "is_correct": false, "explanation": "体力（tǐ lì）与推力的韵母不同（ǐ 与 uī），声调也不同（第三声），意思是身体的力气。"}, {"text": "腿力", "is_correct": false, "explanation": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指用手推东西时用的力。", "推理": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。", "体力": "体力（tǐ lì）与推力的韵母不同（ǐ 与 uī），声调也不同（第三声），意思是身体的力气。", "腿力": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：门很重，需要很大的力才能推动，与“推力”相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是物体本身的质量，不是需要施加的力，“需要很大的重量”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人体的温度，与推门所需的力无关。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”指声音的大小，不能说“需要很大的音量”来推门。"}], "explanations": {"推力": "正确：门很重，需要很大的力才能推动，与“推力”相符。", "重量": "语义：重量是物体本身的质量，不是需要施加的力，“需要很大的重量”说不通。", "体温": "语义：体温指人体的温度，与推门所需的力无关。", "音量": "搭配：“音量”指声音的大小，不能说“需要很大的音量”来推门。"}, "sentence_index": 6, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车的推力越来越快，很快就到了站。", "explanation": "这里应该用〈速度〉。“越来越快”说的是速度，推力只说大小。"}, {"text": "地球对月亮有推力，月亮才不会飞走。", "explanation": "这里应该用〈引力〉。推力指推东西时用的力，地球吸引月亮不让它飞走的是引力，不能说推力。"}, {"text": "老师对学生很有推力。", "explanation": "这里应该用〈耐心〉。推力指推动物体的力，不能说人对别人“有推力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子很重，需要一只很大的推力。", "corrected_sentence": "这个箱子很重，需要一股很大的推力。", "error_description": "量词错误：推力应用量词“股”，不能用“只”（“只”用于动物、成对事物中的单个等）。正确说法是“一股很大的推力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人一起推，推力比一个人大的多。", "corrected_sentence": "两个人一起推，推力比一个人大得多。", "error_description": "程度补语错误：“大得多”中的“得”误写成“的”。程度补语应用“得”，正确说法是“推力比一个人大得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acda918b-ea72-4467-9c9d-51d5a5c84781') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润说有水分，与表面光滑没有相反关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔说面积大，与表面光不光滑无关。"}, {"text": "结实", "is_correct": false, "explanation": "结实说质地牢固，与表面光滑没有相反关系。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙与光滑意思相反，指表面凹凸不平、有毛刺。", "湿润": "湿润说有水分，与表面光滑没有相反关系。", "宽阔": "宽阔说面积大，与表面光不光滑无关。", "结实": "结实说质地牢固，与表面光滑没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
