INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "摸起来很滑，不平的东西就是光滑。", "primary_collocate": null, "pronunciation": "guāng huá", "ipa": "kwɑŋ˥ xwa˧˥", "syllable_count": 2, "sentences": [{"text": "新买的桌子摸着很光滑。", "target_word": "光滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋的壳很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地板太光滑，我差点摔倒。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块玻璃光滑得像镜子。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩的脸蛋又软又光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水把石头洗得很光滑。", "target_word": "光滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子里外都很光滑。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "磨过的木头特别光滑。", "target_word": "光滑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路面不光滑，骑车很累。", "target_word": "光滑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她用手摸了摸光滑的桌面。", "target_word": "光滑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "光滑的", "label": "定语形式"}, {"form": "光滑了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "摸起来很滑，表面不粗糙不凸起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光滑", "is_correct": true, "explanation": "光滑指摸起来平滑，不粗糙也不凸起。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”说视觉效果，不能用来形容摸着的感觉。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”说体积，与摸起来的感觉无关。"}, {"text": "好听", "is_correct": false, "explanation": "搭配：“好听”说声音，不能用于形容触感。"}], "explanations": {"光滑": "光滑指摸起来平滑，不粗糙也不凸起。", "好看": "搭配：“好看”说视觉效果，不能用来形容摸着的感觉。", "高大": "语义：“高大”说体积，与摸起来的感觉无关。", "好听": "搭配：“好听”说声音，不能用于形容触感。"}, "sentence_index": 0, "correct_answer": "光滑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小伙子的个子很光滑，很会说话。", "explanation": "这里应该用〈高〉。光滑只说物体表面平，不用来形容个子。"}, {"text": "这盏灯的光很光滑，照得整个屋子都亮了。", "explanation": "这里应该用〈明亮〉。光滑形容物体表面，不用来形容光线，明亮的光要说明亮。"}, {"text": "这篇论文的结构很光滑，前后呼应得很好。", "explanation": "这里应该用〈严谨〉。光滑形容物体表面平，不用来形容结构，结构周密、环环相扣要用严谨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光滑", "is_correct": true, "explanation": "光滑指杯子内外表面都平滑。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不形容杯子的表面。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境，不用来说物体表面。"}, {"text": "绵软", "is_correct": false, "explanation": "语义：“绵软”说质地松软，与杯子光滑的表面不相符。"}], "explanations": {"光滑": "光滑指杯子内外表面都平滑。", "清脆": "语义：“清脆”形容声音，不形容杯子的表面。", "寂静": "搭配：“寂静”形容环境，不用来说物体表面。", "绵软": "语义：“绵软”说质地松软，与杯子光滑的表面不相符。"}, "sentence_index": 6, "correct_answer": "光滑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的文章写得很光滑，读起来很顺口。", "explanation": "这里应该用〈流畅〉。光滑只说物体表面，不形容文章，文字通顺、读起来流利要用流畅。"}, {"text": "她的个子很光滑，待人很亲切。", "explanation": "这里应该用〈高〉。光滑只说物体表面平，不用来形容个子。"}, {"text": "这个词的解释很光滑，大家一看就懂。", "explanation": "这里应该用〈清楚〉。光滑指物体表面平，形容解释说明得明白要用清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条木凳擦很光滑。", "corrected_sentence": "这条木凳擦得很光滑。", "error_description": "补语要用“得”连接，“擦很光滑”漏了“得”，正确是“擦得很光滑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他捡起了一块光滑地鹅卵石。", "corrected_sentence": "他捡起了一块光滑的鹅卵石。", "error_description": "修饰名词要用“的”，不用“地”。正确是“光滑的鹅卵石”，“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
