INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24046, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从上往下移动。", "primary_collocate": null, "pronunciation": "xià jiàng", "ipa": "ɕja⁵¹ tɕjaŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "飞机慢慢下降，我看见了城市。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯正在下降，马上到一楼。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球慢慢下降，落在草地上。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的缆车开始下降了。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机下降的时候，我的耳朵很难受。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟慢慢下降，站在窗边。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请等一下，电梯还在下降。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那架无人机慢慢下降，停在桌子上。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞的人慢慢下降，落在草地上。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐缆车下降的时候，风很大。", "target_word": "下降", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下降了", "label": "体标"}, {"form": "下降过", "label": "体标"}], "register": "中性", "sense_fingerprint": "下降：动词，物体从高处往低处移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下降", "is_correct": true, "explanation": "正确答案：下降，指从上往下移动。"}, {"text": "鞋匠", "is_correct": false, "explanation": "xié（第二声）与 xià（第四声）声调不同，意思是做鞋的人。"}, {"text": "虾酱", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，jiàng 相同，意思是虾酱。"}, {"text": "瞎讲", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，jiǎng（第三声）与 jiàng（第四声）声调也不同，意思是胡说。"}], "explanations": {"下降": "正确答案：下降，指从上往下移动。", "鞋匠": "xié（第二声）与 xià（第四声）声调不同，意思是做鞋的人。", "虾酱": "xiā（第一声）与 xià（第四声）声调不同，jiàng 相同，意思是虾酱。", "瞎讲": "xiā（第一声）与 xià（第四声）声调不同，jiǎng（第三声）与 jiàng（第四声）声调也不同，意思是胡说。"}, "sentence_index": null, "correct_answer": "下降"}, "level_3": {"options": [{"text": "下降", "is_correct": true, "explanation": "“下降”指飞机从高处往低处移动，符合句意。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”多指植物、动物的成长，不能说飞机生长。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”的主体须是有生命的人或动物，飞机不能睡觉。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”用于种子、植物，与“飞机”不搭配。"}], "explanations": {"下降": "“下降”指飞机从高处往低处移动，符合句意。", "生长": "搭配：“生长”多指植物、动物的成长，不能说飞机生长。", "睡觉": "语义：“睡觉”的主体须是有生命的人或动物，飞机不能睡觉。", "发芽": "搭配：“发芽”用于种子、植物，与“飞机”不搭配。"}, "sentence_index": 0, "correct_answer": "下降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那架飞机下降在首都机场了。", "explanation": "这里应该用〈降落〉。下降只说从高处往低处移动，飞机着陆要用降落。"}, {"text": "他从公交车上下降了。", "explanation": "这里应该用〈下车〉。下降说位置或数量往下，人离开车要说下车。"}, {"text": "他从床上下降了。", "explanation": "这里应该用〈下床〉。下降说从高处往低处移动，人离开床铺要说下床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下降", "is_correct": true, "explanation": "“下降”指电梯向下移动，符合句意。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”的主体须是人或动物，电梯不能吃饭。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”的主体是人，不能说电梯写字。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”的主体只能是人或动物，电梯不能洗澡。"}], "explanations": {"下降": "“下降”指电梯向下移动，符合句意。", "吃饭": "语义：“吃饭”的主体须是人或动物，电梯不能吃饭。", "写字": "搭配：“写字”的主体是人，不能说电梯写字。", "洗澡": "语义：“洗澡”的主体只能是人或动物，电梯不能洗澡。"}, "sentence_index": 6, "correct_answer": "下降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下降去买东西。", "explanation": "这里应该用〈下楼〉。下降说高度或数量往下，人走下楼梯要用下楼。"}, {"text": "商店决定下降。", "explanation": "这里应该用〈降价〉。下降的主语应是价格、数量等，商店不能作主语下降。"}, {"text": "他突然下降了。", "explanation": "这里应该用〈倒下〉。下降不用于人跌倒，人突然跌倒要说倒下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只风筝下降的很快。", "corrected_sentence": "那只风筝下降得很快。", "error_description": "错误：“下降的很快”，补语标记应为“得”而不是“的”。“得”引出程度补语，说明下降的程度。正确：“下降得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯慢慢下降去一楼。", "corrected_sentence": "电梯慢慢下降到一楼。", "error_description": "补语错误：表示终点的补语应用“到”，不能用“去”，“下降去一楼”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
