INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24076, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "一直做某件事，到某个时间才停下来。", "primary_collocate": null, "pronunciation": "zhí dào", "ipa": "ʈʂɨ˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他一直工作，直到晚上十点才休息。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一直走，直到看见一条河。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到老师进来，教室里才安静下来。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟一直玩手机，直到电池没电了。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直笑，直到肚子都疼了。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会一直学习，直到学会。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到公司关门，他才离开办公室。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人睡了很久，直到中午才醒。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直开车，直到我们到了海边。", "target_word": "直到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直等，直到天亮才离开。", "target_word": "直到", "complexity_tier": "T3", "furigana": "wǒ yìzhí děng, zhídào tiānliàng cái líkāi.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "直到：一直做某事，到某个时间才停止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '328de6f8-a753-46b2-9f72-d875f758cd08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：zhí（第二声）dào，表示一直做某事到某个时间才停止，是正确答案。"}, {"text": "知道", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道，不是直到。"}, {"text": "迟到", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch/zh），意思是迟到。"}, {"text": "指导", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，dǎo（第三声）与 dào（第四声）也不同，意思是指导。"}, {"text": "执导", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是执导（导演影片）。"}], "explanations": {"直到": "直到：zhí（第二声）dào，表示一直做某事到某个时间才停止，是正确答案。", "知道": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道，不是直到。", "迟到": "chí 与 zhí 声母不同（ch/zh），意思是迟到。", "指导": "zhǐ（第三声）与 zhí（第二声）声调不同，dǎo（第三声）与 dào（第四声）也不同，意思是指导。", "执导": "dǎo（第三声）与 dào（第四声）声调不同，意思是执导（导演影片）。"}, "sentence_index": null, "correct_answer": "直到"}, "level_3": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：表示工作一直持续到晚上十点，之后才休息，符合句意。"}, {"text": "自从", "is_correct": false, "explanation": "语义：“自从”表示起点，与“工作到十点才休息”的终点意义相反。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“工作”不是为了“十点才休息”，句意不通。"}, {"text": "从", "is_correct": false, "explanation": "搭配：“从”引出起点，与“才休息”表示终点的句式不搭配。"}], "explanations": {"直到": "直到：表示工作一直持续到晚上十点，之后才休息，符合句意。", "自从": "语义：“自从”表示起点，与“工作到十点才休息”的终点意义相反。", "为了": "语义：“为了”表示目的，“工作”不是为了“十点才休息”，句意不通。", "从": "搭配：“从”引出起点，与“才休息”表示终点的句式不搭配。"}, "sentence_index": 0, "correct_answer": "直到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚出门，直到晚上十点。", "explanation": "这里应该用〈一直〉。直到前面要有一段持续的动作，“刚出门”是瞬间动作，不能持续到某个时间点。"}, {"text": "他直到工作，晚上十点才休息。", "explanation": "这里应该用〈一直〉。直到后面要接时间点，不能接“工作”这样的持续动作。"}, {"text": "他直到早上工作到晚上。", "explanation": "这里应该用〈从〉。直到表示持续到某个时间点，不能表示起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24076, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：zhí（第二声）dào，表示一直做某事到某个时间才停止，是正确答案。"}, {"text": "吃到", "is_correct": false, "explanation": "chī（第一声）与 zhí（第二声）声母不同（ch/zh），声调也不同，意思是吃到。"}, {"text": "实到", "is_correct": false, "explanation": "shí（第二声）与 zhí 声母不同（sh/zh），意思是实际到场，常说“实到人数”。"}, {"text": "制导", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，dǎo 与 dào 也不同，意思是制导。"}, {"text": "只到", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是只到（达）。"}], "explanations": {"直到": "直到：zhí（第二声）dào，表示一直做某事到某个时间才停止，是正确答案。", "吃到": "chī（第一声）与 zhí（第二声）声母不同（ch/zh），声调也不同，意思是吃到。", "实到": "shí（第二声）与 zhí 声母不同（sh/zh），意思是实际到场，常说“实到人数”。", "制导": "zhì（第四声）与 zhí（第二声）声调不同，dǎo 与 dào 也不同，意思是制导。", "只到": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是只到（达）。"}, "sentence_index": null, "correct_answer": "直到"}, "level_3": {"options": [{"text": "直到", "is_correct": true, "explanation": "直到：表示公司关门这个时间点之后，他才离开办公室，符合句意。"}, {"text": "趁着", "is_correct": false, "explanation": "语义：“趁着”表示利用时机，与“公司关门后才离开”的时间终点不符。"}, {"text": "自打", "is_correct": false, "explanation": "语义：“自打”表示起点，与“才离开”的终点意义相反。"}, {"text": "对于", "is_correct": false, "explanation": "搭配：“对于”引出话题，不表示时间的终点，不能与“才离开”搭配。"}], "explanations": {"直到": "直到：表示公司关门这个时间点之后，他才离开办公室，符合句意。", "趁着": "语义：“趁着”表示利用时机，与“公司关门后才离开”的时间终点不符。", "自打": "语义：“自打”表示起点，与“才离开”的终点意义相反。", "对于": "搭配：“对于”引出话题，不表示时间的终点，不能与“才离开”搭配。"}, "sentence_index": 6, "correct_answer": "直到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他直到回家，不去别处。", "explanation": "这里应该用〈直接〉。直到表示持续到某一时间点，不表示径直前往。"}, {"text": "我一按门铃，直到门就开了。", "explanation": "这里应该用〈马上〉。直到前面要有持续的动作，“一按门铃”是瞬间动作。"}, {"text": "我在门口直到了很久，才听见敲门声。", "explanation": "这里应该用〈等〉。直到表示持续到某个时间点，不能作动词表示等待，所以这里不能说直到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看了一下午书，直到晚上十点就吃饭。", "corrected_sentence": "他看了一下午书，直到晚上十点才吃饭。", "error_description": "副词错误：「直到……」表示持续到某个时间点才发生的事，应用「才」；「就」表示紧接着，与「直到」的终点意义不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走了一天，直到傍晚就到家。", "corrected_sentence": "我们走了一天，直到傍晚才到家。", "error_description": "副词错误：「直到……」后面表示到那时才发生的事情，应用「才」；「就」表示紧接着，与「直到」的终点意义不符。正确形式是「直到傍晚才到家」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf7ac19-460f-4443-8fa5-9a9ea809f07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
