INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让东西变得好看、有创意的做法。", "primary_collocate": null, "pronunciation": "yì shù huà", "ipa": "i˥˩ ʂu˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "手工课上，老师示范了纸盒的艺术化做法。", "target_word": "艺术化", "complexity_tier": "T3", "furigana": "shǒu gōng kè shàng, lǎo shī shì fàn le zhǐ hé de yì shù huà zuò fǎ。", "sentence_source": "generated"}, {"text": "这个咖啡杯的艺术化让它很受欢迎。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢房间的艺术化，墙上都是自己画的画。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜的艺术化让吃饭也成了一种享受。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术化的包装让礼物更漂亮。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的艺术化做得很有创意。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对照片做了艺术化处理，看起来像画。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店墙上的艺术化设计吸引了很多人。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要为了艺术化，忘了东西要好用。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，艺术化需要想法，也需要耐心。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艺术化处理", "label": "复合"}, {"form": "藝術化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让东西变得好看、有创意的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神秘化", "is_correct": false, "explanation": "语义：「神秘化」指使事物显得神秘，与示范手工做法的语境不符。"}, {"text": "艺术化", "is_correct": true, "explanation": "正确：「艺术化做法」指让纸盒变得好看、有创意的做法，与句义吻合。"}, {"text": "方言化", "is_correct": false, "explanation": "语义：「方言化」指使事物带上地方方言的色彩，与纸盒的制作做法无关。"}, {"text": "口语化", "is_correct": false, "explanation": "语域：「口语化」指语言通俗、适于口头表达，不能用来修饰「做法」。"}], "explanations": {"神秘化": "语义：「神秘化」指使事物显得神秘，与示范手工做法的语境不符。", "艺术化": "正确：「艺术化做法」指让纸盒变得好看、有创意的做法，与句义吻合。", "方言化": "语义：「方言化」指使事物带上地方方言的色彩，与纸盒的制作做法无关。", "口语化": "语域：「口语化」指语言通俗、适于口头表达，不能用来修饰「做法」。"}, "sentence_index": 0, "correct_answer": "艺术化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师艺术化了班上的人数，结果是四十五人。", "explanation": "这里应该用〈统计〉。「艺术化」指让东西变得好看、有创意，不能用于数字的统计，统计人数应说「统计」。"}, {"text": "他用清水艺术化了这只杯子。", "explanation": "这里应该用〈清洗〉。「艺术化」指让东西变得好看、有创意，用清水去除污渍应说「清洗」，不说「艺术化」。"}, {"text": "他认真艺术化了每一项开支。", "explanation": "这里应该用〈计算〉。「艺术化」指让东西变得好看、有创意，开支的数字运算应说「计算」，不说「艺术化」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实用化", "is_correct": false, "explanation": "语义：「实用化」指使事物便于实际使用，与「看起来像画」的效果相冲突。"}, {"text": "艺术化", "is_correct": true, "explanation": "正确：「艺术化处理」指经艺术手法加工，与「看起来像画」的结果相符。"}, {"text": "数据化", "is_correct": false, "explanation": "语义：「数据化」指转化为数字信息，与「看起来像画」的效果无关。"}, {"text": "石化", "is_correct": false, "explanation": "搭配：「石化」指变成石头，不能用来说照片的处理方式。"}], "explanations": {"实用化": "语义：「实用化」指使事物便于实际使用，与「看起来像画」的效果相冲突。", "艺术化": "正确：「艺术化处理」指经艺术手法加工，与「看起来像画」的结果相符。", "数据化": "语义：「数据化」指转化为数字信息，与「看起来像画」的效果无关。", "石化": "搭配：「石化」指变成石头，不能用来说照片的处理方式。"}, "sentence_index": 6, "correct_answer": "艺术化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头要艺术化，才能变得光滑。", "explanation": "这里应该用〈打磨〉。「艺术化」强调艺术加工使事物好看有创意，使石头变光滑属于物理加工，应说「打磨」。"}, {"text": "会计要艺术化账目，把每笔钱对清楚。", "explanation": "这里应该用〈核对〉。「艺术化」指让东西变得好看、有创意，核对账目是检查数字是否准确，应说「核对」，不说「艺术化」。"}, {"text": "墙上的裂缝需要艺术化，才能不再漏水。", "explanation": "这里应该用〈修补〉。「艺术化」不表示修补裂缝，处理漏水的裂缝应说「修补」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧椅子艺术化很好看。", "corrected_sentence": "他把旧椅子艺术化得很好看。", "error_description": "错误形式：「艺术化」后的补语前漏掉了「得」。正确形式：「艺术化得很好看」。原因：「把……艺术化」后接程度补语时，需要用「得」连接，漏掉后句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把窗帘艺术化。", "corrected_sentence": "她把窗帘艺术化了。", "error_description": "错误形式：「把窗帘艺术化」后缺少「了」。正确形式：「把窗帘艺术化了」。原因：「把」字句中动词后要带「了」或其他补充成分，动作才算完成，句子才完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
