INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一边走到另一边。", "primary_collocate": null, "pronunciation": "chuān xíng", "ipa": "tʂʰuan˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "行人不能在马路上随便穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在车站里来回穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在树林里穿行，很快到了河边。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在两栋楼之间穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫在桌椅之间穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "游客在老街的小巷里穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天骑车在小路上穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在人群里穿行，想找到朋友。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在工地上穿行，要戴安全帽。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在走廊里匆匆穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿行了", "label": "体标"}, {"form": "穿行着", "label": "体标"}, {"form": "穿行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从一边穿过中间走到另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿行", "is_correct": true, "explanation": "正确：行人在马路上从一边走到另一边，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要水体作为环境，马路上不能游泳。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是把植物栽进土地，与行人在马路上的行走无关。"}, {"text": "飞翔", "is_correct": false, "explanation": "语义：行人不能在马路上飞翔，与“随便穿行”的行走语境不符。"}], "explanations": {"穿行": "正确：行人在马路上从一边走到另一边，句意通顺。", "游泳": "搭配：“游泳”需要水体作为环境，马路上不能游泳。", "种植": "语义：种植是把植物栽进土地，与行人在马路上的行走无关。", "飞翔": "语义：行人不能在马路上飞翔，与“随便穿行”的行走语境不符。"}, "sentence_index": 0, "correct_answer": "穿行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿行了两栋楼，很快到了另一边。", "explanation": "这里应该用〈穿过〉。“穿行”通常需用“在……之间／中”引出所经的空间，不宜直接以“两栋楼”为宾语，故用“穿过”。"}, {"text": "这箱子在两栋楼之间穿行。", "explanation": "这里应该用〈搬〉。箱子不能自己移动，穿行的主语须能自行移动。"}, {"text": "他在两栋楼之间穿行了一间小屋。", "explanation": "这里应该用〈盖〉。穿行指从中间通过，不能用来表示建造房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿行", "is_correct": true, "explanation": "正确：我每天骑车在小路上移动着通过，句意通顺。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是对物件进行维修，与骑车在小路上行进的动作不符。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：“播种”需要田地作为对象，小路上不能播种。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是用烤箱做食物，与骑车在小路上行进的情境不符。"}], "explanations": {"穿行": "正确：我每天骑车在小路上移动着通过，句意通顺。", "修理": "语义：修理是对物件进行维修，与骑车在小路上行进的动作不符。", "播种": "搭配：“播种”需要田地作为对象，小路上不能播种。", "烘焙": "语义：烘焙是用烤箱做食物，与骑车在小路上行进的情境不符。"}, "sentence_index": 6, "correct_answer": "穿行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑在走廊里匆匆穿行。", "explanation": "这里应该用〈搬〉。电脑不能自己移动，穿行的主语须能自行移动。"}, {"text": "课堂上穿行着游戏环节。", "explanation": "这里应该用〈穿插〉。穿插指夹杂在其中，穿行指人或物从中间通过，不能用来表示游戏环节夹杂在课堂里。"}, {"text": "学生们在走廊里穿行了一篇作文。", "explanation": "这里应该用〈写〉。穿行指从中间通过，不能用来表示写作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他街道上穿行，去找朋友。", "corrected_sentence": "他在街道上穿行，去找朋友。", "error_description": "缺少介词“在”：表示动作发生的处所要放在动词前，用“在……”引出，应说“在街道上穿行”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们匆匆的穿行在走廊里。", "corrected_sentence": "学生们匆匆地穿行在走廊里。", "error_description": "“地”误用为“的”：副词“匆匆”修饰动词“穿行”，应用“地”，不能用“的”。正确说法是“匆匆地穿行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
