INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气在动，就像风吹过来。", "primary_collocate": null, "pronunciation": "qì liú", "ipa": "tɕʰi˥˩ liou˧˥", "syllable_count": 2, "sentences": [{"text": "门一开，一股气流吹了进来。", "target_word": "气流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，房间里有气流会凉快一点。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗边有一股冷冷的气流。", "target_word": "气流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风扇让屋里的气流动了起来。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山口的气流很急，帽子飞走了。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟张开翅膀，乘着气流往上飞。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感到有气流从脚边走过。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟顺着气流往窗外飘去。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的气流直接吹着我的头。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁来了，隧道里出现一阵气流。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股气流", "label": "量词"}, {"form": "上升气流", "label": "复合"}], "register": "中性", "sense_fingerprint": "空气流动，像风一样吹来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24098, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：气流 qì liú，意思是空气在流动、像风一样吹来。"}, {"text": "细流", "is_correct": false, "explanation": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。"}, {"text": "激流", "is_correct": false, "explanation": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。"}, {"text": "溪流", "is_correct": false, "explanation": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}], "explanations": {"气流": "正确：气流 qì liú，意思是空气在流动、像风一样吹来。", "细流": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。", "激流": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。", "溪流": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}, "sentence_index": null, "correct_answer": "气流"}, "level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“一股气流吹了进来”指空气流动吹进门，与“门一开”的语境相符。"}, {"text": "怒火", "is_correct": false, "explanation": "语义：“怒火”是情绪，不能从门缝里被吹进来。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性情，不能像空气一样被吹进门。"}, {"text": "恨意", "is_correct": false, "explanation": "语义：“恨意”是心理状态，与门开后吹进来的物理动作不符。"}], "explanations": {"气流": "正确：“一股气流吹了进来”指空气流动吹进门，与“门一开”的语境相符。", "怒火": "语义：“怒火”是情绪，不能从门缝里被吹进来。", "脾气": "语义：“脾气”是性情，不能像空气一样被吹进门。", "恨意": "语义：“恨意”是心理状态，与门开后吹进来的物理动作不符。"}, "sentence_index": 0, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把气流倒进了杯子里。", "explanation": "这里应该用〈水〉。气流看不见，倒进杯子的是液体。"}, {"text": "气流落在窗上，发出沙沙的声音。", "explanation": "这里应该用〈雨水〉。雨水才会落在窗上；气流是看不见的流动空气，不会“落在”窗上。"}, {"text": "气流照进屋里。", "explanation": "这里应该用〈阳光〉。阳光才会照进屋里；气流不能用来描述光的照射。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24098, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：气流 qì liú，意思是空气在流动、像风一样吹来。"}, {"text": "逆流", "is_correct": false, "explanation": "逆流 nìliú 的声母 n 与 q 不同，声调相同，意思是向上游流动。"}, {"text": "底流", "is_correct": false, "explanation": "底流 dǐliú 的声母 d 与 q 不同，声调变为第三声，意思是水底的暗流。"}, {"text": "溢流", "is_correct": false, "explanation": "溢流 yìliú 的声母 y 与 q 不同，声调相同，意思是满出来向下流。"}], "explanations": {"气流": "正确：气流 qì liú，意思是空气在流动、像风一样吹来。", "逆流": "逆流 nìliú 的声母 n 与 q 不同，声调相同，意思是向上游流动。", "底流": "底流 dǐliú 的声母 d 与 q 不同，声调变为第三声，意思是水底的暗流。", "溢流": "溢流 yìliú 的声母 y 与 q 不同，声调相同，意思是满出来向下流。"}, "sentence_index": null, "correct_answer": "气流"}, "level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“有气流从脚边走过”指空气在脚边流动，与“走过”的语境相符。"}, {"text": "思绪", "is_correct": false, "explanation": "语义：“思绪”是心理活动，不能从脚边走过。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“走过”的主体应是人或动物，桌子不会走过。"}, {"text": "麦子", "is_correct": false, "explanation": "搭配：麦子不能“走过”，也不会从脚边经过。"}], "explanations": {"气流": "正确：“有气流从脚边走过”指空气在脚边流动，与“走过”的语境相符。", "思绪": "语义：“思绪”是心理活动，不能从脚边走过。", "桌子": "搭配：“走过”的主体应是人或动物，桌子不会走过。", "麦子": "搭配：麦子不能“走过”，也不会从脚边经过。"}, "sentence_index": 6, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "站台上挤满了气流。", "explanation": "这里应该用〈人群〉。站台上挤满的是人群；气流是空气，不能“挤满”站台。"}, {"text": "天边传来一阵气流。", "explanation": "这里应该用〈雷声〉。天边传来的是雷声；气流不是可以“传来”的声响。"}, {"text": "桌上的气流煮得很烂。", "explanation": "这里应该用〈饭菜〉。气流不能煮，煮烂的是饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋角有一颗潮湿的气流。", "corrected_sentence": "屋角有一股潮湿的气流。", "error_description": "错误形式：“一颗潮湿的气流”。正确形式：“一股潮湿的气流”。“气流”要用量词“股”，不能用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气流树梢间穿行。", "corrected_sentence": "气流在树梢间穿行。", "error_description": "错误形式：“气流树梢间穿行”。正确形式：“气流在树梢间穿行”。表示处所时要用“在”引出，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
