INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24100, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某个地方或位置弄到自己手里。", "primary_collocate": null, "pronunciation": "zhàn jù", "ipa": "tʂan˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "他早早占据了第一排的座位。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行李占据了整个后座。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想占据好位置。", "target_word": "占据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗占据了我的床。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们占据了教室后面的角落。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店占据了街角最好的位置。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们占据了公园里的长椅。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要占据别人的座位。", "target_word": "占据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大沙发占据了客厅的一半。", "target_word": "占据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个男孩占据着球场，不让别人玩。", "target_word": "占据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占据了", "label": "体标"}, {"form": "占据着", "label": "体标"}, {"form": "占据过", "label": "体标"}], "register": "中性", "sense_fingerprint": "抢先拿到并霸占某个位置或空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设计", "is_correct": false, "explanation": "语义：「设计」指规划绘制，与「早早」抢先占据座位的语境不符。"}, {"text": "占据", "is_correct": true, "explanation": "正确：「占据」指抢先拿到并占有某个位置，与「早早」「座位」相符。"}, {"text": "融化", "is_correct": false, "explanation": "语义：「融化」指固体变成液体，座位不会被融化，句义不通。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：「点燃」指使物体燃烧，与抢占座位的语境毫不相干。"}], "explanations": {"设计": "语义：「设计」指规划绘制，与「早早」抢先占据座位的语境不符。", "占据": "正确：「占据」指抢先拿到并占有某个位置，与「早早」「座位」相符。", "融化": "语义：「融化」指固体变成液体，座位不会被融化，句义不通。", "点燃": "语义：「点燃」指使物体燃烧，与抢占座位的语境毫不相干。"}, "sentence_index": 0, "correct_answer": "占据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天上班，他都占据这条大街。", "explanation": "这里应该用〈经过〉。「占据」指持续占有某处，只是上班时路过不能用「占据」。"}, {"text": "我占据了他的笔，写完后还给他。", "explanation": "这里应该用〈借用〉。「占据」指把某个地方或位置弄到自己手里并长期占有，借来东西用完归还不能说「占据」。"}, {"text": "客人一进门就占据了这间屋子，随即离开了。", "explanation": "这里应该用〈进入〉。「占据」含持续占有某处之义，不能与「随即离开」搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "语义：「参观」指到某处观看了解，与「占据」所表示的占有义不符，句义不通。"}, {"text": "占据", "is_correct": true, "explanation": "正确：「占据」指把长椅弄到自己手里，与「孩子们」的行为相符。"}, {"text": "咏叹", "is_correct": false, "explanation": "搭配：「咏叹」多用于歌咏某事物或情感，不能用来说对长椅的行为。"}, {"text": "倒卖", "is_correct": false, "explanation": "语义：「倒卖」指低价买进高价卖出，孩子们不会对长椅进行倒卖，句义不通。"}], "explanations": {"参观": "语义：「参观」指到某处观看了解，与「占据」所表示的占有义不符，句义不通。", "占据": "正确：「占据」指把长椅弄到自己手里，与「孩子们」的行为相符。", "咏叹": "搭配：「咏叹」多用于歌咏某事物或情感，不能用来说对长椅的行为。", "倒卖": "语义：「倒卖」指低价买进高价卖出，孩子们不会对长椅进行倒卖，句义不通。"}, "sentence_index": 6, "correct_answer": "占据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用木板占据了破窗户。", "explanation": "这里应该用〈堵住〉。「占据」指把某个地方弄到自己手里，用木板封住窗口不说「占据」。"}, {"text": "几个人占据了球场，又穿过去了。", "explanation": "这里应该用〈经过〉。「占据」指长时间占有某处，几个人只是路过、没有停留，应说「经过」。"}, {"text": "我占据了今天的作业，老师很生气。", "explanation": "这里应该用〈忘记〉。「占据」指把某个地方或位置弄到自己手里，不能用于遗忘作业，应说「忘记」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一进教室就把最后一排占据。", "corrected_sentence": "他一进教室就把最后一排占据了。", "error_description": "错误形式：「把最后一排占据」。正确形式：「把最后一排占据了」。原因：「把」字句的动词后须有补语或「了」等成分，以「占据」结尾句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们占据在那片树荫。", "corrected_sentence": "他们占据了那片树荫。", "error_description": "错误形式：「占据」后直接接了「在」。正确形式：「占据了」。原因：「占据」后应接「了」「着」等动态助词，不能接「在」；改为「占据着那片树荫」也可以。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
