INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机翼是飞机的翅膀。", "primary_collocate": null, "pronunciation": "jī yì", "ipa": "tɕi˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "飞机的机翼又长又宽。", "target_word": "机翼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐在窗边，能看见机翼。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明画了一架飞机，机翼很大。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "降落时机翼上的小板会打开。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机翼上落着一只小鸟。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，机翼上全是水。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架飞机的两个机翼都是白色的。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把模型飞机的机翼粘好了。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞过云层时，机翼有点儿抖。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸飞机的机翼是用硬纸折成的。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对机翼", "label": "量词"}, {"form": "主机翼", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机的翅膀，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机的翅膀，即两侧用来产生升力的部件。"}, {"text": "记忆", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。"}, {"text": "机遇", "is_correct": false, "explanation": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。"}, {"text": "机制", "is_correct": false, "explanation": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。"}, {"text": "饥饿", "is_correct": false, "explanation": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。"}, {"text": "极易", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机的翅膀，即两侧用来产生升力的部件。", "记忆": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。", "机遇": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。", "机制": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。", "饥饿": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。", "极易": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机的翅膀，可以又长又宽。"}, {"text": "车轮", "is_correct": false, "explanation": "体貌：车轮是圆的，不能用“又长又宽”来形容。"}, {"text": "船帆", "is_correct": false, "explanation": "语义：船帆属于帆船，飞机没有船帆。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是飞机的部件，与句中所指不合。"}], "explanations": {"机翼": "正确：机翼是飞机的翅膀，可以又长又宽。", "车轮": "体貌：车轮是圆的，不能用“又长又宽”来形容。", "船帆": "语义：船帆属于帆船，飞机没有船帆。", "桌子": "语义：桌子是家具，不是飞机的部件，与句中所指不合。"}, "sentence_index": 0, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟飞起来时，机翼会上下扇动。", "explanation": "这里应该用〈翅膀〉。机翼专指飞机的翅膀，鸟的翅膀要说“翅膀”。"}, {"text": "风力发电机的机翼在风中转个不停。", "explanation": "这里应该用〈叶片〉。风力发电机的旋转部件叫叶片，机翼专指飞机的翅膀。"}, {"text": "他买了一把机翼，装在模型上。", "explanation": "这里应该用〈个〉或〈对〉。“把”用于有柄的器具，机翼不用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机的翅膀，即两侧用来产生升力的部件。"}, {"text": "机器", "is_correct": false, "explanation": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。"}, {"text": "西翼", "is_correct": false, "explanation": "第一个音节 xī 与 jī 的声母不同（x 对 j），意思是建筑或机构的西侧部分。"}, {"text": "极易", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。"}, {"text": "技艺", "is_correct": false, "explanation": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机的翅膀，即两侧用来产生升力的部件。", "机器": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。", "西翼": "第一个音节 xī 与 jī 的声母不同（x 对 j），意思是建筑或机构的西侧部分。", "极易": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。", "技艺": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机的翅膀，两个机翼都可以是白色的。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：飞机没有耳朵，句中指的是飞机的部件。"}, {"text": "叶子", "is_correct": false, "explanation": "语义：叶子长在植物上，飞机没有叶子，句中不成立。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：花瓣长在花上，飞机不是花，句中不成立。"}], "explanations": {"机翼": "正确：机翼是飞机的翅膀，两个机翼都可以是白色的。", "耳朵": "语义：飞机没有耳朵，句中指的是飞机的部件。", "叶子": "语义：叶子长在植物上，飞机没有叶子，句中不成立。", "花瓣": "语义：花瓣长在花上，飞机不是花，句中不成立。"}, "sentence_index": 6, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架小飞机的机翼转得很快。", "explanation": "这里应该用〈螺旋桨〉。螺旋桨绕轴转动，机翼是固定在机身两侧的翼面，不会转动。"}, {"text": "直升机的机翼飞快地转动。", "explanation": "这里应该用〈旋翼〉。直升机的旋翼绕轴转动，机翼是固定的翼面，不会转动。"}, {"text": "工人修好了一辆机翼。", "explanation": "这里应该用〈个〉或〈对〉。“辆”用于车辆，机翼不是独立的车辆，不能用“辆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光照在飞机地机翼上。", "corrected_sentence": "阳光照在飞机的机翼上。", "error_description": "结构助词错误：“飞机”修饰“机翼”时应用结构助词“的”，说“飞机的机翼上”；“地”多用于修饰动词，此处误用，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人给飞机的两只机翼都刷了漆。", "corrected_sentence": "工人给飞机的两个机翼都刷了漆。", "error_description": "量词错误：机翼成对计量应用“个”或“对”，“两只机翼”错误，应说“两个机翼”。“只”用于动物或成对的器官。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
