INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以在天上飞的东西，像飞机、火箭。", "primary_collocate": null, "pronunciation": "fēi xíng qì", "ipa": "feɪ˥ ɕiŋ˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "飞机是一种飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上有一架飞行器在飞。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个飞行器是我哥哥做的。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩喜欢看天上的飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭也是飞行器，它能飞到太空。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那架飞行器飞得又高又快。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想造一架自己的飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个飞行器很小，可以放在手上。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行器从机场起飞了。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看过很多飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一架飞行器", "label": "量词"}, {"form": "无人飞行器", "label": "复合"}], "register": "中性", "sense_fingerprint": "天上飞的东西，如飞机、火箭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba539e2-997b-4cf4-8bc9-f8e1b6a4200e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞行器", "is_correct": true, "explanation": "正确。“飞机是一种飞行器”中，“飞行器”是飞机所属的类别，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：飞机不是食物，不能说“飞机是一种食物”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：飞机是飞行的机械，不是乐器，不能说“飞机是一种乐器”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是一种”后应接可归类的事物名称，“颜色”是属性词，不能用来归类飞机。"}], "explanations": {"飞行器": "正确。“飞机是一种飞行器”中，“飞行器”是飞机所属的类别，符合句意。", "食物": "语义：飞机不是食物，不能说“飞机是一种食物”。", "乐器": "语义：飞机是飞行的机械，不是乐器，不能说“飞机是一种乐器”。", "颜色": "搭配：“是一种”后应接可归类的事物名称，“颜色”是属性词，不能用来归类飞机。"}, "sentence_index": 0, "correct_answer": "飞行器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "表姐在航空公司当飞行器。", "explanation": "这里应该用〈飞行员〉。“飞行器”是机器，不能当职业。"}, {"text": "我在天上看见一朵飞行器。", "explanation": "这里应该用〈架〉。飞行器用量词“架”，“朵”多用于花、云等。"}, {"text": "我每天骑飞行器上学。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车等，飞行器应说“驾驶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞行器", "is_correct": true, "explanation": "正确。“造一架自己的”后接的是机械类物件，飞行器符合句意。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“架”不用于书，应说“一本书”，“造一架自己的书”不成立。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“架”不用于房子，应说“一座房子”，“造一架自己的房子”不成立。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱出来的作品，不能被“造”成机械式的物件，量词也不是“架”。"}], "explanations": {"飞行器": "正确。“造一架自己的”后接的是机械类物件，飞行器符合句意。", "书": "搭配：量词“架”不用于书，应说“一本书”，“造一架自己的书”不成立。", "房子": "搭配：量词“架”不用于房子，应说“一座房子”，“造一架自己的房子”不成立。", "歌": "语义：歌是唱出来的作品，不能被“造”成机械式的物件，量词也不是“架”。"}, "sentence_index": 6, "correct_answer": "飞行器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在食堂吃过很多飞行器。", "explanation": "这里应该用〈点心〉。“吃”的对象是食物，飞行器不能吃。"}, {"text": "他在院子里种了很多飞行器。", "explanation": "这里应该用〈花〉。“种”用于植物，飞行器不能种。"}, {"text": "我每天读飞行器。", "explanation": "这里应该用〈报纸〉。“读”的对象是文字材料，飞行器不能被阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候最想拥有一只飞行器。", "corrected_sentence": "他小时候最想拥有一架飞行器。", "error_description": "量词错误：飞行器应使用量词“架”，不能用“只”。“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这架飞行器已经飞远着。", "corrected_sentence": "这架飞行器已经飞远了。", "error_description": "体标错误：“飞远”表示动作已完成并有了结果，应用“了”表示完成；“着”表示持续的状态，与这一完成结果不搭配。应说“这架飞行器已经飞远了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd009fd0f-7132-43de-89a2-308f53041d57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
