INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "曲率是描述一个东西弯曲了多少的数值。", "primary_collocate": null, "pronunciation": "qū lǜ", "ipa": "tɕʰy˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "曲率可以告诉我们东西有多弯。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根铁丝的曲率很大。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路越弯，曲率就越大。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在黑板上画了两条曲率不同的线。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平的桌面，曲率是零。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小球的曲率比大球大。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请算一算这个圆的曲率。", "target_word": "曲率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弯道的曲率太大，车要慢一点。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑算出了这条曲线的曲率。", "target_word": "曲率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼镜片的曲率不一样，看东西也不一样。", "target_word": "曲率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲率半径", "label": "复合"}, {"form": "平均曲率", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示一个东西弯了多少的数值，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曲率", "is_correct": true, "explanation": "正确。“曲率”表示东西弯了多少，能说明东西有多弯。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色的深浅不能说明东西弯曲的程度。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量与弯曲程度无关，不能用来说明东西有多弯。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“有多弯”需要表示弯曲程度的量作主语，“温度”不能与之搭配。"}], "explanations": {"曲率": "正确。“曲率”表示东西弯了多少，能说明东西有多弯。", "颜色": "语义：颜色的深浅不能说明东西弯曲的程度。", "重量": "语义：重量与弯曲程度无关，不能用来说明东西有多弯。", "温度": "搭配：“有多弯”需要表示弯曲程度的量作主语，“温度”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "曲率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯的曲率很亮。", "explanation": "这里应该用〈亮度〉。亮用于光线的明暗，曲率是弯曲程度的数值，不说亮暗。"}, {"text": "这袋米的曲率是五公斤。", "explanation": "这里应该用〈重量〉。曲率是弯曲程度的数值，不以公斤计量。"}, {"text": "这朵花的曲率很深。", "explanation": "这里应该用〈颜色〉。颜色才用“深”来形容，曲率不说深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曲率", "is_correct": true, "explanation": "正确。“算”的对象可以是弯曲程度的数值，曲率能计算。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“算”一般用于数值，味道不能用“算”来处理。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：圆没有脾气，“算一算这个圆的脾气”不合逻辑。"}, {"text": "心情", "is_correct": false, "explanation": "语义：圆没有心情，这个说法与几何对象不相关。"}], "explanations": {"曲率": "正确。“算”的对象可以是弯曲程度的数值，曲率能计算。", "味道": "搭配：“算”一般用于数值，味道不能用“算”来处理。", "脾气": "语义：圆没有脾气，“算一算这个圆的脾气”不合逻辑。", "心情": "语义：圆没有心情，这个说法与几何对象不相关。"}, "sentence_index": 6, "correct_answer": "曲率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "从家到学校的曲率是两公里。", "explanation": "这里应该用〈路程〉。路程用公里计量，曲率不表示距离。"}, {"text": "这辆车的曲率很快。", "explanation": "这里应该用〈速度〉。快慢只用于速度，曲率不能说快。"}, {"text": "这杯水的曲率很高。", "explanation": "这里应该用〈温度〉。温度的高低用“高、低”，曲率用大小描述，不说高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块镜片的曲率突然变大着。", "corrected_sentence": "这块镜片的曲率突然变大了。", "error_description": "体标错误：“变大”是已经完成的变化，应用“了”，不能用“着”。“着”表示动作或状态的持续，应改为“这块镜片的曲率突然变大了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这个圆的曲率算出去了。", "corrected_sentence": "我把这个圆的曲率算出来了。", "error_description": "补语错误：“算出来”表示算得结果，不能说“算出去”。“去”表示离开，应改为“我把这个圆的曲率算出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
