INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "把两个东西放在一起看，找出不一样的地方。", "primary_collocate": null, "pronunciation": "xiāng bǐ zhī xià", "ipa": "ɕiaŋ˥ pi˨˩ ʈʂɻ̩˥ ɕia˥˩", "syllable_count": 4, "sentences": [{"text": "这两本书都不错，相比之下，红色的更有意思。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房间很小，相比之下，朋友的房间大多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果五块一斤，相比之下，香蕉便宜一些。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路去学校，相比之下，我骑车快多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，相比之下，昨天没有风。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐很高，相比之下，妹妹矮一点。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很窄，相比之下，那条路宽多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里人很多，相比之下，河边安静得多。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做的菜太咸了，相比之下，妈妈做的刚好。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李学了三年汉语，相比之下，我才学了三个月。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把两样东西放在一起比较，指出它们不同的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：把两本书放在一起比较，指出红色的更有意思。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，句中是两本书的比较，不是因果关系。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示由此导致的结果，与比较两本书的语境不符。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接前面的动作，后面不接表示比较的分句。"}], "explanations": {"相比之下": "相比之下：把两本书放在一起比较，指出红色的更有意思。", "因此": "语义：“因此”表示因果，句中是两本书的比较，不是因果关系。", "因而": "语义：“因而”表示由此导致的结果，与比较两本书的语境不符。", "于是": "搭配：“于是”承接前面的动作，后面不接表示比较的分句。"}, "sentence_index": 0, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先吃午饭，相比之下去散步了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有可以比较的对象，不用“相比之下”。"}, {"text": "天气很热，相比之下，我们决定在家吹空调。", "explanation": "这里应该用〈因此〉。前后是因果关系，没有比较两者。"}, {"text": "我去邮局，相比之下寄了一封信。", "explanation": "这里应该用〈顺便〉。寄信只是顺带做的事，不是比较两者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：引出后一分句，与前面一条路窄的情况对比，指出另一条路更宽。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示并列或递进，前后一窄一宽，不能这样相接。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此达到的结果，与一窄一宽的对比不符。"}, {"text": "进而", "is_correct": false, "explanation": "语域：“进而”偏书面语，表示递进，与前后的对比关系不符。"}], "explanations": {"相比之下": "相比之下：引出后一分句，与前面一条路窄的情况对比，指出另一条路更宽。", "而且": "语义：“而且”表示并列或递进，前后一窄一宽，不能这样相接。", "从而": "语义：“从而”表示由此达到的结果，与一窄一宽的对比不符。", "进而": "语域：“进而”偏书面语，表示递进，与前后的对比关系不符。"}, "sentence_index": 6, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相比之下，他先去了银行。", "explanation": "这里应该用〈首先〉。句首没有可以比较的前文，这里只是先后顺序。"}, {"text": "妈妈做完饭，相比之下，去叫爸爸吃饭。", "explanation": "这里应该用〈接着〉。前后是先后动作，不是比较两者。"}, {"text": "她连续熬夜，相比之下，生病了。", "explanation": "这里应该用〈结果〉。前后是因果关系，不是比较两者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家面包店很大，相比之下了，那家小多了。", "corrected_sentence": "这家面包店很大，相比之下，那家小多了。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“了”，应去掉“了”，写作“相比之下，”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑得很快，相比之下的，我跑得慢多了。", "corrected_sentence": "他跑得很快，相比之下，我跑得慢多了。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“的”，应去掉“的”，写作“相比之下，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
