INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里觉得不舒服，像有东西压着。", "primary_collocate": null, "pronunciation": "yā lì", "ipa": "ja˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我心里有压力，吃不下饭。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快要考试了，我觉得压力很大。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想让孩子有压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力太大的时候，我就去跑步。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话给了我很大的压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说没有压力，其实心里很紧张。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次上台，她感到很大的压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡不着，是因为压力太大。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别给自己太多压力，慢慢来。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了新学校，他有点压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "壓力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心理上的沉重、不舒服的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指心里沉重、不舒服的感觉，与“吃不下饭”相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，不能指心里的感受。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“心里”通常搭配感受、情绪类词语，不搭“温度”。"}, {"text": "高度", "is_correct": false, "explanation": "语义：高度指高低，与心里不舒服的感受无关。"}], "explanations": {"压力": "压力：指心里沉重、不舒服的感觉，与“吃不下饭”相符。", "体重": "语义：体重指身体的重量，不能指心里的感受。", "温度": "搭配：“心里”通常搭配感受、情绪类词语，不搭“温度”。", "高度": "语义：高度指高低，与心里不舒服的感受无关。"}, "sentence_index": 0, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的压力太暗了，我不想穿。", "explanation": "这里应该用〈颜色〉。“压力”指心里觉得不舒服，不指衣服的颜色。"}, {"text": "他的压力是经理，管理三个部门。", "explanation": "这里应该用〈职位〉。“压力”指心里觉得不舒服，不指工作的职务；说职务要用“职位”。"}, {"text": "这张桌子的压力是木头做的。", "explanation": "这里应该用〈材料〉。“压力”指心里觉得不舒服，不指桌子用的东西；说制作物品的原料要用“材料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指心里的沉重、紧张感，与“感到”搭配，符合句意。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供玩耍的物品，不能作为“感到”的对象，与心理感受不符。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“感到”后接感受类词语，“亮度”是物理属性，搭配不当。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积指平面的大小，不能作为“感到”的对象。"}], "explanations": {"压力": "压力：指心里的沉重、紧张感，与“感到”搭配，符合句意。", "玩具": "语义：玩具是供玩耍的物品，不能作为“感到”的对象，与心理感受不符。", "亮度": "搭配：“感到”后接感受类词语，“亮度”是物理属性，搭配不当。", "面积": "语义：面积指平面的大小，不能作为“感到”的对象。"}, "sentence_index": 6, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她心里充满了压力的歌声。", "explanation": "这里应该用〈欢快〉。“压力”指心里觉得不舒服，不指歌声的风格；形容歌声的感觉要用“欢快”。"}, {"text": "他从压力店买了一个杯子。", "explanation": "这里应该用〈商店〉。“压力”指心里觉得不舒服，不指店铺；说买东西的地方要用“商店”。"}, {"text": "他买了一支压力，用来写字。", "explanation": "这里应该用〈钢笔〉。“压力”指心里觉得不舒服，不指写字的工具；说写字的工具要用“钢笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近他心里的压力大得很很。", "corrected_sentence": "最近他心里的压力大得很。", "error_description": "重复错误：“大得很”中的“很”不能重复，程度补语只用一个“很”，应写作“压力大得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她第一次上台时感到着很大的压力。", "corrected_sentence": "她第一次上台时感到了很大的压力。", "error_description": "了／着误用：“感到”后表示已经发生的感受要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。两者相比，“较小”与“较大”相对，指体积或数量较低的一个。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音，与“较大”的比较义没有相对关系。"}, {"text": "直率", "is_correct": false, "explanation": "“直率”形容性格，与“较大”没有相对关系。"}, {"text": "珍贵", "is_correct": false, "explanation": "“珍贵”形容价值，与“较大”的比较义不构成反义。"}], "correct_answer": "较小", "explanations": {"较小": "正确。两者相比，“较小”与“较大”相对，指体积或数量较低的一个。", "清脆": "“清脆”形容声音，与“较大”的比较义没有相对关系。", "直率": "“直率”形容性格，与“较大”没有相对关系。", "珍贵": "“珍贵”形容价值，与“较大”的比较义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。两者相比，“较小”与“较大”相对，指程度或数量较低的一个。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度，与“较大”的比较义不构成反义。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”形容含水少，与“较大”没有相对关系。"}], "correct_answer": "较小", "explanations": {"较小": "正确。两者相比，“较小”与“较大”相对，指程度或数量较低的一个。", "轻松": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。", "冷淡": "“冷淡”形容态度，与“较大”的比较义不构成反义。", "干燥": "“干燥”形容含水少，与“较大”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西比另一个更多、更大。", "primary_collocate": null, "pronunciation": "jiào dà", "ipa": "tɕjɑʊ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "两个苹果里，我要较大的那个。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个箱子，较大的一个放书。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把较大的盘子拿给我。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟分到了较大的一块蛋糕。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了两条鱼，较大的一条做汤。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个西瓜里，较大的那个更甜。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两袋米，较大的那袋我来提。", "target_word": "较大", "complexity_tier": "T3", "furigana": "zhè liǎng dài mǐ, jiào dà de nà dài wǒ lái tí.", "sentence_source": "generated"}, {"text": "书架上的书，较大的放下层。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了两个包里较大的那个。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "较大的杯子给爸爸，较小的给我。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "較大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在两个事物中比较，指其中体积或数量更大的那一个，如“较大的那个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ea6797-318b-42b7-a7d7-5ecd5fb5d5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。两个苹果相比，较大的那个就是体积更大的那个。"}, {"text": "较年轻", "is_correct": false, "explanation": "语义：苹果没有年龄，“较年轻的那个”与苹果不相配。"}, {"text": "较聪明", "is_correct": false, "explanation": "语义：苹果不具有智力，这一比较在句中不成立。"}, {"text": "较古老", "is_correct": false, "explanation": "语义：苹果不谈古老，“较古老的那个”不合语境。"}], "explanations": {"较大": "正确。两个苹果相比，较大的那个就是体积更大的那个。", "较年轻": "语义：苹果没有年龄，“较年轻的那个”与苹果不相配。", "较聪明": "语义：苹果不具有智力，这一比较在句中不成立。", "较古老": "语义：苹果不谈古老，“较古老的那个”不合语境。"}, "sentence_index": 0, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个碗，颜色较大的那个是我的。", "explanation": "这里应该用〈较深〉。颜色的深浅用“深”，“较大”不指颜色。"}, {"text": "两个孩子，性格较大的那个更爱说话。", "explanation": "这里应该用〈较外向〉。性格的倾向用“外向、内向”描述，“较大”不说性格。"}, {"text": "两个人练字，姿势较大的那个写得更好。", "explanation": "这里应该用〈较标准〉。姿势的规范程度用“标准”描述，“较大”不说姿势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。两袋米相比，较大的那袋指体积或重量更大的一袋。"}, {"text": "较甜", "is_correct": false, "explanation": "语义：米袋不能用甜淡来区分，句中没有味道的语境。"}, {"text": "较香", "is_correct": false, "explanation": "语义：米袋不能用香味来比较，与句子不符。"}, {"text": "较热", "is_correct": false, "explanation": "语义：米袋在两者之间的比较不说冷热，“较热的那袋”不合语境。"}], "explanations": {"较大": "正确。两袋米相比，较大的那袋指体积或重量更大的一袋。", "较甜": "语义：米袋不能用甜淡来区分，句中没有味道的语境。", "较香": "语义：米袋不能用香味来比较，与句子不符。", "较热": "语义：米袋在两者之间的比较不说冷热，“较热的那袋”不合语境。"}, "sentence_index": 6, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两首歌，节奏较大的那首更好听。", "explanation": "这里应该用〈较快〉。节奏的快慢用“快、慢”描述，“较大”不说节奏。"}, {"text": "两个孩子，表情较大的那个很凶。", "explanation": "这里应该用〈较凶〉。表情用“凶、和”描述，“较大”不说表情。"}, {"text": "两块布，质地较大的那块是丝的。", "explanation": "这里应该用〈较软〉。质地的软硬用“软、硬”描述，“较大”不说质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个盘子里，我要较大那个。", "corrected_sentence": "这两个盘子里，我要较大的那个。", "error_description": "“的”遗漏：“较大”修饰“那个”，中间要加结构助词“的”，应说“较大的那个”，不能直接说“较大那个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把较大的那块饼干了弟弟。", "corrected_sentence": "妈妈把较大的那块饼干给了弟弟。", "error_description": "漏掉动词：“把”字句中的动词“给”不能省略，应说“妈妈把较大的那块饼干给了弟弟”，不能说“把……了弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44e15e2c-ef43-46c1-b37a-25b5aef6e00f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较快", "is_correct": true, "explanation": "「较快」与「较慢」在速度义项上互为反义。"}, {"text": "柔软", "is_correct": false, "explanation": "「柔软」形容质地，与「较慢」的速度义无关，不构成反义。"}, {"text": "厚重", "is_correct": false, "explanation": "「厚重」形容分量或质感，与「较慢」的速度义无关，不构成反义。"}, {"text": "清脆", "is_correct": false, "explanation": "「清脆」形容声音，与「较慢」的速度义无关，不构成反义。"}], "correct_answer": "较快", "explanations": {"较快": "「较快」与「较慢」在速度义项上互为反义。", "柔软": "「柔软」形容质地，与「较慢」的速度义无关，不构成反义。", "厚重": "「厚重」形容分量或质感，与「较慢」的速度义无关，不构成反义。", "清脆": "「清脆」形容声音，与「较慢」的速度义无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
