INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几个力合成后剩下的力量，即合力。", "primary_collocate": null, "pronunciation": "jìng lì", "ipa": "tɕiŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "推力比摩擦力大，剩下的净力让车动起来。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力量互相抵消后，剩下的就是净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边拉的力和右边拉的力一样大，净力是零。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船向前的力减去水的阻力，就是船的净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "净力为零，桌上的书就不会动。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的净力很小，所以走得很慢。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球受到向下的净力，所以往下掉。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "净力的方向，就是物体开始动的方向。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出箱子受到的净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个力方向相反时，要先相减，才能得到净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "淨力", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物理通俗说法：相互抵消后剩下的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：净力指几个力合成后剩下的力量。"}, {"text": "经历", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是经历。"}, {"text": "精力", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是精力。"}, {"text": "敬礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是敬礼。"}], "explanations": {"净力": "正确：净力指几个力合成后剩下的力量。", "经历": "jīng（第一声）与 jìng（第四声）声调不同，意思是经历。", "精力": "jīng（第一声）与 jìng（第四声）声调不同，意思是精力。", "敬礼": "lǐ（第三声）与 lì（第四声）声调不同，意思是敬礼。"}, "sentence_index": null, "correct_answer": "净力"}, "level_3": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：剩下的净力能让车动起来，符合句意。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力与运动方向相反，不能让车动起来，与句中“让车动起来”相矛盾。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：距离是长度，不能作让车动起来的力，不说剩下的距离让车动。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：重量是物体的属性，不能让车动起来，与“剩下的”搭配不当。"}], "explanations": {"净力": "正确：剩下的净力能让车动起来，符合句意。", "阻力": "语义：阻力与运动方向相反，不能让车动起来，与句中“让车动起来”相矛盾。", "距离": "搭配：距离是长度，不能作让车动起来的力，不说剩下的距离让车动。", "重量": "搭配：重量是物体的属性，不能让车动起来，与“剩下的”搭配不当。"}, "sentence_index": 0, "correct_answer": "净力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只鸟的净力很快，一下子就飞走了。", "explanation": "这里应该用〈速度〉。净力指力的大小与方向，不表示快慢；说快慢要用〈速度〉。"}, {"text": "他的净力很大，一拳就把门打开了。", "explanation": "用法错误：净力是物理概念，指作用在物体上的合力，不用于说人的力气；人的力气应说〈力气〉。"}, {"text": "这首歌的净力很响亮。", "explanation": "用法错误：净力是力的概念，不用于描述声音；说声音大小要用〈音量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24132, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：净力指几个力合成后剩下的力量。"}, {"text": "尽力", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是尽力。"}, {"text": "劲力", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是力量。"}, {"text": "近利", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是眼前的利益。"}], "explanations": {"净力": "正确：净力指几个力合成后剩下的力量。", "尽力": "jìn 与 jìng 韵尾不同（n 与 ng），意思是尽力。", "劲力": "jìn 与 jìng 韵尾不同（n 与 ng），意思是力量。", "近利": "jìn 与 jìng 韵尾不同（n 与 ng），意思是眼前的利益。"}, "sentence_index": null, "correct_answer": "净力"}, "level_3": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：向下的净力使小球往下掉，符合句意。"}, {"text": "浮力", "is_correct": false, "explanation": "语义：浮力通常向上，与句中的“向下”相矛盾。"}, {"text": "升力", "is_correct": false, "explanation": "语义：升力方向向上，与句中的“向下”相矛盾。"}, {"text": "惯性", "is_correct": false, "explanation": "搭配：惯性不是力，不能说成向下的力。"}], "explanations": {"净力": "正确：向下的净力使小球往下掉，符合句意。", "浮力": "语义：浮力通常向上，与句中的“向下”相矛盾。", "升力": "语义：升力方向向上，与句中的“向下”相矛盾。", "惯性": "搭配：惯性不是力，不能说成向下的力。"}, "sentence_index": 6, "correct_answer": "净力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先算出收入减去成本，才能得到公司的净力。", "explanation": "这里应该用〈净利润〉。净力是力学概念，指合力；收入减成本得到的是净利润。"}, {"text": "这个产品的净力很好，所以很多人买。", "explanation": "用法错误：净力是力学概念，不用于说产品质量；说质量好应说〈质量〉。"}, {"text": "这节课的净力很长，同学们都累了。", "explanation": "用法错误：净力是力的概念，不能用来说时间长短；说课的时长应说〈时长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆小车受到的净力小得很慢，所以慢慢动。", "corrected_sentence": "这辆小车受到的净力很小，所以慢慢动。", "error_description": "错误：“小得很慢”。正确：“很小”。净力的大小用“很小”，“小得”后要接表示程度的补语，不能接“很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车受到地净力越小，走得就越慢。", "corrected_sentence": "车受到的净力越小，走得就越慢。", "error_description": "错误：“受到地净力”，“的”写成了“地”。正确：“受到的净力”，“的”连接定语“受到”与“净力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
