INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "一物与另一物相交，成正正的直角。", "primary_collocate": null, "pronunciation": "chuí zhí yú", "ipa": "ʈʂʰweɪ˧˥ ʈʂɨ˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "黑板的边垂直于地面。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条马路垂直于那条大街，路口是直角。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树干垂直于地面生长。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "横线垂直于竖线，看起来像十字。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗框垂直于墙面，装得很正。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把尺子垂直于纸边放好。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门打开到九十度时，就垂直于墙了。", "target_word": "垂直于", "complexity_tier": "T3", "furigana": "mén dǎkāi dào jiǔshí dù shí, jiù chuízhí yú qiáng le.", "sentence_source": "generated"}, {"text": "柱子垂直于地面，房子才稳。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木棍垂直于地面插在土里。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画时，让这条线垂直于纸的下边。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垂直於", "label": "繁体"}, {"form": "垂直线", "label": "复合"}], "register": "书面", "sense_fingerprint": "日常：一物与另一物正正相交成直角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814f0f11-8914-4749-b4fd-b94e137a1f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垂直于", "is_correct": true, "explanation": "正确：黑板的边与地面成直角，所以说垂直于地面。"}, {"text": "穿过", "is_correct": false, "explanation": "语义：穿过表示从一侧穿到另一侧，黑板的边不会穿进地面。"}, {"text": "围绕", "is_correct": false, "explanation": "搭配：围绕要求环绕一个中心，不能说黑板的边围绕地面。"}, {"text": "绕过", "is_correct": false, "explanation": "语义：绕过表示避开障碍，黑板的边与地面之间没有绕行的意思。"}], "explanations": {"垂直于": "正确：黑板的边与地面成直角，所以说垂直于地面。", "穿过": "语义：穿过表示从一侧穿到另一侧，黑板的边不会穿进地面。", "围绕": "搭配：围绕要求环绕一个中心，不能说黑板的边围绕地面。", "绕过": "语义：绕过表示避开障碍，黑板的边与地面之间没有绕行的意思。"}, "sentence_index": 0, "correct_answer": "垂直于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈垂直于孩子，一起坐在沙发上。", "explanation": "这里应该用〈靠近〉。垂直只用于两条线或两个面成直角，不用来说人与人的远近。"}, {"text": "我们俩的意见垂直于对方。", "explanation": "用法错误：垂直不表示意见对立；意见相反应说〈相反〉。"}, {"text": "这座塔垂直于山顶。", "explanation": "用法错误：垂直说两者成直角，不表示位置在正上方；塔在山顶的正上方应说〈正上方〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垂直于", "is_correct": true, "explanation": "正确：门打开到九十度时与墙成直角，所以说垂直于墙。"}, {"text": "背对", "is_correct": false, "explanation": "搭配：背对的对象要能面向或背朝，门不说背对墙。"}, {"text": "平行于", "is_correct": false, "explanation": "语义：九十度时门与墙成直角，不是平行，与句中的“九十度”相矛盾。"}, {"text": "倾斜于", "is_correct": false, "explanation": "语义：倾斜表示不成直角，与句中的“九十度”相矛盾。"}], "explanations": {"垂直于": "正确：门打开到九十度时与墙成直角，所以说垂直于墙。", "背对": "搭配：背对的对象要能面向或背朝，门不说背对墙。", "平行于": "语义：九十度时门与墙成直角，不是平行，与句中的“九十度”相矛盾。", "倾斜于": "语义：倾斜表示不成直角，与句中的“九十度”相矛盾。"}, "sentence_index": 6, "correct_answer": "垂直于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗垂直于主人，一直跟着跑。", "explanation": "用法错误：垂直只用于线与线、线与面成直角，不用于动物与人的位置关系；这里应说〈靠近〉。"}, {"text": "红色垂直于蓝色，所以这幅画很好看。", "explanation": "用法错误：垂直不用于颜色对比；颜色相互对照应说〈对比〉。"}, {"text": "这场比赛中，两队垂直于对方。", "explanation": "用法错误：垂直不表示比赛中的对抗；两队对抗应说〈对抗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根木棍要垂直于于地面插进土里。", "corrected_sentence": "这根木棍要垂直于地面插进土里。", "error_description": "错误：“垂直于于地面”，“于”重复。正确：“垂直于地面”，“垂直于”只用一个“于”引出对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块板子垂直于了地面立着，才不会倒。", "corrected_sentence": "这块板子垂直于地面立着，才不会倒。", "error_description": "错误：“垂直于了地面”，“了”加在“垂直于”后面。正确：“垂直于地面立着”，描述状态，不带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861da8b1-d554-4dd2-924c-0cdcec2a8d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
