INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以流动的东西，比如水、牛奶、空气。", "primary_collocate": null, "pronunciation": "liú tǐ", "ipa": "ljou˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "水是流体。", "target_word": "流体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "牛奶是一种流体，可以倒进杯子里。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气也是流体，虽然我们看不见。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "流体会从高的地方流向低的地方。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个瓶子里装的是什么流体？", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把流体倒进杯子，它会变成杯子的形状。", "target_word": "流体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水和冷水都是流体。", "target_word": "流体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "石头不是流体，它不会流动。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "流体放在桌子上会慢慢流开。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在课上认识了几种流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "流體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "流体：可以流动的东西，如水、牛奶、空气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，水不是石头，“水是石头”与事实不符。"}, {"text": "流体", "is_correct": true, "explanation": "正确。水是液体，属于可以流动的流体。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是”后面要跟表示事物类别的名词，颜色是属性，不能说“水是颜色”。"}, {"text": "固体", "is_correct": false, "explanation": "语义：水是液体，不是固体，“水是固体”与事实不符。"}], "explanations": {"石头": "语义：石头是固体，水不是石头，“水是石头”与事实不符。", "流体": "正确。水是液体，属于可以流动的流体。", "颜色": "搭配：“是”后面要跟表示事物类别的名词，颜色是属性，不能说“水是颜色”。", "固体": "语义：水是液体，不是固体，“水是固体”与事实不符。"}, "sentence_index": 0, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上要穿一件流体。", "explanation": "这里应该用〈衣服〉。流体会流动，不能穿；能穿的东西要用〈衣服〉。"}, {"text": "流体有四条腿，能稳稳地站在地上。", "explanation": "这里应该用〈椅子〉。流体能流动、没有固定形状，有四条腿、能站稳的东西要用〈椅子〉。"}, {"text": "这种流体食物很硬，老人和病人都咬不动。", "explanation": "这里应该用〈硬糖〉。流体会流动，不会硬到咬不动；咬不动的硬东西要用〈硬糖〉这类固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金属", "is_correct": false, "explanation": "语义：金属是固体，热水和冷水都不是金属，句子说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”是属性，不能说“热水和冷水都是温度”，它们属于流体这一类。"}, {"text": "流体", "is_correct": true, "explanation": "正确。热水和冷水都是液体，属于可以流动的流体。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是固体，热水和冷水不是木头，句子与事实不符。"}], "explanations": {"金属": "语义：金属是固体，热水和冷水都不是金属，句子说不通。", "温度": "搭配：“温度”是属性，不能说“热水和冷水都是温度”，它们属于流体这一类。", "流体": "正确。热水和冷水都是液体，属于可以流动的流体。", "木头": "语义：木头是固体，热水和冷水不是木头，句子与事实不符。"}, "sentence_index": 6, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰箱里的流体硬邦邦的。", "explanation": "这里应该用〈冰〉。流体会流动，说“硬邦邦的”要用〈冰〉这种固态的水。"}, {"text": "流体放在窗台上，会自己跳起来。", "explanation": "这里应该用〈青蛙〉。流体只会流动，不会自己跳起来；会自己跳的东西要用〈青蛙〉。"}, {"text": "我用手能抓起流体，装进口袋里带回家。", "explanation": "这里应该用〈石子〉。流体能流动，抓不起来，能装进口袋的小块硬物要用〈石子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯热牛奶是一种会慢慢流动流体。", "corrected_sentence": "这杯热牛奶是一种会慢慢流动的流体。", "error_description": "错误：“会慢慢流动”修饰“流体”时，中间要加结构助词“的”，应说“会慢慢流动的流体”。漏掉“的”，定语与中心词之间没有连接，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在桌上摆出了几种流体们，让大家观察。", "corrected_sentence": "老师在桌上摆出了几种流体，让大家观察。", "error_description": "错误：“几种”已经表示数量，“流体”是物质名词，后面不能再加“们”，应说“几种流体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
