INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把意思或原因说清楚。", "primary_collocate": null, "pronunciation": "jiě shì", "ipa": "tɕjɛ˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师给我们解释了这个词。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你解释一下为什么迟到。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有解释，只是笑了笑。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来解释这道题怎么做。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈耐心地解释着原因。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你解释得太快，我没听懂。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向大家解释了自己的想法。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很复杂，不好解释。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生解释了药该怎么吃。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把迟到的原因解释清楚了。", "target_word": "解释", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解释了", "label": "体标"}, {"form": "解释着", "label": "体标"}, {"form": "解释过", "label": "体标"}, {"form": "解释一下", "label": "动量"}], "register": "中性", "sense_fingerprint": "说明意思或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebd53f51-cdf0-46b6-96dd-99270f958475') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解释", "is_correct": true, "explanation": "正确：解释指把意思说清楚，与“给我们……这个词”相符。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，与“给我们……这个词”的讲授之意不符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”的对象是人或行为，不能表扬“这个词”。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”多用于人或事物的优点，不说赞美“这个词”。"}], "explanations": {"解释": "正确：解释指把意思说清楚，与“给我们……这个词”相符。", "删除": "语义：“删除”指去掉，与“给我们……这个词”的讲授之意不符。", "表扬": "语义：“表扬”的对象是人或行为，不能表扬“这个词”。", "赞美": "搭配：“赞美”多用于人或事物的优点，不说赞美“这个词”。"}, "sentence_index": 0, "correct_answer": "解释"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于解释了绳子。", "explanation": "这里应该用〈解开〉。解释指把意思说清楚，不能用于绳子，解开才是松开绳结。"}, {"text": "工人解释了机器。", "explanation": "这里应该用〈拆解〉。拆解指把机器拆开，解释只用于说明意思，不能用于机器。"}, {"text": "冬天过去，河水终于解释了。", "explanation": "这里应该用〈解冻〉。解冻指冰雪融化，解释只用于说明意思，不能用于河水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解释", "is_correct": true, "explanation": "正确：解释指把意思说清楚，与“向大家……自己的想法”相符。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物品，不说搬运“自己的想法”。"}, {"text": "调查", "is_correct": false, "explanation": "搭配：“调查”的对象是事实或情况，不说调查“自己的想法”。"}, {"text": "感觉", "is_correct": false, "explanation": "搭配：“感觉”的宾语多为感受或事物，不说感觉“想法”。"}], "explanations": {"解释": "正确：解释指把意思说清楚，与“向大家……自己的想法”相符。", "搬运": "搭配：“搬运”的对象是有形的物品，不说搬运“自己的想法”。", "调查": "搭配：“调查”的对象是事实或情况，不说调查“自己的想法”。", "感觉": "搭配：“感觉”的宾语多为感受或事物，不说感觉“想法”。"}, "sentence_index": 6, "correct_answer": "解释"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司解释了他。", "explanation": "这里应该用〈解雇〉。解释指说清道理，不能用于辞退人员，解雇才是让人离职。"}, {"text": "这个乐队被解释了。", "explanation": "这里应该用〈解散〉。解散指团体不再存在，解释指把意思说清楚，不能用于团体，“被解释”也说不通。"}, {"text": "消防员解释了被困的人。", "explanation": "这里应该用〈解救〉。解救指把被困的人救出来，解释不能用于救人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这件事解释很清楚。", "corrected_sentence": "他把这件事解释得很清楚。", "error_description": "“解释得很清楚”中，补语前必须加助词“得”；应说“解释得很清楚”，不说“解释很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把道理解释了。", "corrected_sentence": "他把道理解释清楚了。", "error_description": "“把”字句中动词后需有补语等成分，“解释”后应接补语“清楚”，说“把道理解释清楚了”；“把道理解释了”结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e535a1-3d00-41a4-8a35-d6188aee7aa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
