INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "静压是液体或气体不动时的压力。", "primary_collocate": null, "pronunciation": "jìng yā", "ipa": "tɕiŋ˥˩ ja˥˥", "syllable_count": 2, "sentences": [{"text": "水不流动时，管子里只有静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不动的时候，水管里的压力叫静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用仪器测量水管里的静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水深越大，水的静压就越大。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎里空气不动，它的压力就是静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹在管口上有动压，风停了只剩静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表能显示管道的静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池里的水不动，底部的静压很大。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机外面的空气有静压，也有动压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把水管里的静压降低了。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "静压力", "label": "复合"}], "register": "书面", "sense_fingerprint": "液体或气体不动时的压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静压", "is_correct": true, "explanation": "正确：静压指液体或气体不动时的压力。"}, {"text": "静雅", "is_correct": false, "explanation": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。"}, {"text": "惊讶", "is_correct": false, "explanation": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。"}, {"text": "精雅", "is_correct": false, "explanation": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。"}, {"text": "惊呀", "is_correct": false, "explanation": "jīng yā（第一声）与 jìng yā（第四声）首字声调不同，意思是惊叹的声音。"}], "explanations": {"静压": "正确：静压指液体或气体不动时的压力。", "静雅": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。", "惊讶": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。", "精雅": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。", "惊呀": "jīng yā（第一声）与 jìng yā（第四声）首字声调不同，意思是惊叹的声音。"}, "sentence_index": null, "correct_answer": "静压"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：管子里不会只有“颜色”，与“水不流动时”的情境不符。"}, {"text": "墙纸", "is_correct": false, "explanation": "语义：管子里不会只有“墙纸”，与流体的压力无关。"}, {"text": "静压", "is_correct": true, "explanation": "正确：水不流动时，管子里只有液体的静压。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，书面的物理描述中不这样指代压力。"}], "explanations": {"颜色": "语义：管子里不会只有“颜色”，与“水不流动时”的情境不符。", "墙纸": "语义：管子里不会只有“墙纸”，与流体的压力无关。", "静压": "正确：水不流动时，管子里只有液体的静压。", "玩意儿": "语域：“玩意儿”是口语，书面的物理描述中不这样指代压力。"}, "sentence_index": 0, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这股水流的静压很猛。", "explanation": "这里应该用〈动压〉。水流冲击的猛劲属于动压；静压指液体或气体不动时的压力，不能形容冲击的猛烈。"}, {"text": "他心里的静压很大。", "explanation": "这里应该用〈压力〉。静压只指液体或气体的物理压力，不指人的心理压力。"}, {"text": "这杯水的静压很烫。", "explanation": "这里应该用〈温度〉。静压指液体或气体不动时的压力，不能用来说冷热；水的冷热要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "语义：管道没有脾气，“显示”的对象应是压力，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：管道的味道与压力无关，句意不通。"}, {"text": "静压", "is_correct": true, "explanation": "正确：这个表能显示管道里液体或气体的静压。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，与书面的仪表说明不协调，也不指压力。"}], "explanations": {"脾气": "语义：管道没有脾气，“显示”的对象应是压力，句意不通。", "味道": "语义：管道的味道与压力无关，句意不通。", "静压": "正确：这个表能显示管道里液体或气体的静压。", "八卦": "语域：“八卦”是口语，与书面的仪表说明不协调，也不指压力。"}, "sentence_index": 6, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "管子里水的静压很快。", "explanation": "这里应该用〈流速〉。静压是压力，不能描述水流的快慢。"}, {"text": "这个箱子的静压很大。", "explanation": "这里应该用〈体积〉。静压指液体或气体的压力，箱子是固体，不说静压。"}, {"text": "这盏灯的静压很高。", "explanation": "这里应该用〈亮度〉。静压指液体或气体的压力，灯的明暗要用亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根管子里的静压很降低了。", "corrected_sentence": "这根管子里的静压降低了。", "error_description": "错误：「很」只修饰形容词或状态词，不能直接修饰动词「降低」；表示已经降低应说「降低了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管子里的静压升下来了。", "corrected_sentence": "管子里的静压升起来了。", "error_description": "补语错误：压力上升应说“升起来”；“下来”表示向下，不能与“升”搭配，应改为“升起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
