INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大家都很喜欢的、很好的。", "primary_collocate": null, "pronunciation": "jīng diǎn", "ipa": "tɕiŋ˥˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌很经典，大家都喜欢听。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部老电影真经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个红色的包设计很经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件经典的黑色裙子。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的味道很经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经典的老歌，我听过很多遍。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的画面很经典，所以很多人玩过。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话太经典了，大家都记住了。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的经典蛋糕最好卖。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的笑话很经典，我们都笑了。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经典作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容事物很好、深受大家喜爱、有代表性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确答案。经典 jīng diǎn，形容事物很好、深受大家喜爱。"}, {"text": "景点", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。"}, {"text": "清点", "is_correct": false, "explanation": "qīng 与 jīng 声母不同，意思是清查、点数。"}, {"text": "星点", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是星星般的小点。"}], "explanations": {"经典": "正确答案。经典 jīng diǎn，形容事物很好、深受大家喜爱。", "景点": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。", "清点": "qīng 与 jīng 声母不同，意思是清查、点数。", "星点": "xīng 与 jīng 声母不同，意思是星星般的小点。"}, "sentence_index": null, "correct_answer": "经典"}, "level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「这首歌很经典」表示很好、深受大家喜爱，与后句「大家都喜欢听」一致。"}, {"text": "冷门", "is_correct": false, "explanation": "语义：「冷门」指少人关注、不受欢迎，与「大家都喜欢听」相反。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：「无聊」是负面评价，与「大家都喜欢听」矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：「粗糙」多形容质地、表面，不用来评价歌曲，与「大家都喜欢听」也不协调。"}], "explanations": {"经典": "正确。「这首歌很经典」表示很好、深受大家喜爱，与后句「大家都喜欢听」一致。", "冷门": "语义：「冷门」指少人关注、不受欢迎，与「大家都喜欢听」相反。", "无聊": "语义：「无聊」是负面评价，与「大家都喜欢听」矛盾。", "粗糙": "搭配：「粗糙」多形容质地、表面，不用来评价歌曲，与「大家都喜欢听」也不协调。"}, "sentence_index": 0, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部游戏的剧情很经典，玩家都觉得是烂剧情。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，用来形容大家都觉得烂的剧情不合适，此处应改用〈糟糕〉。"}, {"text": "这位科学家很经典，所以大家都不认识他。", "explanation": "这里应该用〈著名〉。「经典」一般不用来形容人，且“很经典，所以大家都不认识他”前后矛盾，应说“很著名，大家都认识他”。"}, {"text": "这家餐厅的服务很经典，客人都投诉了。", "explanation": "这里误用了〈经典〉。「经典」表示事物很好、大家都喜欢，与「客人都投诉」矛盾，服务差应说〈糟糕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「画面很经典」表示很好、深受喜爱，与「很多人玩过」一致。"}, {"text": "难看", "is_correct": false, "explanation": "语义：「难看」是负面评价，与「很多人玩过」的受欢迎之意矛盾。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：「低劣」表示质量差，与「很多人玩过」矛盾。"}, {"text": "呆板", "is_correct": false, "explanation": "体貌：「呆板」多形容神态、外观僵硬，不符合对画面的正面评价，与「很多人玩过」也不协调。"}], "explanations": {"经典": "正确。「画面很经典」表示很好、深受喜爱，与「很多人玩过」一致。", "难看": "语义：「难看」是负面评价，与「很多人玩过」的受欢迎之意矛盾。", "低劣": "语义：「低劣」表示质量差，与「很多人玩过」矛盾。", "呆板": "体貌：「呆板」多形容神态、外观僵硬，不符合对画面的正面评价，与「很多人玩过」也不协调。"}, "sentence_index": 6, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告很经典，所以老板把它扔进了垃圾桶。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，报告被扔掉说明它不受欢迎，此处应改用〈糟糕〉之类的评价。"}, {"text": "这种设计已经经典了，大家都不喜欢。", "explanation": "这里应该用〈陈旧〉。「经典」表示很好、深受喜爱，不能用来形容过时、不受欢迎的设计。"}, {"text": "这家饭店的菜很经典，客人都很失望。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，与「客人都很失望」矛盾，此处应改用〈难吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影没经典，但我看了三遍。", "corrected_sentence": "这部电影不经典，但我看了三遍。", "error_description": "否定词错误：形容词「经典」的否定一般用「不」，说「不经典」；「没」多与动词或「有」搭配，「没经典」不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部老片很的经典，我们都爱看。", "corrected_sentence": "这部老片很经典，我们都爱看。", "error_description": "助词错误：「很」修饰形容词「经典」时不加「的」，应说「很经典」，不说「很的经典」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
