INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同部分合在一起。", "primary_collocate": null, "pronunciation": "zōng hé", "ipa": "tsʊŋ˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他把几个小故事综合成一个长故事。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这三张表的数据综合起来，做一个统计。", "target_word": "综合", "complexity_tier": "T3", "furigana": "zōng hé", "sentence_source": "generated"}, {"text": "老师综合了同学们的想法。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先综合各组的结果，再写总结。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书综合了中西方的做法。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把两个办法综合起来用。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把所有意见综合一下，再做决定。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李综合三个人的说法，找到了原因。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案综合了大家的优点。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他综合过各家的长处，形成自己的风格。", "target_word": "综合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "综合了", "label": "体标（了）"}, {"form": "综合过", "label": "体标（过）"}, {"form": "綜合", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把不同的部分合成一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合", "is_correct": true, "explanation": "“综合成一个长故事”表示把几个小故事合成一个，与句意相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是分解，与“合成一个长故事”的方向相反。"}, {"text": "分割", "is_correct": false, "explanation": "语义：分割会得到多个部分，不能合成一个长故事。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切成”针对实物或片段，不能把几个故事切成一个长故事。"}], "explanations": {"综合": "“综合成一个长故事”表示把几个小故事合成一个，与句意相符。", "拆": "语义：“拆”是分解，与“合成一个长故事”的方向相反。", "分割": "语义：分割会得到多个部分，不能合成一个长故事。", "切": "搭配：“切成”针对实物或片段，不能把几个故事切成一个长故事。"}, "sentence_index": 0, "correct_answer": "综合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先综合一下教室，再开会。", "explanation": "这里应该用〈收拾〉。综合用于结果、意见等抽象内容，整理教室要用收拾。"}, {"text": "他把书综合在桌上。", "explanation": "这里应该用〈摆放〉。综合指把抽象内容合成整体，书的摆放是空间位置上的安排，应用摆放。"}, {"text": "他把一个苹果综合了一下，又吃了。", "explanation": "这里应该用〈切〉。综合要把多个部分合成整体，把一个苹果切开应用切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合", "is_correct": true, "explanation": "“综合一下”表示把意见整理合并，再做决定，与句意相符。"}, {"text": "无视", "is_correct": false, "explanation": "语义：无视意见就谈不上综合，与“再做决定”的前提矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除意见后，就没有可以综合的内容了。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”针对实物，不能用于“意见”的整理。"}], "explanations": {"综合": "“综合一下”表示把意见整理合并，再做决定，与句意相符。", "无视": "语义：无视意见就谈不上综合，与“再做决定”的前提矛盾。", "删除": "语义：删除意见后，就没有可以综合的内容了。", "烧": "搭配：“烧”针对实物，不能用于“意见”的整理。"}, "sentence_index": 6, "correct_answer": "综合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他综合了一种风格。", "explanation": "这里应该用〈挑选〉。综合要把多个部分合成整体，只选一种风格不能用综合，应用挑选。"}, {"text": "工人综合了旧房子。", "explanation": "这里应该用〈拆〉。综合用于抽象内容的合并，拆除旧房子应用拆。"}, {"text": "他在海边综合了一些贝壳。", "explanation": "这里应该用〈捡〉。综合指把抽象部分合成整体，捡拾贝壳这类实物应用捡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要把两张表的数据综合起去。", "corrected_sentence": "我们要把两张表的数据综合起来。", "error_description": "错误：“综合起去”；正确：“综合起来”。“起来”是结果补语，表示合在一起形成整体，“起去”不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他综合了过各家的看法。", "corrected_sentence": "他综合过各家的看法。", "error_description": "“了”和“过”不能同时用在同一个动词后面，应说“综合过”，不能说“综合了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示指向上面那个方向。"}, {"text": "慢慢", "is_correct": false, "explanation": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。"}, {"text": "突然", "is_correct": false, "explanation": "突然表示出乎意料地发生，与方向无关，不构成反义。"}, {"text": "立刻", "is_correct": false, "explanation": "立刻表示马上，说的是时间，与向下没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示指向上面那个方向。", "慢慢": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。", "突然": "突然表示出乎意料地发生，与方向无关，不构成反义。", "立刻": "立刻表示马上，说的是时间，与向下没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示指向上面那个方向。"}, {"text": "不断", "is_correct": false, "explanation": "不断表示持续、接连不停，与方向无关，不是向下的反义词。"}, {"text": "缓缓", "is_correct": false, "explanation": "缓缓形容动作慢，与方向无关，不构成反义。"}, {"text": "立即", "is_correct": false, "explanation": "立即表示马上，说的是时间，与向下没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示指向上面那个方向。", "不断": "不断表示持续、接连不停，与方向无关，不是向下的反义词。", "缓缓": "缓缓形容动作慢，与方向无关，不构成反义。", "立即": "立即表示马上，说的是时间，与向下没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指向下面那个方向。", "primary_collocate": null, "pronunciation": "xiàng xià", "ipa": "ɕjɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "箭头向下，表示要往下走。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手心向下，放在桌子上。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志的方向向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上的箭头都向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那朵花的头向下，好像没力气。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指向下，指着地图。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的小三角向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞的口向下，雨水会流出来。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝙蝠睡觉时头向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的喷嘴向下，正在给花园浇水。", "target_word": "向下", "complexity_tier": "T3", "furigana": "zhè tái jī qì de pēn zuǐ xiàng xià zhèng zài gěi huā yuán jiāo shuǐ", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "朝向下面的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向下", "is_correct": true, "explanation": "xiàng xià 意思是指向下面那个方向。"}, {"text": "乡下", "is_correct": false, "explanation": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。"}, {"text": "线下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。"}, {"text": "现下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}], "explanations": {"向下": "xiàng xià 意思是指向下面那个方向。", "乡下": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。", "线下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。", "现下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}, "sentence_index": null, "correct_answer": "向下"}, "level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "“向下”指箭头指向低处，与后半句“表示要往下走”一致。"}, {"text": "向上", "is_correct": false, "explanation": "语义：箭头向上指的是往上走，与“表示要往下走”矛盾。"}, {"text": "朝左", "is_correct": false, "explanation": "语义：箭头指左，指向的不是下面，与“表示要往下走”不符。"}, {"text": "指右", "is_correct": false, "explanation": "语义：“指右”指朝右边，与“表示要往下走”的意思不符。"}], "explanations": {"向下": "“向下”指箭头指向低处，与后半句“表示要往下走”一致。", "向上": "语义：箭头向上指的是往上走，与“表示要往下走”矛盾。", "朝左": "语义：箭头指左，指向的不是下面，与“表示要往下走”不符。", "指右": "语义：“指右”指朝右边，与“表示要往下走”的意思不符。"}, "sentence_index": 0, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的飞机向下飞，离地越来越远。", "explanation": "这里应该用〈向上〉。离地越来越远是朝上飞，不能用向下。"}, {"text": "他向下买了一本书。", "explanation": "这里不用〈向下〉，直接说“买”即可。“向下”表示朝低处，与买书的动作无关。"}, {"text": "我们向下商量这个问题吧。", "explanation": "这里应该用〈往下〉，表示接着说下去。向下只表示朝低处的方向，不能用来表示接着商量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "“向下”指小三角的指向是低处，与句子描述一致。"}, {"text": "向外", "is_correct": false, "explanation": "语义：小三角朝外指的是向外的方向，与句中所说的下方指向不符。"}, {"text": "向左", "is_correct": false, "explanation": "语义：小三角指向左边，与句中的下方指向不符。"}, {"text": "朝右", "is_correct": false, "explanation": "语义：小三角指向右边，与句中的下方指向不符。"}], "explanations": {"向下": "“向下”指小三角的指向是低处，与句子描述一致。", "向外": "语义：小三角朝外指的是向外的方向，与句中所说的下方指向不符。", "向左": "语义：小三角指向左边，与句中的下方指向不符。", "朝右": "语义：小三角指向右边，与句中的下方指向不符。"}, "sentence_index": 6, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书向下搬到了楼上。", "explanation": "这里应该用〈向上〉。搬到楼上是朝高处，不能用向下。"}, {"text": "他仰头向下看着天空。", "explanation": "这里应该用〈向上〉。仰头看天空是朝上看，不能用向下。"}, {"text": "妈妈向下炒了一盘菜。", "explanation": "这里不用〈向下〉，直接说“炒”即可。“向下”表示朝低处，与炒菜的动作无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路牌上的箭头在向下，提示前面有台阶。", "corrected_sentence": "路牌上的箭头向下，提示前面有台阶。", "error_description": "错误：“在向下”；正确：“向下”。“在”后面要接动词表示正在进行，“箭头在向下”缺少动词；“向下”直接描述“箭头”的朝向，不需要“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吊灯的灯罩很向下，光线照在桌子上。", "corrected_sentence": "吊灯的灯罩向下，光线照在桌子上。", "error_description": "错误：“很向下”；正确：“向下”。“向下”表示朝向，不能受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
