INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "飞机或小鸟飞行时，身体和风的方向之间有一个角度，这个角度叫攻角。", "primary_collocate": null, "pronunciation": "gōng jiǎo", "ipa": "kʊŋ˥ tɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小鸟飞行时，身体和风有一个攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰张开翅膀，改变了攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸飞机的攻角太大，会掉下来。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "攻角合适，飞机才能飞得高。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从前面吹来，攻角就变小了。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟抬高头，攻角变大了。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生在课上学习了什么是攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，攻角比平时大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这个攻角有多大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "飞行物身体与风向之间的角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“身体和风有一个攻角”指飞行物身体与风向之间的夹角，与句意相符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度说明运动的快慢，不是身体与风之间的夹角。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离说明两者之间的远近，不是两者方向之间的角度。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与身体和风的方向关系无关，不能表示二者之间的角度。"}], "explanations": {"攻角": "“身体和风有一个攻角”指飞行物身体与风向之间的夹角，与句意相符。", "速度": "语义：速度说明运动的快慢，不是身体与风之间的夹角。", "距离": "语义：距离说明两者之间的远近，不是两者方向之间的角度。", "温度": "语义：温度与身体和风的方向关系无关，不能表示二者之间的角度。"}, "sentence_index": 0, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶的攻角很陡。", "explanation": "这里应该用〈角度〉。攻角专指飞行物身体与风向之间的夹角，屋顶的倾斜应用角度。"}, {"text": "他抬头看飞机，攻角很大。", "explanation": "这里应该用〈仰角〉。攻角指飞行物与风向的夹角，观察者抬头看物体的角度应用仰角。"}, {"text": "两条线形成一个攻角。", "explanation": "这里应该用〈夹角〉。攻角只用于飞行物身体与风向之间，两条线形成的一般夹角应用夹角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“这只鸟抬高头，攻角变大了”指鸟身与风向之间的夹角变大，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：抬高头不会让体重变大，与“变大了”的语境不符。"}, {"text": "音量", "is_correct": false, "explanation": "语义：抬头与音量的变化没有关系，句子语义不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与鸟抬头的动作无关，不能用来描述这一变化。"}], "explanations": {"攻角": "“这只鸟抬高头，攻角变大了”指鸟身与风向之间的夹角变大，与句意相符。", "体重": "语义：抬高头不会让体重变大，与“变大了”的语境不符。", "音量": "语义：抬头与音量的变化没有关系，句子语义不通。", "价格": "语义：价格与鸟抬头的动作无关，不能用来描述这一变化。"}, "sentence_index": 6, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三角形的一个攻角很大。", "explanation": "这里应该用〈内角〉。攻角只用于飞行物身体与风向之间，三角形的角应用内角。"}, {"text": "从这个攻角看，房子很大。", "explanation": "这里应该用〈视角〉。攻角指飞行物身体与风向的夹角，观察的角度应用视角。"}, {"text": "地轴的攻角是二十三度。", "explanation": "这里应该用〈倾角〉。攻角只用于飞行物身体与风向之间，地轴的倾斜应用倾角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想看看这三只攻角。", "corrected_sentence": "我想看看这三个攻角。", "error_description": "攻角的量词是“个”，不用“只”。应说“这三个攻角”，不能说“这三只攻角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前见了过这个攻角。", "corrected_sentence": "我以前见过这个攻角。", "error_description": "“了”和“过”不能同时用在同一个动词后面，应说“见过”，不能说“见了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定律是科学家发现的，世界上的一个规则。", "primary_collocate": null, "pronunciation": "dìng lǜ", "ipa": "tiŋ˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "科学家发现了一条新定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条定律很有名。", "target_word": "定律", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "苹果会往下掉，这是一条定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲了一条有关光的定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界上有很多定律，大家都要遵守。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条定律是几百年前的科学家发现的。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学这条定律，再做练习。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上写着三条重要的定律。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“这条定律是谁发现的？”", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水往低处流，也是自然界的一条定律。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "定律：科学家发现的、世界上的一个规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7412a05a-d680-454d-90b7-9bb1efc71a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裙子", "is_correct": false, "explanation": "语义：科学家“发现”的是自然界的规律，裙子是服装，句子说不通。"}, {"text": "定律", "is_correct": true, "explanation": "正确。科学家发现的是自然界的规则，“定律”符合这一语境。"}, {"text": "命令", "is_correct": false, "explanation": "搭配：“发现”不跟“命令”搭配，命令要说“下达”或“发出”。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是人穿戴的物品，科学家不会发现一条新围巾，语义不通。"}], "explanations": {"裙子": "语义：科学家“发现”的是自然界的规律，裙子是服装，句子说不通。", "定律": "正确。科学家发现的是自然界的规则，“定律”符合这一语境。", "命令": "搭配：“发现”不跟“命令”搭配，命令要说“下达”或“发出”。", "围巾": "语义：围巾是人穿戴的物品，科学家不会发现一条新围巾，语义不通。"}, "sentence_index": 0, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是学校的定律，是科学家刚发现的。", "explanation": "这里应该用〈规定〉。定律指科学家发现的自然规律，学校的要求不是科学家发现的，应用〈规定〉。"}, {"text": "我们班的定律是下个月去博物馆。", "explanation": "这里应该用〈计划〉。定律指科学家发现的世界规则，打算要做的事要用〈计划〉。"}, {"text": "这个游戏的定律是牛顿发现的。", "explanation": "这里应该用〈规则〉。定律是科学家发现的自然规律，游戏的约定不是科学家发现的，应用〈规则〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，不能被当作学习的内容，“学这条鱼”说不通。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然地理事物，“学”的对象应是知识或规律，学河说不通。"}, {"text": "定律", "is_correct": true, "explanation": "正确。“学”的对象是规律和知识，“这条定律”符合语境。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能被学习，“学这条雨”说不通。"}], "explanations": {"鱼": "语义：鱼是动物，不能被当作学习的内容，“学这条鱼”说不通。", "河": "语义：河是自然地理事物，“学”的对象应是知识或规律，学河说不通。", "定律": "正确。“学”的对象是规律和知识，“这条定律”符合语境。", "雨": "语义：雨是天气现象，不能被学习，“学这条雨”说不通。"}, "sentence_index": 6, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个定律的答案是三，大家算一算。", "explanation": "这里应该用〈题目〉。定律是科学家发现的世界规则，有答案的数学问题要用〈题目〉。"}, {"text": "他教我们弹这个定律。", "explanation": "这里应该用〈曲子〉。定律不能被“弹”，“弹”的对象应是乐曲，应说“弹这首曲子”。"}, {"text": "今天的定律很好，适合出去玩。", "explanation": "这里应该用〈天气〉。定律是科学家发现的规则，说今天的情况要用〈天气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是科学家提出定律，很多人都学过。", "corrected_sentence": "这是科学家提出的定律，很多人都学过。", "error_description": "错误：“科学家提出”修饰“定律”时，中间要加结构助词“的”，应说“科学家提出的定律”。漏掉“的”，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在课堂上介绍了几条定律们，大家都要记住。", "corrected_sentence": "老师在课堂上介绍了几条定律，大家都要记住。", "error_description": "错误：“几条”已经表示数量，“定律”是抽象名词，后面不能再加“们”，应说“几条定律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147ec75a-5655-4739-9145-8949ef74d085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指不相等，与“相等”构成反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“相等”没有反义关系。"}, {"text": "急促", "is_correct": false, "explanation": "“急促”形容节奏快或声音短促，与“相等”无关。"}, {"text": "巨大", "is_correct": false, "explanation": "“巨大”形容体积或数量很大，不是“相等”的反义词。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指不相等，与“相等”构成反义关系。", "陌生": "“陌生”指不熟悉，与“相等”没有反义关系。", "急促": "“急促”形容节奏快或声音短促，与“相等”无关。", "巨大": "“巨大”形容体积或数量很大，不是“相等”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指不相等，与“相等”构成反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度不热情，与“相等”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“相等”无关。"}, {"text": "轻快", "is_correct": false, "explanation": "“轻快”形容动作或节奏轻松，与“相等”不构成反义。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指不相等，与“相等”构成反义关系。", "冷淡": "“冷淡”形容态度不热情，与“相等”没有反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“相等”无关。", "轻快": "“轻快”形容动作或节奏轻松，与“相等”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西一样大、一样多、一样好。", "primary_collocate": null, "pronunciation": "xiāng děng", "ipa": "ɕjaŋ˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个杯子的容量相等。", "target_word": "相等", "complexity_tier": "T3", "furigana": "liǎng gè bēi zi de róng liàng xiāng děng", "sentence_source": "generated"}, {"text": "哥哥和弟弟的身高几乎相等，站在一起看不出差别。", "target_word": "相等", "complexity_tier": "T3", "furigana": "gē ge hé dì di de shēn gāo jī hū xiāng děng, zhàn zài yì qǐ kàn bu chū chā bié", "sentence_source": "generated"}, {"text": "这两块蛋糕大小相等，你随便选。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的分数相等，都是九十分。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人的水平相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种笔的价格相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子分到的糖果数量相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左右两边的重量相等，天平不动。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的成绩相等，所以并列第一。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队的人数相等，各十个人。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相等", "label": "否定"}], "register": "中性", "sense_fingerprint": "两个东西一样大、一样多或一样好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指容量一样大，正好描述两个杯子的比较。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容外形或个子，不用来形容容量。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与杯子的容量无关。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情或态度，不能用来说容量。"}], "explanations": {"相等": "“相等”指容量一样大，正好描述两个杯子的比较。", "高大": "体貌：“高大”形容外形或个子，不用来形容容量。", "清脆": "语义：“清脆”形容声音，与杯子的容量无关。", "严肃": "语义：“严肃”形容神情或态度，不能用来说容量。"}, "sentence_index": 0, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个人的衣服颜色相等。", "explanation": "这里应该用〈相同〉。相等用于数量、程度等可以量化的情况，颜色要用相同。"}, {"text": "我们对这件事的看法很相等。", "explanation": "这里应该用〈一致〉。相等指数量或程度完全相同，看法的统一要用一致。"}, {"text": "这对双胞胎长得很相等。", "explanation": "这里应该用〈相像〉。相等强调数量或程度完全相同，说长相接近要用相像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指每人分到的数量一样多，与句中的语境一致。"}, {"text": "宽阔", "is_correct": false, "explanation": "体貌：“宽阔”形容空间或面积，不能用来形容糖果数量。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指东西古老、不新，与分配的数量无关。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的态度，不能用来描述数量。"}], "explanations": {"相等": "“相等”指每人分到的数量一样多，与句中的语境一致。", "宽阔": "体貌：“宽阔”形容空间或面积，不能用来形容糖果数量。", "陈旧": "语义：“陈旧”指东西古老、不新，与分配的数量无关。", "懒惰": "语义：“懒惰”形容人的态度，不能用来描述数量。"}, "sentence_index": 6, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两幅画的风格很相等。", "explanation": "这里应该用〈相似〉。相等指数量或程度完全相同，风格的接近要用相似。"}, {"text": "这两个部门的口味很相等。", "explanation": "这里应该用〈一致〉。相等指数量或程度完全相同，口味的统一要用一致。"}, {"text": "这件外套和你的气质很相等。", "explanation": "这里应该用〈相称〉。相等指数量或程度完全相同，外套与气质的协调要用相称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个杯子的容量像那个相等。", "corrected_sentence": "这两个杯子的容量和那个相等。", "error_description": "“相等”的比较对象要用“和/跟”引出，不能用“像”。应把“像”改为“和”，说“这两个杯子的容量和那个相等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把两根绳子的长度相等。", "corrected_sentence": "我们把两根绳子的长度弄得相等。", "error_description": "“相等”是形容词，不能直接放在“把”的后面作谓语。要表示使绳子的长度变得相等，需要补上“弄得”，应说“把……弄得相等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
