INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西转了个方向。", "primary_collocate": null, "pronunciation": "piān zhuǎn", "ipa": "pʰjɛn˥ ʈʂwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "风向变了，旗子偏转到另一边。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支箭碰到树枝，偏转了方向。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打到墙角后，往左偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水遇到大石头，向右偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把镜子稍微偏转一点。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "望远镜偏转了一点，看不到月亮了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船撞到石头后，船头偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台灯太亮，把灯头偏转一点吧。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能板要跟着太阳偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁球经过磁铁旁边，路线偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏转了", "label": "体标"}, {"form": "偏转角", "label": "复合"}, {"form": "偏轉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "东西转向，方向有了变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f461eef-2cb1-401c-a5d5-34b0f63eba4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指旗子转向另一边，与“风向变了”的情境一致。"}, {"text": "转移", "is_correct": false, "explanation": "搭配：“转移”指位置交给别人或改换地方，旗子不能“转移到另一边”。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指温度降低，与旗子转向另一边无关。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：熔化指固体受热变成液体，与旗子转向另一边无关。"}], "explanations": {"偏转": "“偏转”指旗子转向另一边，与“风向变了”的情境一致。", "转移": "搭配：“转移”指位置交给别人或改换地方，旗子不能“转移到另一边”。", "冷却": "语义：冷却指温度降低，与旗子转向另一边无关。", "熔化": "语义：熔化指固体受热变成液体，与旗子转向另一边无关。"}, "sentence_index": 0, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的车轮偏转了一圈。", "explanation": "这里应该用〈转动〉。偏转指方向改变，不指物体绕轴转一圈。"}, {"text": "墙壁偏转得歪歪斜斜。", "explanation": "这里应该用〈倾斜〉。偏转指方向的改变，形容墙面向一侧斜过去要用倾斜。"}, {"text": "他的身高偏转了五厘米。", "explanation": "这里应该用〈增长〉。偏转指方向的改变，身高的增加要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指船头因撞击改变方向，与句意一致。"}, {"text": "颠倒", "is_correct": false, "explanation": "语义：颠倒是整个上下翻转，与船头小幅改变方向的意思不符。"}, {"text": "撞击", "is_correct": false, "explanation": "语义：句中已有“撞到”，再说撞击重复，而且不是改变方向的意思。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾指液体受热剧烈翻滚，与船头方向的改变无关。"}], "explanations": {"偏转": "“偏转”指船头因撞击改变方向，与句意一致。", "颠倒": "语义：颠倒是整个上下翻转，与船头小幅改变方向的意思不符。", "撞击": "语义：句中已有“撞到”，再说撞击重复，而且不是改变方向的意思。", "沸腾": "语义：沸腾指液体受热剧烈翻滚，与船头方向的改变无关。"}, "sentence_index": 6, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁球在桌上快速偏转了几圈。", "explanation": "这里应该用〈旋转〉。偏转指方向改变，不表示物体连续绕轴转圈。"}, {"text": "他把铁丝偏转成了一个圆圈。", "explanation": "这里应该用〈弯〉。偏转指方向的改变，不表示把细长物体弯成圆形。"}, {"text": "他的收入偏转了一万元。", "explanation": "这里应该用〈增加〉。偏转指方向的改变，收入的增加要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风吹过来，树枝偏转了到一边。", "corrected_sentence": "风吹过来，树枝偏转到了一边。", "error_description": "错误：“偏转了到”；正确：“偏转到了”。“了”要放在“到一边”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把镜子稍微偏转得一下。", "corrected_sentence": "他把镜子稍微偏转了一下。", "error_description": "错误：“偏转得一下”；正确：“偏转了一下”。“得”用于程度补语，不能接“一下”，动作完成应在“偏转”后用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab7d4d52-9f7f-4d74-8374-e4e1abf5134f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
