INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西动起来时，被挡住不让动的那种力。", "primary_collocate": null, "pronunciation": "mó cā zǔ lì", "ipa": "mwo˧˥ tsʰa˥ tsu˨˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "汽车刹车时，轮胎和地面之间有摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面很滑，摩擦阻力很小，所以人容易摔倒。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在鞋底加上花纹，可以增大摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体表面越粗糙，摩擦阻力就越大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给自行车链条上油，能减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木箱太重，推不动是因为地面的摩擦阻力大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪板底部很光滑，是为了减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球在桌上滚了一会儿，因为摩擦阻力停下来了。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天路上结冰，车轮的摩擦阻力变小了。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，空气也会对飞机产生摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体接触面相对运动时产生的、阻碍物体运动的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8a7d8d-7ee2-4ed2-a67d-1e712f561b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：刹车时轮胎与地面接触并相对滑动，产生的正是摩擦阻力。"}, {"text": "空气阻力", "is_correct": false, "explanation": "语义：轮胎和地面之间不是空气，空气阻力不会在这个位置产生。"}, {"text": "重量", "is_correct": false, "explanation": "语义：轮胎和地面之间不能“有重量”，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色属于外观，与刹车时轮胎和地面之间的作用无关。"}], "explanations": {"摩擦阻力": "正确：刹车时轮胎与地面接触并相对滑动，产生的正是摩擦阻力。", "空气阻力": "语义：轮胎和地面之间不是空气，空气阻力不会在这个位置产生。", "重量": "语义：轮胎和地面之间不能“有重量”，句意不通。", "颜色": "体貌：颜色属于外观，与刹车时轮胎和地面之间的作用无关。"}, "sentence_index": 0, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用力推箱子时，箱子前进靠的是摩擦阻力。", "explanation": "这里应该用〈推力〉。摩擦阻力是阻碍运动的力，推动箱子前进的力要用推力。"}, {"text": "最近工作太忙，我感到摩擦阻力很大。", "explanation": "这里应该用〈压力〉。摩擦阻力是物理上的力，心理上的负担要用压力。"}, {"text": "两家人之间的摩擦阻力越来越大。", "explanation": "这里应该用〈矛盾〉。摩擦阻力是物理上的力，人与人之间的冲突要用矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：滑雪板底部光滑，是为了减小雪面与板之间的摩擦阻力。"}, {"text": "光泽", "is_correct": false, "explanation": "体貌：光泽属于外观，减小光泽不是滑雪板光滑的目的。"}, {"text": "高度", "is_correct": false, "explanation": "语义：底部光滑与高度无关，“减小高度”不能作为光滑的目的。"}, {"text": "体重", "is_correct": false, "explanation": "语义：滑雪板光滑是为了减少阻力，与体重无关。"}], "explanations": {"摩擦阻力": "正确：滑雪板底部光滑，是为了减小雪面与板之间的摩擦阻力。", "光泽": "体貌：光泽属于外观，减小光泽不是滑雪板光滑的目的。", "高度": "语义：底部光滑与高度无关，“减小高度”不能作为光滑的目的。", "体重": "语义：滑雪板光滑是为了减少阻力，与体重无关。"}, "sentence_index": 6, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的摩擦阻力越大，它转得越快。", "explanation": "这里应该用〈动力〉。摩擦阻力是阻碍运动的力，使机器转得越来越快的力要用动力。"}, {"text": "月亮的摩擦阻力把海水拉向岸边。", "explanation": "这里应该用〈引力〉。摩擦阻力是阻碍运动的力，把海水拉向岸边的力要用引力。"}, {"text": "弹簧被压缩后，它的摩擦阻力会把物体弹开。", "explanation": "这里应该用〈弹力〉。摩擦阻力是阻碍运动的力，弹簧恢复形变时把物体弹开的力要用弹力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋的摩擦摩擦阻力很大。", "corrected_sentence": "这双鞋的摩擦阻力很大。", "error_description": "错误：「摩擦阻力」前多写了一个「摩擦」，应删去，正确为「这双鞋的摩擦阻力很大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨后地面湿滑，车轮的摩擦摩擦阻力减小了。", "corrected_sentence": "雨后地面湿滑，车轮的摩擦阻力减小了。", "error_description": "错误：「摩擦阻力」前多写了一个「摩擦」，应删去，正确为「雨后地面湿滑，车轮的摩擦阻力减小了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
