INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做你想让他做的事。", "primary_collocate": null, "pronunciation": "yòu dǎo", "ipa": "jou̯˥˩ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想诱导我签下这份合同。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告诱导人们买不需要的东西。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着诱导小弟弟说出了秘密。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子诱导受害人转钱给陌生人。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板诱导新人加班，却不给加班费。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人不应该诱导孩子说谎。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有诱导他，是他自己说的。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的游戏诱导学生花很多钱。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店把糖放在门口，诱导小孩进来买。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用好听的话诱导朋友投资。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱导了", "label": "体标"}, {"form": "诱导过", "label": "体标"}], "register": "中性", "sense_fingerprint": "设法让别人按自己的想法去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8a7d8d-7ee2-4ed2-a67d-1e712f561b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "诱导：用好处或手段引人去做，与“想签下这份合同”的意图相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是护住对方、使其免受伤害，不能让人去签合同。"}, {"text": "修改", "is_correct": false, "explanation": "配价：“修改”的宾语是文件、计划，不能以“我”作宾语，也不能接“签下合同”。"}, {"text": "包括", "is_correct": false, "explanation": "配价：“包括”后接事物或范围，不能接动作短语“签下这份合同”。"}], "explanations": {"诱导": "诱导：用好处或手段引人去做，与“想签下这份合同”的意图相合。", "保护": "语义：保护是护住对方、使其免受伤害，不能让人去签合同。", "修改": "配价：“修改”的宾语是文件、计划，不能以“我”作宾语，也不能接“签下合同”。", "包括": "配价：“包括”后接事物或范围，不能接动作短语“签下这份合同”。"}, "sentence_index": 0, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他诱导了我的感情。", "explanation": "这里应该用〈欺骗〉。诱导的宾语是要对方去做的事，不能说“诱导感情”；“欺骗感情”才是正确说法。"}, {"text": "这场暴雨诱导了山体滑坡。", "explanation": "这里应该用〈诱发〉。诱导的对象是人，要使人去做某事；山体滑坡是自然现象造成的结果，应用〈诱发〉。"}, {"text": "这件事诱导了大家的注意。", "explanation": "这里应该用〈引起〉。诱导的宾语是要对方去做的事，不能与“注意”搭配；“引起注意”应用〈引起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "诱导：用手段或利益引人做事，与“没有诱导他”的否定相呼应，说明警察没有用手段。"}, {"text": "翻阅", "is_correct": false, "explanation": "配价：“翻阅”的对象是书报、文件，不能以人作宾语。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮是修饰外表，与“是他自己说的”不相干，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”的对象是语言或文字，不能以人作宾语。"}], "explanations": {"诱导": "诱导：用手段或利益引人做事，与“没有诱导他”的否定相呼应，说明警察没有用手段。", "翻阅": "配价：“翻阅”的对象是书报、文件，不能以人作宾语。", "打扮": "语义：打扮是修饰外表，与“是他自己说的”不相干，句意不通。", "翻译": "配价：“翻译”的对象是语言或文字，不能以人作宾语。"}, "sentence_index": 6, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个标志诱导车辆转弯了。", "explanation": "这里应该用〈指示〉。诱导是用手段使有意志的人去做某事，路标不能诱导车辆；指示车辆转弯应用〈指示〉。"}, {"text": "队长诱导队员立即出发。", "explanation": "这里应该用〈命令〉。诱导是间接引人去做，不是直接下令；要求队员立即行动应用〈命令〉。"}, {"text": "这首歌诱导了我的泪水。", "explanation": "这里应该用〈引出〉。诱导是促使人去做某事，不能与“泪水”搭配；这首歌使人流泪，应用〈引出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人用假消息诱导很多老人的买保健品。", "corrected_sentence": "那个人用假消息诱导很多老人买保健品。", "error_description": "错误：「老人」与「买」之间多出「的」，「的」不能插在兼语「老人」与动词「买」之间，应删去，正确为「那个人用假消息诱导很多老人买保健品」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用奖金诱导员工了加班。", "corrected_sentence": "他用奖金诱导员工加班。", "error_description": "错误：“员工了加班”。“了”不能插在兼语“员工”与动词“加班”之间，应删去；正确为“他用奖金诱导员工加班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机用来坐人的那部分。", "primary_collocate": null, "pronunciation": "jī shēn", "ipa": "tɕi˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "乘客都坐在机身里。", "target_word": "机身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机身里有一百多个座位。", "target_word": "机身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空姐在机身里走来走去，给乘客送水。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机身里很安静，大家都睡着了。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，机身里的人要系好安全带。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架飞机的机身很宽，每排能坐九个人。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机身里有点冷，我向空姐要了一条毯子。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在机身里找到了自己的座位。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机身里的灯关了，乘客们准备睡觉。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上飞机后，我把行李放进机身里的行李架。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "飞机上乘客乘坐的内部空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dde6a0-6292-4664-9a19-16fa7c1d359e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机身", "is_correct": true, "explanation": "jī shēn，指飞机上供乘客乘坐的内部空间。"}, {"text": "己身", "is_correct": false, "explanation": "jǐ shēn（第三声）与 jī shēn（第一声）只差声调，意思是自己的身体。"}, {"text": "机声", "is_correct": false, "explanation": "jī shēng（-eng）与 jī shēn（-en）韵母不同，意思是机器发出的声音。"}, {"text": "资深", "is_correct": false, "explanation": "zī shēn（z-）与 jī shēn（j-）声母不同，意思是资历深。"}], "explanations": {"机身": "jī shēn，指飞机上供乘客乘坐的内部空间。", "己身": "jǐ shēn（第三声）与 jī shēn（第一声）只差声调，意思是自己的身体。", "机声": "jī shēng（-eng）与 jī shēn（-en）韵母不同，意思是机器发出的声音。", "资深": "zī shēn（z-）与 jī shēn（j-）声母不同，意思是资历深。"}, "sentence_index": null, "correct_answer": "机身"}, "level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以乘坐的空间，乘客不会坐在冰箱里。"}, {"text": "机身", "is_correct": true, "explanation": "“机身”指飞机内乘客乘坐的空间，乘客可以坐在里面。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“坐在……里”的处所不能是天空，天空不是可以乘坐的空间。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然水域，乘客不会坐在海洋里。"}], "explanations": {"冰箱": "语义：冰箱不是可以乘坐的空间，乘客不会坐在冰箱里。", "机身": "“机身”指飞机内乘客乘坐的空间，乘客可以坐在里面。", "天空": "搭配：“坐在……里”的处所不能是天空，天空不是可以乘坐的空间。", "海洋": "语义：海洋是自然水域，乘客不会坐在海洋里。"}, "sentence_index": 0, "correct_answer": "机身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的机身里很暗，要开灯。", "explanation": "这里应该用〈屋里〉。机身指飞机内供乘客乘坐的空间，房间里的空间要说屋里。"}, {"text": "列车长在机身里巡视，乘客们都很安静。", "explanation": "这里应该用〈车厢〉。机身指飞机内供乘客乘坐的空间，列车上的乘坐空间要说车厢。"}, {"text": "这艘船的机身里很闷，大家都躺着休息。", "explanation": "这里应该用〈船舱〉。机身指飞机内的乘客空间，船上的舱室要说船舱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：教室里不会有空姐，没有人会在教室里向空姐要毯子。"}, {"text": "机身", "is_correct": true, "explanation": "“机身”指飞机内的乘客空间，空姐和毯子都与飞机内的场景相符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅不是飞机内的空间，不会有空姐在里面送毯子。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“向空姐要毯子”的场所应是飞机内，操场与这一语境不搭配。"}], "explanations": {"教室": "语义：教室里不会有空姐，没有人会在教室里向空姐要毯子。", "机身": "“机身”指飞机内的乘客空间，空姐和毯子都与飞机内的场景相符。", "餐厅": "语义：餐厅不是飞机内的空间，不会有空姐在里面送毯子。", "操场": "搭配：“向空姐要毯子”的场所应是飞机内，操场与这一语境不搭配。"}, "sentence_index": 6, "correct_answer": "机身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫把机身蜷成一团，睡得很香。", "explanation": "这里应该用〈身子〉。机身指飞机用来坐人的部分，小动物的身子要说身子。"}, {"text": "这棵老树的机身上长满了青苔。", "explanation": "这里应该用〈树身〉。机身指飞机用来坐人的部分，树的主干要说树身。"}, {"text": "这只瓶子的机身很细，拿在手里很轻。", "explanation": "这里应该用〈瓶身〉。机身指飞机用来坐人的部分，瓶子的主体要说瓶身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只机身里的座位都坐满了人。", "corrected_sentence": "这个机身里的座位都坐满了人。", "error_description": "量词错误：“机身”应搭配“个”，不能说“这只机身”。“只”多用于动物或成对物件中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乘客们都在机身上系好了安全带。", "corrected_sentence": "乘客们都在机身里系好了安全带。", "error_description": "方位词错误：乘客在机舱内系安全带，应说“机身里”；“机身上”指飞机外部，不能用来指乘客的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
