INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "动得很快、很猛。", "primary_collocate": null, "pronunciation": "jù liè", "ipa": "tɕy˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "地震时，房子剧烈地摇晃。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吓得心脏剧烈跳动。", "target_word": "剧烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大风里，小船剧烈地上下摇动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机遇到气流，开始剧烈抖动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑得肩膀剧烈地抖动起来。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机转得太剧烈，地板也跟着震动。", "target_word": "剧烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车突然停下，车里的人剧烈地向前冲。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山喷发时，大地剧烈地震动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼一离开水，就在网里剧烈地跳动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力一拉，绳子剧烈地晃了几下。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剧烈地", "label": "副词形式"}, {"form": "劇烈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物体或身体动作幅度大、速度快，如晃动、抖动、跳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dde6a0-6292-4664-9a19-16fa7c1d359e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“摇晃”，表示幅度大、速度快，符合地震时的情境，可以填入空格。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：清淡多用于形容饮食，不能用来修饰摇晃。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡形容态度，与地震时房子的动荡不符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：寂静指没有声音，与摇晃的动态特点不符。"}], "explanations": {"剧烈": "剧烈修饰“摇晃”，表示幅度大、速度快，符合地震时的情境，可以填入空格。", "清淡": "搭配：清淡多用于形容饮食，不能用来修饰摇晃。", "冷淡": "语义：冷淡形容态度，与地震时房子的动荡不符。", "寂静": "语义：寂静指没有声音，与摇晃的动态特点不符。"}, "sentence_index": 0, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的阳光非常剧烈。", "explanation": "这里应该用〈强烈〉。剧烈形容动作的猛烈程度，阳光的强弱要用强烈。"}, {"text": "这幅画的颜色非常剧烈。", "explanation": "这里应该用〈强烈〉。颜色的鲜明程度要用强烈，剧烈只形容动作。"}, {"text": "他思考这个问题时非常剧烈。", "explanation": "这里应该用〈认真〉。剧烈表示动得很快很猛，思考是内在活动，不能用剧烈修饰；描述思考的投入要说〈认真〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“向前冲”，表示动作猛烈，符合车急停时的情境，可以填入空格。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮形容光线或色彩，不能修饰冲的动作。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：平淡指平稳、没有波澜，与急停后的猛冲相反。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能用来形容人的动作。"}], "explanations": {"剧烈": "剧烈修饰“向前冲”，表示动作猛烈，符合车急停时的情境，可以填入空格。", "明亮": "搭配：明亮形容光线或色彩，不能修饰冲的动作。", "平淡": "语义：平淡指平稳、没有波澜，与急停后的猛冲相反。", "清脆": "搭配：清脆形容声音，不能用来形容人的动作。"}, "sentence_index": 6, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画剧烈地挂在墙上。", "explanation": "这里误把〈剧烈〉当作“牢牢地”来用；剧烈指动得很快很猛，挂画是平稳的动作，应说〈牢牢地〉。"}, {"text": "老师剧烈地讲解数学题。", "explanation": "这里误把〈剧烈〉当作“仔细、详尽”来用；讲解是平和的活动，剧烈表示动得很快很猛，应说〈仔细〉。"}, {"text": "那个人剧烈地坐在椅子上发呆。", "explanation": "这里应该用〈安静〉。剧烈表示动得很快很猛，坐着发呆是静止的，不能用剧烈修饰，应说安静地坐着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小船在风里剧烈的摇动。", "corrected_sentence": "小船在风里剧烈地摇动。", "error_description": "“剧烈”修饰动词“摇动”时要用“地”，写成“的”是误用（“剧烈的”只修饰名词）。正确形式为“剧烈地摇动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他猛地一拉，车门剧烈的晃了几下。", "corrected_sentence": "他猛地一拉，车门剧烈地晃了几下。", "error_description": "修饰动词“晃”要用“地”，写成“的”是误用。“剧烈的”只能修饰名词，正确形式为“剧烈地晃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
