INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "黏性是指东西摸起来黏黏的，比如胶水会黏住手指。", "primary_collocate": null, "pronunciation": "nián xìng", "ipa": "njɛn˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种胶水的黏性很强。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胶带用久了，黏性就变差了。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年糕的黏性很大，会粘牙。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个便利贴没有黏性，老是掉下来。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糯米饭有很强的黏性。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的胶水黏性很大，洗了好几次才干净。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块泥土黏性大，一踩就粘鞋。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买胶带前，我先试了试黏性。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面团加水太多，黏性会变大。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种双面胶黏性好，墙上能贴很久。", "target_word": "黏性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粘性", "label": "异形词"}], "register": "中性", "sense_fingerprint": "日常物品（胶水、胶带、年糕等）摸起来发黏、能粘住东西的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dde6a0-6292-4664-9a19-16fa7c1d359e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黏性", "is_correct": true, "explanation": "正确：黏性指东西摸起来发黏、能粘住东西的性质，与“胶水的……很强”搭配恰当。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，胶水不发出声音，与句中描述的性质无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”应说“高”或“低”，不说“很强”，与句中的搭配不当。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指发光的强弱，胶水不发光，句中说的是黏附的性质。"}], "explanations": {"黏性": "正确：黏性指东西摸起来发黏、能粘住东西的性质，与“胶水的……很强”搭配恰当。", "音量": "语义：音量指声音的大小，胶水不发出声音，与句中描述的性质无关。", "价格": "搭配：“价格”应说“高”或“低”，不说“很强”，与句中的搭配不当。", "亮度": "语义：亮度指发光的强弱，胶水不发光，句中说的是黏附的性质。"}, "sentence_index": 0, "correct_answer": "黏性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的黏性很柔软，穿起来很舒服。", "explanation": "这里应该用〈手感〉。黏性说东西摸上去粘手、能粘住东西，形容布料柔软舒适要用手感。"}, {"text": "这杯水的黏性很高，喝下去会烫嘴。", "explanation": "这里应该用〈温度〉。黏性指摸上去粘手、粘住东西的性质，形容水的冷热要用温度。"}, {"text": "这根弹簧的黏性很好，压下去能弹回来。", "explanation": "这里应该用〈弹性〉。黏性指粘住东西的性质，压下去又弹回来形容的是弹性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黏性", "is_correct": true, "explanation": "正确：黏性指东西摸起来发黏、能粘住其他东西的性质，泥土一踩就粘鞋正是由此。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命指生物或物品存续的时长，泥土不是生物，“寿命大”与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色应说“深”或“浅”，不说“大”，与“大”搭配不当。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度指运动的快慢，泥土是静止的，“速度大”与“一踩就粘鞋”的语境不符。"}], "explanations": {"黏性": "正确：黏性指东西摸起来发黏、能粘住其他东西的性质，泥土一踩就粘鞋正是由此。", "寿命": "语义：寿命指生物或物品存续的时长，泥土不是生物，“寿命大”与句意不符。", "颜色": "搭配：颜色应说“深”或“浅”，不说“大”，与“大”搭配不当。", "速度": "语义：速度指运动的快慢，泥土是静止的，“速度大”与“一踩就粘鞋”的语境不符。"}, "sentence_index": 6, "correct_answer": "黏性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根铁丝的黏性很高，弯来弯去也不断。", "explanation": "这里应该用〈韧性〉。黏性指粘住东西的性质，形容铁丝弯折多次也不断裂要用韧性。"}, {"text": "这块玉石的黏性很好，看上去很温润。", "explanation": "这里应该用〈光泽〉。黏性指粘附的性质，形容玉石表面发亮、有光泽要用光泽。"}, {"text": "他的黏性很强，总爱缠着朋友。", "explanation": "这里应该用〈黏人〉。黏性形容物体的附着性能，形容人爱缠着别人、粘人要用“黏人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胶水有一根很强的黏性，碰到手指就会粘住。", "corrected_sentence": "胶水有一种很强的黏性，碰到手指就会粘住。", "error_description": "量词错误：“黏性”是抽象的性质，前面应用量词“种”，“根”用于细长的物体，不能用来修饰“黏性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "泥土有一根很大的黏性，一踩就粘鞋。", "corrected_sentence": "泥土有一种很大的黏性，一踩就粘鞋。", "error_description": "量词错误：“黏性”前应用量词“种”，“根”用于细长的物体，不能用来修饰性质名词“黏性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
