INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分子是分数中上面的数，告诉你有几份。", "primary_collocate": null, "pronunciation": "fēn zǐ", "ipa": "fən˥˥ tsɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "二分之一的分子是一。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三分之二里，分子是二，分母是三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数的分子比分母小。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把分子写在分数线上面。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五分之四的分子是四。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分数线上面的数叫分子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母是八，分子是三，这个分数是八分之三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子和分母一样大，这个分数就是一。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我：“七分之五的分子是多少？”", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母不变时，这个分子越大，分数越大。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分数线上面的数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea56e5e-7c24-45c0-acbd-cd48719e98b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子指分数线上面的数，读作 fēn zǐ，例如二分之一的分子是一。"}, {"text": "分支", "is_correct": false, "explanation": "zhī（第一声）与 zǐ（第三声）声母与声调都不同，意思是分支。"}, {"text": "分值", "is_correct": false, "explanation": "zhí（第二声）与 zǐ（第三声）声母与声调不同，意思是分值。"}, {"text": "分词", "is_correct": false, "explanation": "cí（第二声）与 zǐ（第三声）声母与声调不同，意思是分词（语法中的一类词）。"}, {"text": "份子", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，份子指随礼送的钱，与分数无关。"}], "explanations": {"分子": "分子指分数线上面的数，读作 fēn zǐ，例如二分之一的分子是一。", "分支": "zhī（第一声）与 zǐ（第三声）声母与声调都不同，意思是分支。", "分值": "zhí（第二声）与 zǐ（第三声）声母与声调不同，意思是分值。", "分词": "cí（第二声）与 zǐ（第三声）声母与声调不同，意思是分词（语法中的一类词）。", "份子": "fèn（第四声）与 fēn（第一声）声调不同，份子指随礼送的钱，与分数无关。"}, "sentence_index": null, "correct_answer": "分子"}, "level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子是分数线上面的数，“二分之一的分子是一”句意正确。"}, {"text": "分母", "is_correct": false, "explanation": "语义：分母是分数线下面的数，二分之一的分母是二，不能是一。"}, {"text": "整数", "is_correct": false, "explanation": "语义：二分之一是分数，不是整数，不能说它的整数是一。"}, {"text": "小数", "is_correct": false, "explanation": "语义：二分之一的小数是0.5，不是一，与句意不符。"}], "explanations": {"分子": "分子是分数线上面的数，“二分之一的分子是一”句意正确。", "分母": "语义：分母是分数线下面的数，二分之一的分母是二，不能是一。", "整数": "语义：二分之一是分数，不是整数，不能说它的整数是一。", "小数": "语义：二分之一的小数是0.5，不是一，与句意不符。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作的分子很重。", "explanation": "这里应该用〈分量〉。“分子”只指分数线上面的数或化学中的微粒，说工作的轻重要用“分量”。"}, {"text": "这个分子是八分之三。", "explanation": "这里应该用〈分数〉。分子只是分数线上面的那个数，整个八分之三才叫分数。"}, {"text": "我们班的分子都很热心。", "explanation": "这里应该用〈成员〉。“分子”指人时只见于“积极分子”“知识分子”等复合词，说班里的人要用“成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子指分数线上面的数，读作 fēn zǐ。"}, {"text": "分组", "is_correct": false, "explanation": "zǔ（第三声）与 zǐ（第三声）韵母不同，意思是分组。"}, {"text": "方子", "is_correct": false, "explanation": "fāng（第一声）与 fēn（第一声）韵母不同，zi 读轻声，意思是药方。"}, {"text": "分制", "is_correct": false, "explanation": "zhì（第四声）与 zǐ（第三声）声母与声调都不同，意思是按分数计算的制度，如学分制。"}], "explanations": {"分子": "分子指分数线上面的数，读作 fēn zǐ。", "分组": "zǔ（第三声）与 zǐ（第三声）韵母不同，意思是分组。", "方子": "fāng（第一声）与 fēn（第一声）韵母不同，zi 读轻声，意思是药方。", "分制": "zhì（第四声）与 zǐ（第三声）声母与声调都不同，意思是按分数计算的制度，如学分制。"}, "sentence_index": null, "correct_answer": "分子"}, "level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子是分数线上面的数，“分子是三”与“八分之三”的分数相符。"}, {"text": "因数", "is_correct": false, "explanation": "语义：句中说的是分数的分子，“因数是三”与分数的构成不符。"}, {"text": "积", "is_correct": false, "explanation": "语义：积是乘法的结果，与分数的分子是三无关。"}, {"text": "余数", "is_correct": false, "explanation": "搭配：“余数”要与除法连用，不能与“分母是八”并列作分数的组成部分。"}], "explanations": {"分子": "分子是分数线上面的数，“分子是三”与“八分之三”的分数相符。", "因数": "语义：句中说的是分数的分子，“因数是三”与分数的构成不符。", "积": "语义：积是乘法的结果，与分数的分子是三无关。", "余数": "搭配：“余数”要与除法连用，不能与“分母是八”并列作分数的组成部分。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分母不变时，这位分子越大，分数越大。", "explanation": "这里应该用〈个〉。“位”用于人，分子是抽象的数，不能用“位”计量。"}, {"text": "分母不变时，这条分子越大，分数越大。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，分子是抽象的数，不能用“条”计量。"}, {"text": "分母不变时，这只分子越大，分数越大。", "explanation": "这里应该用〈个〉。“只”用于动物等，分子是抽象的数，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七分之三分子是三。", "corrected_sentence": "七分之三的分子是三。", "error_description": "“分子”修饰分数时要加“的”，应说“七分之三的分子是三”，漏掉“的”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张分子是六，分母是十一。", "corrected_sentence": "这个分子是六，分母是十一。", "error_description": "“分子”是抽象的数，量词用“个”；“张”用于平面的东西，不能计量分子，应说“这个分子是六”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de4db2d-b451-4256-9725-b5daa27bb953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "粗糙度就是东西表面不光滑的程度，比如摸起来很粗或者很细的感觉。", "primary_collocate": null, "pronunciation": "cū cāo dù", "ipa": "tsʰu˥˥ tsʰaʊ˥˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这块布的粗糙度很高，摸起来有点扎手。", "target_word": "粗糙度", "complexity_tier": "T3", "furigana": "zhè kuài bù de cū cāo dù hěn gāo, mō qǐ lái yǒu diǎn zhā shǒu.", "sentence_source": "generated"}, {"text": "你摸一摸，就知道墙面的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "砂纸的粗糙度比纸巾大得多。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上长了茧，我能感觉到皮肤的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "furigana": "shǒu shàng zhǎng le jiǎn, wǒ néng gǎn jué dào pí fū de cū cāo dù.", "sentence_source": "generated"}, {"text": "这个杯子表面很滑，几乎没有粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买木桌时，我会用手摸一摸桌面的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "furigana": "mǎi mù zhuō shí, wǒ huì yòng shǒu mō yi mō zhuō miàn de cū cāo dù.", "sentence_source": "generated"}, {"text": "孩子用手一摸，就能感觉到石头的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手指感受着纸的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房地砖的粗糙度刚好，不容易滑倒。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两块木板的粗糙度不一样。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面粗糙度", "label": "复合"}], "register": "中性", "sense_fingerprint": "粗糙度：东西表面摸起来粗或细的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：“粗糙度很高”指表面摸起来粗，与“摸起来有点扎手”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能靠摸来感受粗细，与“摸起来扎手”不符。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：布的“长度”不用“很高”来形容，与句子搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：布料不说“年龄很高”，与句中描述的触感不符。"}], "explanations": {"粗糙度": "正确：“粗糙度很高”指表面摸起来粗，与“摸起来有点扎手”相符。", "颜色": "语义：颜色不能靠摸来感受粗细，与“摸起来扎手”不符。", "长度": "搭配：布的“长度”不用“很高”来形容，与句子搭配不当。", "年龄": "搭配：布料不说“年龄很高”，与句中描述的触感不符。"}, "sentence_index": 0, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃的粗糙度很高，所以很透明。", "explanation": "这里应该用〈透明度〉。玻璃通透与否要说“透明度”，粗糙度只描述表面不平整的程度，不能用来说明透明与否。"}, {"text": "今天空气的粗糙度很高，闷得人喘不过气。", "explanation": "这里应该用〈湿度〉。空气潮湿要说“湿度”，粗糙度只描述物体表面。"}, {"text": "杯子里的粗糙度很高，喝的时候要小心。", "explanation": "这里应该用〈温度〉。烫不烫要说“温度”，粗糙度只描述物体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：用手一摸就能感觉到的表面粗细，符合句中的触感语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是味觉的感受，与“让孩子觉得有趣”的触感无关。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是嗅觉的感受，不能用来说石头的触感。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖的代价，与孩子的感受无关。"}], "explanations": {"粗糙度": "正确：用手一摸就能感觉到的表面粗细，符合句中的触感语境。", "味道": "语义：味道是味觉的感受，与“让孩子觉得有趣”的触感无关。", "气味": "语义：气味是嗅觉的感受，不能用来说石头的触感。", "价格": "语义：价格指买卖的代价，与孩子的感受无关。"}, "sentence_index": 6, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的粗糙度太大了，邻居都听到了。", "explanation": "这里应该用〈音量〉。声音大小要说“音量”，粗糙度只描述物体表面。"}, {"text": "房间里的粗糙度太低，看不清字。", "explanation": "这里应该用〈亮度〉。光线明暗要说“亮度”，粗糙度不能用来形容房间。"}, {"text": "这箱书的粗糙度太重，搬不动。", "explanation": "这里应该用〈重量〉。轻重要说“重量”，粗糙度只描述物体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头的一只粗糙度很低，摸起来很光滑。", "corrected_sentence": "这块木头的粗糙度很低，摸起来很光滑。", "error_description": "错误形式：一只粗糙度；正确形式：粗糙度。原因：“只”多用于动物或成对的小物，抽象名词“粗糙度”不能用“只”计量，应直接说“这块木头的粗糙度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只粗糙度让我觉得很舒服。", "corrected_sentence": "这种粗糙度让我觉得很舒服。", "error_description": "错误形式：这只粗糙度；正确形式：这种粗糙度。原因：“只”多用于动物或成对的小物，抽象名词“粗糙度”要用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
