INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来源于是指人或事物从某处来、出自某地。", "primary_collocate": null, "pronunciation": "lái yuán yú", "ipa": "lai˧˥ ɥɛn˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这些苹果来源于山东的一个小村子。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的学生来源于不同的国家。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水来源于山上的小河。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的牛奶来源于附近的农场。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水来源于雪山。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的茶叶来源于云南。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人来源于全国各地。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批木头来源于南方的森林。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的蔬菜来源于自己的小院子。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的咖啡豆来源于哪里？", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "具体的人或物（水、水果、学生等）所来自的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dde6a0-6292-4664-9a19-16fa7c1d359e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示苹果的产地，符合语境，可以填入空格。"}, {"text": "等于", "is_correct": false, "explanation": "语义：等于表示相等，苹果与村子不能说相等。"}, {"text": "高于", "is_correct": false, "explanation": "语义：高于表示比较高低，与说明产地的语境不符。"}, {"text": "陷于", "is_correct": false, "explanation": "搭配：陷于多指困境，不能说苹果陷于某个地方。"}], "explanations": {"来源于": "来源于表示苹果的产地，符合语境，可以填入空格。", "等于": "语义：等于表示相等，苹果与村子不能说相等。", "高于": "语义：高于表示比较高低，与说明产地的语境不符。", "陷于": "搭配：陷于多指困境，不能说苹果陷于某个地方。"}, "sentence_index": 0, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车来源于我。", "explanation": "这里应该用〈属于〉。来源于说事物的来处，车的所有归属要用属于。"}, {"text": "这个饭店来源于明天晚上开业。", "explanation": "这里应该用〈在〉。来源于说人或事物来的地方，不能表示时间；“在明天晚上开业”要用在。"}, {"text": "这家超市来源于学校旁边。", "explanation": "这里应该用〈位于〉。来源于说人或事物来的地方，超市的位置要用位于，不能用来源于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示参赛者的来处，符合语境，可以填入空格。"}, {"text": "挑战", "is_correct": false, "explanation": "配价：挑战要带人或事的宾语，不能接表示地点的“全国各地”。"}, {"text": "死于", "is_correct": false, "explanation": "语义：死于指死亡的原因，与参加比赛的语境无关。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：惩罚与说明参赛者来处的语境不相合，句子不通。"}], "explanations": {"来源于": "来源于表示参赛者的来处，符合语境，可以填入空格。", "挑战": "配价：挑战要带人或事的宾语，不能接表示地点的“全国各地”。", "死于": "语义：死于指死亡的原因，与参加比赛的语境无关。", "惩罚": "语义：惩罚与说明参赛者来处的语境不相合，句子不通。"}, "sentence_index": 6, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明来源于学校跑回家。", "explanation": "这里应该用〈从〉。来源于说人或事物来的地方，不表示动作的起点；“从学校跑回家”的起点要用从。"}, {"text": "她来源于热情，主动帮我搬了家。", "explanation": "这里应该用〈出于〉。来源于说人或事物来的地方，不表示行为的动机；“出于热情”要用出于。"}, {"text": "这把椅子来源于家具。", "explanation": "这里应该用〈属于〉。来源于说人或事物来的地方，不表示类别归属；“椅子属于家具”才是类别关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这束花来源于了云南的一个小园子。", "corrected_sentence": "这束花来源于云南的一个小园子。", "error_description": "“来源于”后面不能加“了”。写成“来源于了”是误用，正确形式为“来源于云南的一个小园子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把这批鱼来源于海边的渔船。", "corrected_sentence": "这批鱼来源于海边的渔船。", "error_description": "“来源于”不是处置动词，前面不能加“把”把宾语提前。正确形式为“这批鱼来源于海边的渔船”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3705f554-5cf5-40b2-99a5-64b9c475358f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
