INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西剪开或剪掉。", "primary_collocate": null, "pronunciation": "jiǎn qiē", "ipa": "tɕjɛn˨˩˦ tɕʰjɛ˥˥", "syllable_count": 2, "sentences": [{"text": "他用剪刀剪切了一块红布。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张纸剪切成两半。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把多余的线头剪切掉了。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这块布剪切一下，只要左边的部分。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她仔细地把手里的彩纸剪切成条。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用大剪刀剪切铁皮。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上把彩纸剪切成花瓣。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他剪切过很多种形状的纸。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条绳子太长了，你剪切一段吧。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剪切之前，先用笔画一条线。", "target_word": "剪切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剪切了", "label": "体标（了）"}, {"form": "剪切着", "label": "体标（着）"}, {"form": "剪切过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "剪切：用剪刀把纸、布等东西剪开或剪掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剪切", "is_correct": true, "explanation": "正确：“用剪刀剪切”指用剪刀把布剪开，符合句中的工具和动作。"}, {"text": "粘贴", "is_correct": false, "explanation": "配价：粘贴需要说明贴到哪里，不能说“用剪刀粘贴一块布”。"}, {"text": "复制", "is_correct": false, "explanation": "语义：复制指复制内容，与用剪刀把布切开不符。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指降温，与用剪刀裁布无关。"}], "explanations": {"剪切": "正确：“用剪刀剪切”指用剪刀把布剪开，符合句中的工具和动作。", "粘贴": "配价：粘贴需要说明贴到哪里，不能说“用剪刀粘贴一块布”。", "复制": "语义：复制指复制内容，与用剪刀把布切开不符。", "冷却": "语义：冷却指降温，与用剪刀裁布无关。"}, "sentence_index": 0, "correct_answer": "剪切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用刀把蛋糕剪切成小块。", "explanation": "这里应该用〈切割〉。用刀切东西说“切”或“切割”，剪切要用剪刀等工具把东西剪开。"}, {"text": "他把这块石头剪切成了两半。", "explanation": "这里应该用〈凿〉。剪切只用于剪刀能剪开的薄软东西，石头这样的硬物要用“凿”。"}, {"text": "他用手把纸剪切开了。", "explanation": "这里应该用〈撕〉。剪切要借助剪刀等工具，徒手把纸弄开要说“撕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剪切", "is_correct": true, "explanation": "正确：“把彩纸剪切成花瓣”指用剪刀把彩纸剪成所需形状，符合课上手工的语境。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵指微生物作用使物质变化，与剪纸做花无关。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指降温，与课上做手工无关。"}, {"text": "升华", "is_correct": false, "explanation": "搭配：“升华”不用于剪纸做花这类手工动作。"}], "explanations": {"剪切": "正确：“把彩纸剪切成花瓣”指用剪刀把彩纸剪成所需形状，符合课上手工的语境。", "发酵": "语义：发酵指微生物作用使物质变化，与剪纸做花无关。", "冷却": "语义：冷却指降温，与课上做手工无关。", "升华": "搭配：“升华”不用于剪纸做花这类手工动作。"}, "sentence_index": 6, "correct_answer": "剪切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用锯子把木板剪切开了。", "explanation": "这里应该用〈锯〉。木板这样的硬物要用锯子锯开，剪切用于剪刀能剪开的东西。"}, {"text": "他用胶水把两张纸剪切在一起。", "explanation": "这里应该用〈粘〉。剪切是把东西剪开或剪掉，把两张纸接在一起要用“粘”。"}, {"text": "他把苹果剪切了皮，切成块。", "explanation": "这里应该用〈削〉。去掉果皮要用刀“削”，不说“剪切皮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用剪刀把彩纸剪切。", "corrected_sentence": "她用剪刀把彩纸剪切成了两段。", "error_description": "补语缺失：“把”字句中“剪切”后须带结果补语或“了”，应说“把彩纸剪切成了两段”，不能只说“把彩纸剪切”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这根绳子剪切了成两截。", "corrected_sentence": "我把这根绳子剪切成了两截。", "error_description": "错误形式：剪切了成两截；正确形式：剪切成了两截。原因：结果补语“成”紧跟动词，动态助词“了”应放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
