INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "翅膀的尖尖的部分。", "primary_collocate": null, "pronunciation": "yì jiān", "ipa": "i˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "小鸟的翼尖是白色的。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶停下来，翼尖轻轻动着。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的翼尖亮着红灯。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰张开翅膀时，翼尖朝上翘着。", "target_word": "翼尖", "complexity_tier": "T3", "furigana": "yì jiān", "sentence_source": "generated"}, {"text": "孩子用手摸了摸模型飞机的翼尖。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞过树旁时，翼尖碰到了树叶。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海鸥的翼尖沾了一点水。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纸飞机的翼尖折了起来。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟的翼尖受伤了。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天鹅张开翅膀，翼尖几乎碰到水面。", "target_word": "翼尖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个翼尖", "label": "量词"}, {"form": "翼尖涡流", "label": "复合"}], "register": "中性", "sense_fingerprint": "翅膀尖尖的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：翅膀尖尖的部分，即本题目标词。"}, {"text": "意见", "is_correct": false, "explanation": "jiàn（第四声）与 jiān（第一声）声调不同，意思是看法。"}, {"text": "一键", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一键指按一下按键，是常见用语。"}, {"text": "议价", "is_correct": false, "explanation": "jià（第四声）与 jiān（第一声）声调不同，意思是讨价还价。"}], "explanations": {"翼尖": "翼尖：翅膀尖尖的部分，即本题目标词。", "意见": "jiàn（第四声）与 jiān（第一声）声调不同，意思是看法。", "一键": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一键指按一下按键，是常见用语。", "议价": "jià（第四声）与 jiān（第一声）声调不同，意思是讨价还价。"}, "sentence_index": null, "correct_answer": "翼尖"}, "level_3": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：小鸟翅膀尖尖的部分，可以是白色的，与句意相符。"}, {"text": "鳍", "is_correct": false, "explanation": "语义：鳍是鱼类的游动器官，小鸟没有鳍，不能说它的鳍是白色的。"}, {"text": "鬃毛", "is_correct": false, "explanation": "语义：鬃毛长在马等动物的颈背上，小鸟身上没有鬃毛。"}, {"text": "蹄", "is_correct": false, "explanation": "搭配：“蹄”指有蹄动物的脚，用来描述小鸟的部位不合常规。"}], "explanations": {"翼尖": "翼尖：小鸟翅膀尖尖的部分，可以是白色的，与句意相符。", "鳍": "语义：鳍是鱼类的游动器官，小鸟没有鳍，不能说它的鳍是白色的。", "鬃毛": "语义：鬃毛长在马等动物的颈背上，小鸟身上没有鬃毛。", "蹄": "搭配：“蹄”指有蹄动物的脚，用来描述小鸟的部位不合常规。"}, "sentence_index": 0, "correct_answer": "翼尖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蝴蝶收起翼尖，停在花上。", "explanation": "这里应该用〈翅膀〉。翼尖只指翅膀的末端，收起要用整对翅膀。"}, {"text": "这把刀的翼尖很锋利。", "explanation": "这里应该用〈尖端〉。翼尖只用于鸟或飞机的翅膀，刀的尖端不能说翼尖。"}, {"text": "这块石头的翼尖很硬。", "explanation": "这里应该用〈尖角〉。翼尖只指翅膀的末端，石头的尖角不能说翼尖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24198, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：翅膀尖尖的部分，即本题目标词。"}, {"text": "异见", "is_correct": false, "explanation": "jiàn（第四声）与 jiān（第一声）声调不同，意思是不同的看法。"}, {"text": "一件", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一件指一个物品。"}, {"text": "一间", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，一间指一个房间。"}], "explanations": {"翼尖": "翼尖：翅膀尖尖的部分，即本题目标词。", "异见": "jiàn（第四声）与 jiān（第一声）声调不同，意思是不同的看法。", "一件": "yī（第一声）与 yì（第四声）、jiàn（第四声）与 jiān（第一声）声调都不同，一件指一个物品。", "一间": "yī（第一声）与 yì（第四声）声调不同，一间指一个房间。"}, "sentence_index": null, "correct_answer": "翼尖"}, "level_3": {"options": [{"text": "翼尖", "is_correct": true, "explanation": "翼尖：海鸥翅膀尖尖的部分，沾了水，与句意相符。"}, {"text": "鳃", "is_correct": false, "explanation": "语义：鳃是鱼类呼吸的器官，海鸥用肺呼吸，不能说它的鳃沾了水。"}, {"text": "触角", "is_correct": false, "explanation": "语义：触角是昆虫等的感觉器官，海鸥没有触角。"}, {"text": "鳞", "is_correct": false, "explanation": "体貌：海鸥身上长的是羽毛，不长鳞片。"}], "explanations": {"翼尖": "翼尖：海鸥翅膀尖尖的部分，沾了水，与句意相符。", "鳃": "语义：鳃是鱼类呼吸的器官，海鸥用肺呼吸，不能说它的鳃沾了水。", "触角": "语义：触角是昆虫等的感觉器官，海鸥没有触角。", "鳞": "体貌：海鸥身上长的是羽毛，不长鳞片。"}, "sentence_index": 6, "correct_answer": "翼尖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天鹅收起翅膀，一把翼尖几乎碰到水面。", "explanation": "这里应该用〈个〉。“把”用于有柄的器物，不能用来计量翼尖。"}, {"text": "一根翼尖从天鹅的翅膀上伸了出来，几乎碰到水面。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，翼尖不能用“根”计量。"}, {"text": "天鹅的翅膀上，一条翼尖几乎碰到了水面。", "explanation": "这里应该用〈个〉。“条”用于长条形物件，翼尖不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水沾在猫头鹰的一座翼尖上。", "corrected_sentence": "雨水沾在猫头鹰的一个翼尖上。", "error_description": "量词错误：翼尖应用“个”计量，“座”用于山、楼等大型固定的东西，不能用来计量翼尖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一颗翼尖上落着一只蝴蝶。", "corrected_sentence": "一个翼尖上落着一只蝴蝶。", "error_description": "量词错误：“颗”用于粒状的小东西，翼尖不能用“颗”计量，应为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
