INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "雷诺数是一个数字，科学家用它来看液体或气体流动的样子。", "primary_collocate": null, "pronunciation": "léi nuò shù", "ipa": "leɪ˧˥ nwɔ˥˩ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "科学家用雷诺数看水怎么流。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雷诺数很大，水流很乱。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了雷诺数。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷诺数小的时候，水流得很平稳。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这根管子的雷诺数。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流动的样子，可以用雷诺数表示。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算雷诺数时，要用到速度和管子的粗细。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷诺数是个数字，没有单位。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们查过书，找到了雷诺数的意思。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流变快，雷诺数就会变大。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "临界雷诺数", "label": "复合"}], "register": "中性", "sense_fingerprint": "雷诺数：科学家用来看液体或气体怎样流动的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雷诺数", "is_correct": true, "explanation": "正确：雷诺数是科学家用来观察液体或气体流动样子的数字，句中“用……看水怎么流”与之相符。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机用来接收广播，不能用来观察水的流动状态。"}, {"text": "拼图", "is_correct": false, "explanation": "语义：拼图是拼接图案的玩具，不能用来观察水的流动。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱记录音乐，与水的流动无关，句子语义不通。"}], "explanations": {"雷诺数": "正确：雷诺数是科学家用来观察液体或气体流动样子的数字，句中“用……看水怎么流”与之相符。", "收音机": "语义：收音机用来接收广播，不能用来观察水的流动状态。", "拼图": "语义：拼图是拼接图案的玩具，不能用来观察水的流动。", "乐谱": "语义：乐谱记录音乐，与水的流动无关，句子语义不通。"}, "sentence_index": 0, "correct_answer": "雷诺数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘船模的雷诺数决定了水面波浪的高度。", "explanation": "这里应该用〈弗劳德数〉。弗劳德数用于分析自由液面的波浪与流动；雷诺数只用来判断层流或湍流，不能决定波浪高度。"}, {"text": "这股水流的雷诺数是每秒三米。", "explanation": "这里应该用〈流速〉。雷诺数无单位，不能用“每秒三米”来表示流动的速度；速度要用流速。"}, {"text": "这架飞机的雷诺数已经超过了声速。", "explanation": "这里应该用〈马赫数〉。马赫数是飞行速度与声速之比，可以与声速比较；雷诺数只用来判断流动状态，不能与速度比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雷诺数", "is_correct": true, "explanation": "正确：句中说“算雷诺数时要用到速度和管子的粗细”，雷诺数是可以计算的量。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算”的宾语应是可以计算的量，“颜色”是性质，不能被计算。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与流速和管径无关，句中所说的计算不涉及体重。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是经济概念，与流体的速度和管子的粗细无关，句子语义不通。"}], "explanations": {"雷诺数": "正确：句中说“算雷诺数时要用到速度和管子的粗细”，雷诺数是可以计算的量。", "颜色": "搭配：“算”的宾语应是可以计算的量，“颜色”是性质，不能被计算。", "体重": "语义：体重与流速和管径无关，句中所说的计算不涉及体重。", "价格": "语义：价格是经济概念，与流体的速度和管子的粗细无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "雷诺数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "管道里的雷诺数超过了一百帕。", "explanation": "这里应该用〈压强〉。压强以帕为单位，雷诺数无单位，不能与“一百帕”比较大小。"}, {"text": "这种油的雷诺数决定了它的导热能力。", "explanation": "这里应该用〈普朗特数〉。导热能力由普朗特数反映，雷诺数只用来判断流动状态。"}, {"text": "他把雷诺数装进了瓶子里。", "explanation": "雷诺数是一个无量纲的数字，不是能装进瓶子的物质，用法错误；它用来判断流动状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他算出了这只雷诺数。", "corrected_sentence": "他算出了这个雷诺数。", "error_description": "错误在于目标词“雷诺数”的量词用了“只”，“只”用于动物或成对的东西；雷诺数应用“个”计量，应为“这个雷诺数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂的工程师算出了这条河的一本雷诺数。", "corrected_sentence": "工厂的工程师算出了这条河的雷诺数。", "error_description": "量词错误：“本”用于书册，不能用来计量雷诺数；应去掉“一本”，说“这条河的雷诺数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
