INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做一件事时，另外得到的东西。", "primary_collocate": null, "pronunciation": "fù chǎn pǐn", "ipa": "fu˥˩ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "榨油以后剩下的饼是副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做豆浆的副产品是豆渣。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家牛奶厂用副产品做奶酪。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "造纸时会有不少副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炼油厂把副产品卖给化工厂。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养蜂的副产品有蜂蜡和蜂王浆。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "副产品有时比主要产品更值钱。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒厂的副产品是酒糟。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把副产品做成了肥料。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "切肉时剩下的骨头成了副产品。", "target_word": "副产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种副产品", "label": "量词"}, {"form": "副产物", "label": "复合"}, {"form": "副產品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做一件事时另外得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0df9f5e-58ee-462e-824d-40cfef81d3d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副产品", "is_correct": true, "explanation": "正确：饼是榨油时附带剩下的东西，与“做一件事时另外得到的东西”的意思相符。"}, {"text": "工具", "is_correct": false, "explanation": "语义：饼是榨油后的残渣，不是用来做事的器具，句子语义不通。"}, {"text": "原油", "is_correct": false, "explanation": "语义：原油是榨出来的主要产物，不是剩下的饼，与句中“剩下的”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“是颜色”无法用来指“饼”这种实物，颜色是事物的性质。"}], "explanations": {"副产品": "正确：饼是榨油时附带剩下的东西，与“做一件事时另外得到的东西”的意思相符。", "工具": "语义：饼是榨油后的残渣，不是用来做事的器具，句子语义不通。", "原油": "语义：原油是榨出来的主要产物，不是剩下的饼，与句中“剩下的”矛盾。", "颜色": "搭配：“是颜色”无法用来指“饼”这种实物，颜色是事物的性质。"}, "sentence_index": 0, "correct_answer": "副产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的副产品是一位老板。", "explanation": "这里应该用〈人〉。副产品是事物，不能指人。"}, {"text": "服用这种药后，副产品是失眠。", "explanation": "这里应该用〈副作用〉。副作用指药物在治疗作用之外产生的不良反应；副产品是做一件事时另外得到的东西，不能指药物的不良影响。"}, {"text": "他们的主要工作是生产副产品。", "explanation": "这里的主次颠倒。副产品是主要产品之外附带得到的，不能当作主要的生产目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副产品", "is_correct": true, "explanation": "正确：句中说副产品有时比主要产品更值钱，“副产品”指附带得到的东西，可以有价值。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“比……更值钱”搭配，颜色不是可以估价的东西。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指位置的指向，不指可以买卖的东西，与“值钱”的意思不符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人或动物身体的温度，与产品价值无关，句子语义不通。"}], "explanations": {"副产品": "正确：句中说副产品有时比主要产品更值钱，“副产品”指附带得到的东西，可以有价值。", "颜色": "搭配：“颜色”不能与“比……更值钱”搭配，颜色不是可以估价的东西。", "方向": "语义：方向指位置的指向，不指可以买卖的东西，与“值钱”的意思不符。", "体温": "语义：体温指人或动物身体的温度，与产品价值无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "副产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位副产品是一名老师。", "explanation": "这里应该用〈人〉。副产品是事物，不能指人。"}, {"text": "这家工厂的主要产品是副产品。", "explanation": "这里把副产品当成了主角：副产品是做一件事时另外得到的东西，不能充当生产的主要目标。"}, {"text": "妈妈把副产品叫回家吃饭。", "explanation": "这里应该用〈孩子〉。副产品是事物，不能被叫回家吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些麸皮是磨面得副产品。", "corrected_sentence": "这些麸皮是磨面的副产品。", "error_description": "错误在于修饰语“磨面”与中心语“副产品”之间用了“得”，应为结构助词“的”；“得”不能用在名词前作定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "榨油厂每天都会得到一本副产品。", "corrected_sentence": "榨油厂每天都会得到一种副产品。", "error_description": "量词错误：“本”用于书册，副产品应用“种”计量，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95527f2e-4ef0-416b-ab68-7d4000280bb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
