INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24208, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟着别人走，或者听别人的话。", "primary_collocate": null, "pronunciation": "suí", "ipa": "sweɪ˧˥", "syllable_count": 1, "sentences": [{"text": "孩子随妈妈去超市买菜了。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗随主人走进了公园。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他随父母搬到了北京。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我随老师去参观博物馆。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们随老师走出了教室。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一向随父母的安排行事。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}, {"text": "在家里，我常随爸爸去钓鱼。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}, {"text": "游客们随导游向山上走去。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她随丈夫去了国外工作。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟随哥哥去了学校。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "跟着某人行动，或听从某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟着某人行动或听从某人。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。"}, {"text": "虽", "is_correct": false, "explanation": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}], "explanations": {"随": "随（suí，第二声）：跟着某人行动或听从某人。", "岁": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。", "穗": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。", "虽": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“孩子随妈妈去超市”表示跟着妈妈一起行动。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂妈妈”与一起去超市买菜的行动不符。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢妈妈”与一起去超市买菜的行动不符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂妈妈”不能表示跟着一起行动，这个动词不能这样搭配。"}], "explanations": {"随": "正确。“孩子随妈妈去超市”表示跟着妈妈一起行动。", "骂": "语义：“骂妈妈”与一起去超市买菜的行动不符。", "抢": "语义：“抢妈妈”与一起去超市买菜的行动不符。", "挂": "搭配：“挂妈妈”不能表示跟着一起行动，这个动词不能这样搭配。"}, "sentence_index": 0, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他约定三个月后随即回信。", "explanation": "这里应该用〈过一段时间〉。“随即”表示紧接着立刻发生，不能与“三个月后”连用。"}, {"text": "她随身跑去了门口。", "explanation": "这里应该用〈飞快〉。“随身”指东西带在身上，不能用来形容跑步。"}, {"text": "他随口把钥匙交给了我。", "explanation": "这里应该用〈顺手〉。“随口”只用于说话，把东西交给别人这类动作不能用随口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24208, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟着某人行动或听从某人。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。"}, {"text": "隧", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}], "explanations": {"随": "随（suí，第二声）：跟着某人行动或听从某人。", "碎": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。", "穗": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。", "隧": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“我常随爸爸去钓鱼”表示跟着爸爸一起去钓鱼。"}, {"text": "讥笑", "is_correct": false, "explanation": "语义：“讥笑爸爸去钓鱼”与一起出门钓鱼的意思不符。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：“咒骂爸爸去钓鱼”与一起出门钓鱼的意思不符。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔爸爸”不能表示跟着一起去做某事，这个动词不能这样搭配。"}], "explanations": {"随": "正确。“我常随爸爸去钓鱼”表示跟着爸爸一起去钓鱼。", "讥笑": "语义：“讥笑爸爸去钓鱼”与一起出门钓鱼的意思不符。", "咒骂": "语义：“咒骂爸爸去钓鱼”与一起出门钓鱼的意思不符。", "摔": "搭配：“摔爸爸”不能表示跟着一起去做某事，这个动词不能这样搭配。"}, "sentence_index": 6, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一边唱歌，随后一边跳舞。", "explanation": "这里应该用〈同时〉。“随后”表示在某事之后接着发生，不能用于两件事同时进行。"}, {"text": "他随时在去年就来到了北京。", "explanation": "这里应该用〈早在〉。“随时”指任何时候都可以，不能与“去年”这样确定的时间连用。"}, {"text": "他随手叹了一口气，大家都看着他。", "explanation": "这里应该用〈不由自主〉。“随手”指顺着手边的动作，不能用来形容叹气这类不由自主的反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹随去看展览了。", "corrected_sentence": "妹妹随姐姐去看展览了。", "error_description": "错误：“随”后面缺少所跟随的人，“妹妹随去看展览”不完整。正确：“随姐姐去看展览”，补上“姐姐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们很随老师去了美术馆。", "corrected_sentence": "孩子们随老师去了美术馆。", "error_description": "错误：“很”修饰表示跟随动作的动词“随”，不通。正确：去掉“很”，“随老师去了美术馆”。“很”不能修饰这类动作动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
