INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用飞机在天空中飞行的交通方式，或与之有关的事业。", "primary_collocate": null, "pronunciation": "háng kōng", "ipa": "/xɑŋ˧˥ kʰʊŋ˥/", "syllable_count": 2, "sentences": [{"text": "航空让人可以在天上旅行。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对航空很感兴趣。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前在航空部门工作。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空比坐船快多了。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学习航空，将来造飞机。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了航空的故事。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空发展以后，世界变小了。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的航空事业进步很大。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空旅行需要提前买票。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢看航空杂志。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航空公司", "label": "复合词"}, {"form": "航空母舰", "label": "复合词"}, {"form": "航空邮件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "航空|名词|与飞机在天空中飞行有关的交通方式或事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "航空在此指飞机在天上飞行，可以让人在天上旅行。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车在陆地上行驶，不能让人在天上旅行，与后半句冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车行驶在地面上，与“在天上旅行”的语境矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空是场所，不是交通方式，“让人可以……”后不能接场所作主语来表示旅行方式。"}], "explanations": {"航空": "航空在此指飞机在天上飞行，可以让人在天上旅行。", "火车": "语义：火车在陆地上行驶，不能让人在天上旅行，与后半句冲突。", "汽车": "语义：汽车行驶在地面上，与“在天上旅行”的语境矛盾。", "天空": "搭配：天空是场所，不是交通方式，“让人可以……”后不能接场所作主语来表示旅行方式。"}, "sentence_index": 0, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条航空从北京飞往上海，每天有三班。", "explanation": "这里应该用〈航线〉。“条”和“从北京飞往上海”说的是固定线路，航空指飞行事业或交通方式，不能指航线。"}, {"text": "妈妈把航空放进了冰箱。", "explanation": "这里应该用〈牛奶〉。航空是抽象的行业，不是可以放进冰箱的东西。"}, {"text": "今天的航空下了一场大雨，我们只好待在家里。", "explanation": "这里应该用〈天气〉。下大雨说的是天气，航空指飞机，不能作为天气的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "航空在此指飞行业的发展，可以作主语，“航空发展以后”通顺。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习场所，不能发展后使世界变小，与句意不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：厨房是场所，不能作为“发展”的主语来说使世界变小。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是可以“发展”并影响世界的事物，句子不成立。"}], "explanations": {"航空": "航空在此指飞行业的发展，可以作主语，“航空发展以后”通顺。", "教室": "语义：教室是学习场所，不能发展后使世界变小，与句意不符。", "厨房": "搭配：厨房是场所，不能作为“发展”的主语来说使世界变小。", "老虎": "语义：老虎是动物，不是可以“发展”并影响世界的事物，句子不成立。"}, "sentence_index": 6, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘航空在海上航行。", "explanation": "这里应该用〈船〉。在海上航行的是船，航空指空中飞行，不是船只。"}, {"text": "这列航空很快，每天运送很多人。", "explanation": "这里应该用〈地铁〉。“列”用于地铁等车辆，航空不是车辆。"}, {"text": "他是一位很有经验的航空。", "explanation": "这里应该用〈机长〉。“有经验的”修饰的是人，航空是抽象名词，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我航空很感兴趣。", "corrected_sentence": "我对航空很感兴趣。", "error_description": "错误：“感兴趣”的对象前缺少介词“对”，“我航空很感兴趣”不通。正确：“我对航空很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐每周买一个航空杂志。", "corrected_sentence": "姐姐每周买一本航空杂志。", "error_description": "错误：“一个航空杂志”；正确：“一本航空杂志”。“杂志”的量词用“本”，不用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "减小与增大是反义词，指变小或数量变少。"}, {"text": "保持", "is_correct": false, "explanation": "保持表示维持原状，与增大没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是言语交流，与增大没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探求事理，与增大没有反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "减小与增大是反义词，指变小或数量变少。", "保持": "保持表示维持原状，与增大没有反义关系。", "讨论": "讨论是言语交流，与增大没有反义关系。", "研究": "研究是探求事理，与增大没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "减小与增大是反义词，指变小或数量变少。"}, {"text": "建立", "is_correct": false, "explanation": "建立表示创设，与增大没有反义关系。"}, {"text": "通过", "is_correct": false, "explanation": "通过表示经过或批准，与增大没有反义关系。"}, {"text": "组织", "is_correct": false, "explanation": "组织表示安排、集合，与增大没有反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "减小与增大是反义词，指变小或数量变少。", "建立": "建立表示创设，与增大没有反义关系。", "通过": "通过表示经过或批准，与增大没有反义关系。", "组织": "组织表示安排、集合，与增大没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变大，比以前大。", "primary_collocate": null, "pronunciation": "zēng dà", "ipa": "tsəŋ˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "天气变冷，风也增大了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，河水的流量增大了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的压力一天比一天增大。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，城市的面积增大了很多。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音突然增大，孩子吓了一跳。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风增大以后，船开得很慢。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪增大后，他的视力不好了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器的噪音增大，工人受不了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度升高，气体的体积增大了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家之间的差距在增大。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增大了", "label": "完成体"}, {"form": "增大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "自己变大，比以前大（不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：风变大，与「天气变冷」的语境相合，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变为液体，风不能融化。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变为固体，与风的强弱无关。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液态水遇冷变成固体，风不能结冰。"}], "explanations": {"增大": "增大：风变大，与「天气变冷」的语境相合，符合句意。", "融化": "语义：“融化”指固体遇热变为液体，风不能融化。", "凝固": "语义：“凝固”指液体变为固体，与风的强弱无关。", "结冰": "语义：“结冰”指液态水遇冷变成固体，风不能结冰。"}, "sentence_index": 0, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司增大了两个新的部门。", "explanation": "这里应该用〈增设〉。新设立的部门要用增设，增大只说原有事物的变大。"}, {"text": "这次活动增大了一场比赛。", "explanation": "这里应该用〈举办〉。比赛、活动要用举办，增大只说原有事物的变大。"}, {"text": "经过锻炼，他的体质增大了。", "explanation": "这里应该用〈增强〉。体质、力量等抽象的强弱用增强，增大不用于体质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：年纪变大，与「后」和「视力不好」的语境相合，符合句意。"}, {"text": "减小", "is_correct": false, "explanation": "语义：年纪只会增长，不说减小。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：“膨胀”指体积鼓起，不用于年纪。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不用于年纪。"}], "explanations": {"增大": "增大：年纪变大，与「后」和「视力不好」的语境相合，符合句意。", "减小": "语义：年纪只会增长，不说减小。", "膨胀": "语义：“膨胀”指体积鼓起，不用于年纪。", "提高": "搭配：“提高”用于水平、质量，不用于年纪。"}, "sentence_index": 6, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训增大了员工的水平。", "explanation": "这里应该用〈提高〉。水平、质量的提升用提高，增大只说大小、面积的变大。"}, {"text": "这次会议增大了一个小时。", "explanation": "这里应该用〈延长〉。时间的增加要用延长，增大只用于大小、数量、强度的变大。"}, {"text": "这里的环境日益增大。", "explanation": "这里应该用〈恶化〉。环境变坏要用恶化，增大不用于环境的变坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午后，海风逐渐增大了过。", "corrected_sentence": "午后，海风逐渐增大了。", "error_description": "体标错误：“了”与“过”不能同时用在动词后；应说“海风逐渐增大了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里风增大地很快。", "corrected_sentence": "夜里风增大得很快。", "error_description": "错误：补语标记用了“地”。正确：“增大得很快”。“得”引出动词后的补语，说明动作的程度；“地”用于修饰动词，放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
