INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "气动是用空气的力量让东西动起来。", "primary_collocate": null, "pronunciation": "qì dòng", "ipa": "/tɕʰi˥˩ tʊŋ˥˩/", "syllable_count": 2, "sentences": [{"text": "气动玩具靠空气的力量动起来。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个气动装置用空气推动机器。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气动工具工作时会发出响声。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的门是气动的，会自动打开。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用气动装置给我们做了实验。", "target_word": "气动", "complexity_tier": "T3", "furigana": "qì dòng", "sentence_source": "generated"}, {"text": "气动机器人用空气来移动手臂。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种气动刹车比较安全。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把气动设备放进了车间。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气动系统让门慢慢地关上。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在工厂里安装了气动机械。", "target_word": "气动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "氣動", "label": "繁体"}, {"form": "气动工具", "label": "复合词"}, {"form": "气动装置", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "气动|名词|用空气的力量使物体运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a01c2b4-5d6b-4e20-b907-6bc7d46b8ce0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气动", "is_correct": true, "explanation": "气动指利用空气的力量使物体运动，修饰“玩具”，与“靠空气的力量动起来”一致。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子玩具靠电力，不靠空气的力量，与句中的动力来源冲突。"}, {"text": "水力", "is_correct": false, "explanation": "语义：水力靠水流，不是空气的力量，与句中的动力来源冲突。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：煤炭是燃料，不能作为“玩具”的动力方式来修饰，搭配不当。"}], "explanations": {"气动": "气动指利用空气的力量使物体运动，修饰“玩具”，与“靠空气的力量动起来”一致。", "电子": "语义：电子玩具靠电力，不靠空气的力量，与句中的动力来源冲突。", "水力": "语义：水力靠水流，不是空气的力量，与句中的动力来源冲突。", "煤炭": "搭配：煤炭是燃料，不能作为“玩具”的动力方式来修饰，搭配不当。"}, "sentence_index": 0, "correct_answer": "气动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门是气动的，靠太阳能自动开关。", "explanation": "这里应该用〈太阳能〉。靠太阳能开关属于太阳能装置，不是靠空气的力量驱动。"}, {"text": "这台气动玩具车靠电池跑起来。", "explanation": "这里应该用〈电动〉。靠电池驱动属于电动，气动靠空气的力量。"}, {"text": "这个气动装置靠水流推动叶轮。", "explanation": "这里应该用〈水力〉。水流推动叶轮是水力，气动靠空气的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气动", "is_correct": true, "explanation": "气动刹车靠空气的力量控制，符合“这种……刹车比较安全”的语境。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓是水果，不是刹车的类别，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是刹车的类型，与“刹车”冲突。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包不能用来修饰刹车的类别，“这种……刹车”的修饰语搭配不当。"}], "explanations": {"气动": "气动刹车靠空气的力量控制，符合“这种……刹车比较安全”的语境。", "草莓": "语义：草莓是水果，不是刹车的类别，句子不通。", "冰箱": "语义：冰箱是家电，不是刹车的类型，与“刹车”冲突。", "书包": "搭配：书包不能用来修饰刹车的类别，“这种……刹车”的修饰语搭配不当。"}, "sentence_index": 6, "correct_answer": "气动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台气动机器靠火力来工作。", "explanation": "这里应该用〈内燃〉。靠燃烧产生动力属于内燃机的工作方式，气动靠的是空气的力量，不能说“气动机器靠火力来工作”。"}, {"text": "这个气动装置靠磁铁吸住门。", "explanation": "这里应该用〈磁力〉。靠磁铁吸住门是磁力作用，不是空气的力量。"}, {"text": "这台气动机靠电流带动转子转动。", "explanation": "这里应该用〈电动机〉。靠电流带动转子是电动机的原理，动力来自电，不是空气的力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器是气动，声音很小。", "corrected_sentence": "这台机器是气动的，声音很小。", "error_description": "错误：“是气动，声音很小”；正确：“是气动的，声音很小”。“是……的”结构中，“的”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张气动工具很贵。", "corrected_sentence": "这些气动工具很贵。", "error_description": "错误：“这张气动工具”。“张”用于平面的东西，不能用于工具；工具可用“这套”“这件”，也可改用复数的“这些”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a01a5ec-b172-47b7-b1b5-259feb27a7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
