INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "构型是东西的形状和样子。", "primary_collocate": null, "pronunciation": "gòu xíng", "ipa": "kou˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这架飞机的构型很特别。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器的构型很简单。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "设计师改变了桌子的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车的构型和旧车不一样。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥的构型让我很吃惊。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师在图上画出了机器的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一下这个玩具的构型吧。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两栋楼的构型差不多。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很喜欢这种房子的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种零件的构型太复杂，工人很难加工。", "target_word": "构型", "complexity_tier": "T3", "furigana": "zhè zhǒng líng jiàn de gòu xíng tài fù zá, gōng rén hěn nán jiā gōng。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种构型", "label": "量词"}, {"form": "整体构型", "label": "复合"}, {"form": "構型", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "机器、建筑等东西的整体形状和样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：听到的是“构型”（gòu xíng），指东西的整体形状和样子。"}, {"text": "钩形", "is_correct": false, "explanation": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。"}, {"text": "厚型", "is_correct": false, "explanation": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。"}, {"text": "豆形", "is_correct": false, "explanation": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}], "explanations": {"构型": "正确：听到的是“构型”（gòu xíng），指东西的整体形状和样子。", "钩形": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。", "厚型": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。", "豆形": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}, "sentence_index": null, "correct_answer": "构型"}, "level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：构型指飞机的整体形状，“很特别”正符合这里的描述。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：说飞机“年龄很特别”不成立，年龄与外形无关。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指人受教育的经历，飞机不能有学历，“学历很特别”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：飞机没有脾气，“脾气很特别”不成立。"}], "explanations": {"构型": "正确：构型指飞机的整体形状，“很特别”正符合这里的描述。", "年龄": "语义：说飞机“年龄很特别”不成立，年龄与外形无关。", "学历": "语义：学历指人受教育的经历，飞机不能有学历，“学历很特别”不成立。", "脾气": "语义：飞机没有脾气，“脾气很特别”不成立。"}, "sentence_index": 0, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的构型很苗条。", "explanation": "这里应该用〈体型〉。构型指东西的整体形状，人的身材要用体型。"}, {"text": "这个方案的构型很便宜。", "explanation": "这里应该用〈成本〉。便宜形容价格或费用；构型指东西的外形结构，方案的花费要说成本。"}, {"text": "他在大家心中的构型很好。", "explanation": "这里应该用〈形象〉。构型指东西的外形结构，人在别人心中的印象要用形象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：“看一下”针对可见的外形，玩具的构型可以用眼睛看。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”针对视觉，声音应该说“听”，不说“看一下声音”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”要用“闻”或“尝”，不能说“看一下味道”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：玩具没有性格，“看一下这个玩具的性格”不成立。"}], "explanations": {"构型": "正确：“看一下”针对可见的外形，玩具的构型可以用眼睛看。", "声音": "搭配：“看”针对视觉，声音应该说“听”，不说“看一下声音”。", "味道": "搭配：“味道”要用“闻”或“尝”，不能说“看一下味道”。", "性格": "语义：玩具没有性格，“看一下这个玩具的性格”不成立。"}, "sentence_index": 6, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个水壶的构型很香。", "explanation": "这里应该用〈气味〉。香说的是气味，水壶的形状不能用香来形容，应说“气味很香”。"}, {"text": "这个舞蹈的构型很优美。", "explanation": "这里应该用〈动作〉。构型指静止物体的形状，舞蹈的动态要用动作。"}, {"text": "这块布的构型很鲜艳。", "explanation": "这里应该用〈颜色〉。构型指东西的形状结构，布料的色彩不属于构型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座塔有一只独特的构型。", "corrected_sentence": "那座塔有一种独特的构型。", "error_description": "量词错误：“构型”前应用量词“种”，“只”不能用于构型。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个玩具的构型的很特别。", "corrected_sentence": "这个玩具的构型很特别。", "error_description": "“的”位置错误：“构型”后不能再接“的”，应说“这个玩具的构型很特别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
