INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "飞机飞行时向上的力和向后的力。", "primary_collocate": null, "pronunciation": "shēng zǔ", "ipa": "ʂɤŋ˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "飞机飞行时有升阻。", "target_word": "升阻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机翼会产生升阻。", "target_word": "升阻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小飞机的升阻不太大。", "target_word": "升阻", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风大的时候，飞机的升阻会变。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生在课上画了升阻的图。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里说明了飞机的升阻。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机飞得越快，升阻越大。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们算飞机的升阻。", "target_word": "升阻", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师先算出了飞机的升阻。", "target_word": "升阻", "complexity_tier": "T3", "furigana": "gōng chéng shī xiān suàn chū le fēi jī de shēng zǔ。", "sentence_source": "generated"}, {"text": "如果升阻变小，飞机就飞不高。", "target_word": "升阻", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "升阻比", "label": "复合"}, {"form": "升阻", "label": "简体"}], "register": "书面语", "sense_fingerprint": "飞机飞行时向上的力和向后的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升阻", "is_correct": true, "explanation": "正确：飞机飞行时确实存在升阻，这是它的空气动力之一。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：飞机没有脾气，“飞行时有脾气”不成立。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”只说人或动物，不说飞机的相貌。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与飞行时的受力无关，“飞行时有年龄”不成立。"}], "explanations": {"升阻": "正确：飞机飞行时确实存在升阻，这是它的空气动力之一。", "脾气": "语义：飞机没有脾气，“飞行时有脾气”不成立。", "相貌": "体貌：“相貌”只说人或动物，不说飞机的相貌。", "年龄": "语义：年龄与飞行时的受力无关，“飞行时有年龄”不成立。"}, "sentence_index": 0, "correct_answer": "升阻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "升阻让苹果落到地上。", "explanation": "这里应该用〈重力〉。升阻只指飞机飞行时的升力与阻力，苹果下落靠重力。"}, {"text": "书对桌子的升阻很大，桌子快要坏了。", "explanation": "这里应该用〈压力〉。升阻不用于静止物体之间的压力，只指飞机飞行时的力。"}, {"text": "汽车的升阻很强，爬坡很快。", "explanation": "这里应该用〈动力〉。升阻不能表示汽车的动力，爬坡靠的是动力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升阻", "is_correct": true, "explanation": "正确：飞得越快，升阻越大，符合空气动力的规律。"}, {"text": "味道", "is_correct": false, "explanation": "语义：飞得越快，味道不会变大，句子不成立。"}, {"text": "性别", "is_correct": false, "explanation": "语义：速度与性别无关，“性别越大”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身材，飞机没有身高。"}], "explanations": {"升阻": "正确：飞得越快，升阻越大，符合空气动力的规律。", "味道": "语义：飞得越快，味道不会变大，句子不成立。", "性别": "语义：速度与性别无关，“性别越大”不成立。", "身高": "体貌：“身高”指人的身材，飞机没有身高。"}, "sentence_index": 6, "correct_answer": "升阻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块电池的升阻升高了。", "explanation": "这里应该用〈温度〉。升阻是飞机飞行时的力，不能表示电池的冷热变化。"}, {"text": "这辆车的升阻变快了。", "explanation": "这里应该用〈速度〉。升阻不能表示快慢，车子变快要说速度。"}, {"text": "这头牛的升阻有五百公斤。", "explanation": "这里应该用〈体重〉。升阻是力的合称，不能用公斤计量牛的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种小飞机的升阻通常不多。", "corrected_sentence": "这种小飞机的升阻通常不大。", "error_description": "程度错误：错误形式为“不多”，正确形式为“不大”。升阻是抽象的力，程度用“大”或“小”表示；“多”用于可数的事物，不能修饰升阻。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机的一个升阻变大了。", "corrected_sentence": "飞机的升阻变大了。", "error_description": "量词错误：“升阻”是抽象名词，不用“个”计量，应说“飞机的升阻”，去掉“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
