INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24232, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西或标准来比较，看看有多长、多重、多大。", "primary_collocate": null, "pronunciation": "héng liáng", "ipa": "xɤŋ³⁵ ljɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "古人用斗来衡量粮食有多少。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用尺子衡量一下这张桌子有多长。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用天平衡量两块石头哪块更重。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人用秤衡量每袋米有多重。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用卡尺衡量零件有多大。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想衡量一下这个房间有多大。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的人没有尺，就用手来衡量布有多长。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用杯子衡量米和水的多少。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子衡量这棵树有多粗。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁缝用软尺衡量客人的腰围。", "target_word": "衡量", "complexity_tier": "T3", "furigana": "cái féng yòng ruǎn chǐ héng liàng kè rén de yāo wéi", "sentence_source": "generated"}], "morphological_forms": [{"form": "衡量了", "label": "完成体"}, {"form": "衡量过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用工具测量长短轻重大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15509b16-687f-4575-9b2c-b1c6ed693810') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "衡量：用标准或工具比较长短、轻重、大小，与“用斗来……有多少”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：斗是量器，“煮”是加热烹饪的动作，不能表示用斗度量粮食的多少。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示进食，与斗的度量功能和“有多少”的数量比较都无关。"}, {"text": "翻炒", "is_correct": false, "explanation": "语义：“翻炒”是加工食物的动作，与用斗度量粮食的意思不相容。"}], "explanations": {"衡量": "衡量：用标准或工具比较长短、轻重、大小，与“用斗来……有多少”的语境相符。", "煮": "搭配：斗是量器，“煮”是加热烹饪的动作，不能表示用斗度量粮食的多少。", "吃": "语义：“吃”表示进食，与斗的度量功能和“有多少”的数量比较都无关。", "翻炒": "语义：“翻炒”是加工食物的动作，与用斗度量粮食的意思不相容。"}, "sentence_index": 0, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我衡量了一下桌上有几个苹果。", "explanation": "这里应该用〈数〉。衡量指用标准比较长短、轻重、大小，数数量要用“数”。"}, {"text": "医生衡量了一下他的心跳。", "explanation": "这里应该用〈听〉。衡量是比较尺寸或重量，听心跳要用“听”。"}, {"text": "我衡量了一下窗外有没有雨。", "explanation": "这里应该用〈看〉。衡量需要用标准比较，看有没有下雨要用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "衡量：用手比较布的长短，符合“没有尺”的语境。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝布”指加工布料，不能接“有多长”表示量度的结果。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”是把布织出来的动作，与用手测量布的长度无关。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是分割的动作，不表示测量布有多长。"}], "explanations": {"衡量": "衡量：用手比较布的长短，符合“没有尺”的语境。", "缝": "搭配：“缝布”指加工布料，不能接“有多长”表示量度的结果。", "织": "语义：“织”是把布织出来的动作，与用手测量布的长度无关。", "切": "语义：“切”是分割的动作，不表示测量布有多长。"}, "sentence_index": 6, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我衡量了一下字典，找到了那个生词。", "explanation": "这里应该用〈查〉。衡量指用标准比较长短、轻重、大小，在字典里找生词要用“查”。"}, {"text": "我衡量了一下，大声喊了他的名字。", "explanation": "这里应该用〈叫〉。衡量指用标准比较长短、轻重、大小，大声呼唤别人要用“叫”。"}, {"text": "妈妈衡量了一下，就用手摸了摸孩子的额头。", "explanation": "这里应该用〈摸〉。衡量指用标准比较长短、轻重、大小，用手轻触要用“摸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用卡尺衡量在零件的长度。", "corrected_sentence": "工人用卡尺衡量了零件的长度。", "error_description": "“在”表示动作正在进行，应放在动词前；“衡量”后接完成体“了”，应写作“衡量了零件的长度”，不能说“衡量在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用秤衡量了过很多次米的重量。", "corrected_sentence": "她用秤衡量过很多次米的重量。", "error_description": "“了”与“过”不能同时用在同一动词上：表示经历应说“衡量过”，不说“衡量了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff4da09-972d-4400-b83f-a50f503e9442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
