INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "复合材料是用两种或多种不同的东西做成的材料。", "primary_collocate": null, "pronunciation": "fù hé cái liào", "ipa": "fu˥˩ xɤ˧˥ tsʰaɪ˧˥ ljaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这个球拍是用复合材料做的。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料是由几种东西做成的。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车的外壳用了复合材料，所以很轻。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种复合材料又轻又结实。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃钢是一种复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼竿常用复合材料来做。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把塑料和纤维做成复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料不容易坏，可以用很久。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪板的材料是复合材料，不是木头。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种复合材料", "label": "量词搭配"}, {"form": "碳纤维复合材料", "label": "复合词"}, {"form": "複合材料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用两种或多种不同东西做成的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：用两种或多种不同东西做成，符合句中球拍的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法做成球拍，句子说不通。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用来做球拍，句意不通。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：面粉用于做食物，不用于做球拍。"}], "explanations": {"复合材料": "复合材料：用两种或多种不同东西做成，符合句中球拍的语境。", "空气": "语义：空气无法做成球拍，句子说不通。", "水": "语义：水不能用来做球拍，句意不通。", "面粉": "搭配：面粉用于做食物，不用于做球拍。"}, "sentence_index": 0, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生病了，在医院打了一针复合材料。", "explanation": "这里应该用〈药〉。复合材料不是药物，不能拿来打针，打针的是药。"}, {"text": "我今天煮了一碗复合材料。", "explanation": "这里应该用〈面条〉。复合材料不能吃，不能当作食物煮来吃。"}, {"text": "我给妈妈打了复合材料。", "explanation": "这里应该用〈电话〉。复合材料不是通讯工具，打电话才用打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：用塑料和纤维等做成，符合句中的语境。"}, {"text": "面条", "is_correct": false, "explanation": "语义：塑料和纤维不能做成面条，句子说不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包是食物，不能用塑料和纤维做成。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：塑料和纤维不会凝结成冰块，句意不通。"}], "explanations": {"复合材料": "复合材料：用塑料和纤维等做成，符合句中的语境。", "面条": "语义：塑料和纤维不能做成面条，句子说不通。", "面包": "搭配：面包是食物，不能用塑料和纤维做成。", "冰块": "语义：塑料和纤维不会凝结成冰块，句意不通。"}, "sentence_index": 6, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我住在复合材料里。", "explanation": "这里应该用〈房子〉。复合材料不是居住的地方，住要在房子里。"}, {"text": "他开着复合材料去上班。", "explanation": "这里应该用〈汽车〉。复合材料不能用来开，开的是汽车。"}, {"text": "他在台上唱复合材料。", "explanation": "这里应该用〈歌〉。复合材料不能唱，唱的是歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把复合材料很轻。", "corrected_sentence": "这块复合材料很轻。", "error_description": "错误形式：「这把复合材料」，量词错误。正确形式：「这块复合材料」。「把」用于有柄、可握持的器具，材料要用「块」等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂用了这批复合材料了做三个箱子。", "corrected_sentence": "工厂用了这批复合材料做三个箱子。", "error_description": "错误形式：「用了这批复合材料了做三个箱子」，「复合材料」后多出一个「了」。正确形式：「用了这批复合材料做三个箱子」。「了」只需出现一次，紧跟动词「用」即可，不能再插在宾语与「做」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使重量变大，与“减轻”构成反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "与“减轻”没有反义关系，“生长”的意思是长大。"}, {"text": "建造", "is_correct": false, "explanation": "与“减轻”没有反义关系，“建造”的意思是修建。"}, {"text": "讨论", "is_correct": false, "explanation": "与“减轻”没有反义关系，“讨论”的意思是交流意见。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使重量变大，与“减轻”构成反义关系。", "生长": "与“减轻”没有反义关系，“生长”的意思是长大。", "建造": "与“减轻”没有反义关系，“建造”的意思是修建。", "讨论": "与“减轻”没有反义关系，“讨论”的意思是交流意见。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使重量变大，与“减轻”构成反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "与“减轻”没有反义关系，“观察”的意思是仔细看。"}, {"text": "完成", "is_correct": false, "explanation": "与“减轻”没有反义关系，“完成”的意思是做成某件事。"}, {"text": "发展", "is_correct": false, "explanation": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使重量变大，与“减轻”构成反义关系。", "观察": "与“减轻”没有反义关系，“观察”的意思是仔细看。", "完成": "与“减轻”没有反义关系，“完成”的意思是做成某件事。", "发展": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变少或变轻。", "primary_collocate": null, "pronunciation": "jiǎn qīng", "ipa": "tɕjɛn˨˩ tɕʰiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "他拿出两本书，减轻了背包的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了跑得快，运动员减轻了鞋子的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机比旧手机减轻了五十克。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把箱子里的东西拿出来一些，就能减轻重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新材料减轻了汽车的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山前我们减轻了行李的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，想减轻体重。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包太重了，请把它减轻一点。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车减轻了两百公斤，开起来更快。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新桌子用了轻木头，减轻了不少重量，一个人就能搬。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减轻了", "label": "完成体"}, {"form": "减轻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使东西的重量变轻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增加", "is_correct": false, "explanation": "语义：句中“拿出两本书”会使背包变轻，“增加”使重量变大，与句意矛盾。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”指使分量变大，与“拿出两本书”的动作矛盾。"}, {"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”用于范围、规模，不修饰重量，“扩大了背包的重量”不通。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使重量变轻，与“拿出两本书”的动作一致。"}], "explanations": {"增加": "语义：句中“拿出两本书”会使背包变轻，“增加”使重量变大，与句意矛盾。", "加重": "语义：“加重”指使分量变大，与“拿出两本书”的动作矛盾。", "扩大": "搭配：“扩大”用于范围、规模，不修饰重量，“扩大了背包的重量”不通。", "减轻": "“减轻”指使重量变轻，与“拿出两本书”的动作一致。"}, "sentence_index": 0, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的员工减轻了一百人。", "explanation": "这里应该用〈减少〉。减少用于人数、数量；减轻用于重量，不用于人数。"}, {"text": "河水的水位减轻了两米。", "explanation": "这里应该用〈降低〉。水位的下降用“降低”；减轻表示重量变轻，不用于水位。"}, {"text": "这条新路减轻了三公里的路程。", "explanation": "这里应该用〈缩短〉。路程的缩减用“缩短”；减轻表示重量变轻，不用于路程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支撑", "is_correct": false, "explanation": "搭配：“支撑”多指承托，跑步的目的不是承托体重。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘”指忘记，不能与“体重”组成想要达到的目的。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开，与“每天跑步，想……体重”的目的不合。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使体重变轻，与“每天跑步”的目的一致。"}], "explanations": {"支撑": "搭配：“支撑”多指承托，跑步的目的不是承托体重。", "遗忘": "语义：“遗忘”指忘记，不能与“体重”组成想要达到的目的。", "逃避": "语义：“逃避”指躲开，与“每天跑步，想……体重”的目的不合。", "减轻": "“减轻”指使体重变轻，与“每天跑步”的目的一致。"}, "sentence_index": 6, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子减轻了一半。", "explanation": "这里应该用〈缩小〉。缩小用于面积、空间；减轻用于重量、负担，不能用于房间。"}, {"text": "药物减轻了病毒的活性。", "explanation": "这里应该用〈削弱〉。削弱用于活性、力量；减轻不用于病毒的活性。"}, {"text": "这个方法减轻了工作效率。", "explanation": "这里应该用〈提高〉。提高用于效率、水平；减轻不能用于效率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这箱苹果减轻了了两公斤。", "corrected_sentence": "这箱苹果减轻了两公斤。", "error_description": "“了”重复：“减轻”后只用一个“了”，应说“减轻了两公斤”，不能说“减轻了了两公斤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个箱子很减轻了三公斤。", "corrected_sentence": "这个箱子减轻了三公斤。", "error_description": "副词位置错误：“很”是程度副词，不能修饰动词“减轻”。应去掉“很”，说“这个箱子减轻了三公斤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
