INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西能用很久不会坏。", "primary_collocate": null, "pronunciation": "nài jiǔ xìng", "ipa": "nai˥˩ tɕjoʊ˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这双鞋的耐久性很好，穿了三年还像新的。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买书包时，我最看重耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的耐久性不太好。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桌的耐久性比纸盒高多了。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用的玩具，耐久性很重要。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子耐久性强，摔了也不会坏。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员说这块手表的耐久性很高。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先试一试这条绳子的耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买东西不看价格，只看耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种雨伞的耐久性怎么样？", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "东西经久耐用、不容易坏的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c52c201-a9c6-4f97-a07d-ccfe566aedfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能用来评价鞋子的好坏，与“穿了三年还像新的”矛盾。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“很好”用来评价质量，不能修饰体积。"}, {"text": "耐久性", "is_correct": true, "explanation": "正确：“耐久性很好”指鞋子能长期穿而不坏，与“穿了三年还像新的”一致。"}, {"text": "温度", "is_correct": false, "explanation": "语义：鞋子的温度与“穿了三年还像新的”的耐用语境无关，句意不通。"}], "explanations": {"年龄": "语义：“年龄”不能用来评价鞋子的好坏，与“穿了三年还像新的”矛盾。", "体积": "搭配：“很好”用来评价质量，不能修饰体积。", "耐久性": "正确：“耐久性很好”指鞋子能长期穿而不坏，与“穿了三年还像新的”一致。", "温度": "语义：鞋子的温度与“穿了三年还像新的”的耐用语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "耐久性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的耐久性很大，能装下二十件衣服。", "explanation": "这里应该用〈容量〉。能装多少东西是容量；耐久性指长期使用不坏的能力，不能用来说能装多少。"}, {"text": "这位老人的耐久性很好，每天都走很远的路。", "explanation": "耐久性用于物体或系统，不用于人；人的持久力要说耐力，这里用“耐久性”指人是错的。"}, {"text": "这台冰箱的耐久性是白色的。", "explanation": "这里应该用〈颜色〉。颜色是外观属性；耐久性是抽象的性能，不能说“是白色的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“很高”说程度，颜色一般不说高低，“颜色很高”不成立。"}, {"text": "语气", "is_correct": false, "explanation": "语义：店员的语气与手表的性能无关，“语气很高”句意不通。"}, {"text": "耐久性", "is_correct": true, "explanation": "正确：“很高”评价耐久性的程度，符合店员推荐产品的语境。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”只用于人，不能用来形容手表。"}], "explanations": {"颜色": "搭配：“很高”说程度，颜色一般不说高低，“颜色很高”不成立。", "语气": "语义：店员的语气与手表的性能无关，“语气很高”句意不通。", "耐久性": "正确：“很高”评价耐久性的程度，符合店员推荐产品的语境。", "性格": "语义：“性格”只用于人，不能用来形容手表。"}, "sentence_index": 6, "correct_answer": "耐久性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的耐久性能吊起两百斤。", "explanation": "这里应该用〈强度〉。能承受多大的拉力是强度；耐久性指长期使用中保持性能。"}, {"text": "工人把耐久性装进了箱子。", "explanation": "这里应该用〈东西〉。装进箱子的是具体的物品；耐久性是产品的性能，不是可以被装的东西，不能说“把耐久性装进箱子”。"}, {"text": "这台电脑的耐久性比那台快一倍。", "explanation": "这里应该用〈运行速度〉。快一倍说的是运行快慢；耐久性指东西能用很久不坏，不能用来比较快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款跑鞋有一双很好的耐久性。", "corrected_sentence": "这款跑鞋有一种很好的耐久性。", "error_description": "量词错误：错误形式为“一双”，正确形式为“一种”。“双”用于成对的东西，如鞋子；抽象的耐久性应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器是很好的耐久性。", "corrected_sentence": "这台机器有很好的耐久性。", "error_description": "动词错误：错误形式为“是”，正确形式为“有”。“有”表示拥有某种性能，“是”不能用来引出这种抽象性质。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc660105-7b1d-4282-8999-f7a8d96d7e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
