INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西原来的样子。", "primary_collocate": null, "pronunciation": "yuán xíng", "ipa": "ɥɛn˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座老房子已经看不出原型了。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修好以后，这辆旧自行车恢复了原型。", "target_word": "原型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多次改造，老戏台失去了原型。", "target_word": "原型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的古镇还保持着原型。", "target_word": "原型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把闹钟拆开后，就再也看不出原型了。", "target_word": "原型", "complexity_tier": "T3", "furigana": "dìdi bǎ nàozhōng chāi kāi hòu, jiù zài yě kàn bu chū yuánxíng le.", "sentence_source": "generated"}, {"text": "这盏灯只剩下灯座，没有原型了。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师傅照着旧照片，推断出钟的原型是什么样。", "target_word": "原型", "complexity_tier": "T3", "furigana": "lǎo shīfu zhàozhe jiù zhàopiàn, tuīduàn chū zhōng de yuánxíng shì shénme yàng.", "sentence_source": "generated"}, {"text": "房子改了三次，没人记得原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要保护古城墙的原型。", "target_word": "原型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地震后，这座桥完全看不出原型了。", "target_word": "原型", "complexity_tier": "T3", "furigana": "dìzhèn hòu, zhè zuò qiáo wánquán kàn bu chū yuánxíng le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "原型：东西原来的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指东西原来的样子，此处是“看不出原来样子”的意思。"}, {"text": "原子", "is_correct": false, "explanation": "语义：原子是微观粒子，与老房子的外观无关。"}, {"text": "原野", "is_correct": false, "explanation": "搭配：“看不出”一般搭配外形或痕迹，“原野”指大片土地，不能被“看出”。"}, {"text": "原告", "is_correct": false, "explanation": "语义：原告指法律上提起诉讼的一方，与房屋外观无关。"}], "explanations": {"原型": "原型：指东西原来的样子，此处是“看不出原来样子”的意思。", "原子": "语义：原子是微观粒子，与老房子的外观无关。", "原野": "搭配：“看不出”一般搭配外形或痕迹，“原野”指大片土地，不能被“看出”。", "原告": "语义：原告指法律上提起诉讼的一方，与房屋外观无关。"}, "sentence_index": 0, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家老店经过装修，原型大变，老客人都认不出来了。", "explanation": "这里应该用〈面貌〉。“面貌”指外观，可以说“面貌大变”；“原型”指东西原来的样子，不能说“原型大变”。"}, {"text": "这道题的原型很难。", "explanation": "这里应该用〈难度〉。“原型”指东西原来的样子，不能用来说题目的难易。"}, {"text": "这栋老房子只剩下一扇原型。", "explanation": "这里应该用〈个〉。“扇”用于门窗，“原型”要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指钟原来的样子，与“照着旧照片推断”的语境相符。"}, {"text": "原意", "is_correct": false, "explanation": "搭配：“是什么样”询问外形，“原意”指意思，不能用来描述钟的样子。"}, {"text": "原汁", "is_correct": false, "explanation": "语义：原汁指液体的原味，与钟的外观无关。"}, {"text": "原油", "is_correct": false, "explanation": "语义：原油是石油原料，不能指钟的外观。"}], "explanations": {"原型": "原型：指钟原来的样子，与“照着旧照片推断”的语境相符。", "原意": "搭配：“是什么样”询问外形，“原意”指意思，不能用来描述钟的样子。", "原汁": "语义：原汁指液体的原味，与钟的外观无关。", "原油": "语义：原油是石油原料，不能指钟的外观。"}, "sentence_index": 6, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生取走了一份血液原型。", "explanation": "这里应该用〈样本〉。原型指东西原来的样子，不指从身上取下的实物样本。"}, {"text": "他把妹妹的原型送给了朋友。", "explanation": "这里应该用〈照片〉。“原型”指东西原来的样子，不能指可以送人的实物，要说“照片”。"}, {"text": "他手里拿着一条原型。", "explanation": "这里应该用〈个〉。“条”用于细长的物体，“原型”要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修缮以后，这座旧城门依然能看出它的一只原型。", "corrected_sentence": "修缮以后，这座旧城门依然能看出它的原型。", "error_description": "量词错误：“原型”不用“只”。错误形式：它的一只原型；正确形式：它的原型（若要加量词，用“个”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅把这个钟的原型记来下了。", "corrected_sentence": "师傅把这个钟的原型记下来了。", "error_description": "补语位置错误：“记下来”中“下来”须紧跟动词之后。错误形式：记来下；正确形式：记下来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
