INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边界层是靠近一个东西表面的一层薄薄的空气或水。", "primary_collocate": null, "pronunciation": "biān jiè céng", "ipa": "pjɛn˥ tɕjɛ˥˩ tsʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "空气碰到机翼，表面就有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层是紧贴机翼的一层薄空气。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流过船底时，船底会有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了边界层的样子。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车开得越快，车身旁的边界层越明显。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这层边界层很薄，眼睛看不见。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞实验可以让我们看到边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层里的空气比外面的空气走得慢。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在学习什么是边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的翅膀上总是有边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊界層", "label": "繁体"}, {"form": "层流边界层", "label": "复合"}], "register": "通用", "sense_fingerprint": "紧贴物体表面的一层薄空气或水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b777eb8-5c72-40a7-b82c-0975259d6e64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”指紧贴物体表面的一层薄空气或水，空气碰到机翼时表面会有它，句意通顺。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能像一层东西那样附着在机翼表面，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能附着在机翼表面形成一层。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能用量词“层”来计量，“一层温度”不能说。"}], "explanations": {"边界层": "“边界层”指紧贴物体表面的一层薄空气或水，空气碰到机翼时表面会有它，句意通顺。", "声音": "语义：声音不能像一层东西那样附着在机翼表面，句子说不通。", "时间": "语义：时间是抽象概念，不能附着在机翼表面形成一层。", "温度": "搭配：“温度”不能用量词“层”来计量，“一层温度”不能说。"}, "sentence_index": 0, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗户上贴着一层边界层，可以挡住灰尘。", "explanation": "这里应该用〈薄膜〉。薄膜是可以贴在物体表面的薄片，边界层是紧贴物体表面的薄层，不能贴在窗户上挡尘。"}, {"text": "两国的边界层很清楚。", "explanation": "这里应该用〈分界线〉。分界线指两地之间的界线，边界层指紧贴物体表面的薄层，不指国与国之间的分界。"}, {"text": "机翼表面有一只边界层。", "explanation": "这里的量词“只”用于某些动物或成对的东西，如一只鸟，不能用于边界层。边界层是一层薄薄的空气，应该用量词“层”，说“一层边界层”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”是紧贴物体表面的薄层，风洞实验里可以看到它，句意通顺。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，不能用“看到”来说。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看到”不搭配“味道”，味道要用嗅觉感知。"}, {"text": "手感", "is_correct": false, "explanation": "搭配：“手感”要用触摸感知，不能与“看到”搭配。"}], "explanations": {"边界层": "“边界层”是紧贴物体表面的薄层，风洞实验里可以看到它，句意通顺。", "声音": "语义：声音看不见，不能用“看到”来说。", "味道": "搭配：“看到”不搭配“味道”，味道要用嗅觉感知。", "手感": "搭配：“手感”要用触摸感知，不能与“看到”搭配。"}, "sentence_index": 6, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的边界层很开朗。", "explanation": "这里应该用〈性格〉。开朗形容人的性格，边界层是流体紧贴固体表面的薄层，不能用来形容人。"}, {"text": "这个机器的边界层很硬。", "explanation": "这里应该用〈外壳〉。外壳指机器外面包着的硬壳，边界层是流体的薄层，不是机器的部件。"}, {"text": "这篇文章的边界层很清楚。", "explanation": "这里应该用〈层次〉。层次指文章的条理和结构，边界层是物理概念，不用来说明文章结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空气流过机翼时，表面附近形成一根边界层。", "corrected_sentence": "空气流过机翼时，表面附近形成一层边界层。", "error_description": "量词错误：“边界层”是一层薄薄的空气，应用量词“层”；“根”用于细长的东西，不能用于边界层，应说“一层边界层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风吹过树叶时，叶子表面附近会有一根很薄的边界层。", "corrected_sentence": "风吹过树叶时，叶子表面附近会有一层很薄的边界层。", "error_description": "量词错误：“边界层”是一层薄薄的空气，应用量词“层”；“根”用于细长的东西，不能用于边界层，应说“一层很薄的边界层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2809384-bf44-4a6b-a3ac-434bc84eb989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
